4.주제만들기: 
장자권을 빼앗긴 사실을 알고 슬퍼하는 에서

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
별미를 만들어 아버지 이삭에게 가지고온 에서
야곱이 장자 축복권을 속여 받은것을 알게된 이삭과 에서
이 사실을 알고 분노하고 슬피우는 에서

7.하나님 찾기(해석)

8.인간 찾기 (해석)
32절에 "너는 누구냐" 라는 말이 깊이 세겨진다.  육적으로 장남으로 태어낳지만 장자의 명분을 경이 여겨서 장자로써의 축복권을 빠앗기고만 에서이다.

너는 누구냐? 의 말에 에서의 소리높여 울었던 그의 비통함의 현실을 더욱 느끼게된다.  이 모습을 보면서 복음의 본질 즉 구원의 확신 그리고 천국의 소망을 매일 매일 붙잡고 깨우치며 감사한 마음으로 산다는 것이 얼마나 중요한지 알게된다.

세상의 즐거움과 성공을 쫓다가 갑작스런 육의 죽음을 맞이할 때 아버지 하나님께서 분명 물으실 것이다!!

너는 누구냐?  무엇을 행하였느냐? 영적 미숙함과  둔함이 에서의 장자로써의 명분을 누리지 못하도록 막았다. 물론 미래의 시간도 통치하시는 하나님께서는 이 또한 예견하셨었다.  그럼에도 에서편에서 본다면 장자의 명분을 귀하게 여겨야 했던 것은 분명하다.

중요한 축복의 특권을 알지 못 체  세상의 것만을 따라 간다면 슬피우는 사람이 될 수 있음을 알려준다.

9.적용(나):
무엇보다 중요한 하나님의 자녀의 신분의 특권을 꼭 붙잡고  살아야겠다 

10. 영적터치 (단어 또는 구절)
32절: 너는 누구냐

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-19', '창세기', '27장 41절 ~ 46절', '', '(창세기 27장)
41. 그의 아버지가 야곱에게 축복한 그 축복으로 말미암아 에서가 야곱을 미워하여 심중에 이르기를 아버지를 곡할 때가 가까웠은즉 내가 내 아우 야곱을 죽이리라 하였더니
42. 맏아들 에서의 이 말이 리브가에게 들리매 이에 사람을 보내어 작은 아들 야곱을 불러 그에게 이르되 네 형 에서가 너를 죽여 그 한을 풀려 하니
43. 내 아들아 내 말을 따라 일어나 하란으로 가서 내 오라버니 라반에게로 피신하여
44. 네 형의 노가 풀리기까지 몇 날 동안 그와 함께 거주하라
45. 네 형의 분노가 풀려 네가 자기에게 행한 것을 잊어버리거든 내가 곧 사람을 보내어 너를 거기서 불러오리라 어찌 하루에 너희 둘을 잃으랴
46. 리브가가 이삭에게 이르되 내가 헷 사람의 딸들로 말미암아 내 삶이 싫어졌거늘 야곱이 만일 이 땅의 딸들 곧 그들과 같은 헷 사람의 딸들 중에서 아내를 맞이하면 내 삶이 내게 무슨 재미가 있으리이까

