3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 10월13일 창세기 27장41절~46절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
죽이리라/죽여/잃으랴: 41절 42절 45절
일어나/가서/피신하여/거주하라: 43절(3) 44절
축복: 41절(2)
노/분노/한: 42절 44절 45절

4.주제만들기: 
지혜로운 중재자 리브가

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
야곱을 죽이려 마음먹은 형 에서.
그러한 에서의 마음을 들은 리브가.
야곱을 하란에 있는 오라버니 라반에게 피신시키려하는 리브가.
남편 이삭에게 야곱을 떠나보내는 이유를 말하는 리브가.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
동생 야곱을 죽일 것이라 외치는 형 에서의 분노를 알고 야곱을 피신 시키는 리브가의 모습을 볼수있다.

뿐만아니라 남편 이삭을 지혜롭게 설득하여 아들 야곱을 하란에 있는 라반에게 보내려한다.

리브가는 두 아들의 기질을 엄마로써 누구보다도 잘 알고 있었을 것이다. 또한 에서가 이렇게까지 분을 낼 것도 이미 짐작 했을 것이다.

자녀들의 큰 불협 화음의 고통을 알면서도 리브가는 하나님의 예정하심, 주권을 따랐다고 볼수있다 

순종하는 과정에서 큰 충돌을 피하고 중재 역할을  대처하는 리브가가 대범하면서도 대단하게 느껴진다.

만약 리브가가 가인과 아벨의 어미였다면 당시에 가인이 동생 아벨을 살인하지 못하도록 지혜를 사용하지 않았을까 생각해본다.

그럼에도 진정한 중재자는 우리 주님이신 것을 상고해본다. 죽음이 우리의 문턱으로 넘어오지 못하도록 그분의 피의 십자가로 막아주시고 우리를 살리신  위대한 중재자 이심에 감사를 올린다.

9.적용(나):
지혜로운 중재자가 되도록 노력해야겠다 

