6. 인간 찾기 (관찰)
- 이삭은 야곱을 불러 축복하고 당부함
- 가나안 사람 중 딸들을 맞이하지 말고 네 외조부 브두엘의 라반의 딸 중 아내를 맞이하라 함
- 이삭은 야곱에게 아브라함에게 허락하신 복을 야곱에게 주기를 바람
- 야곱은 밧단아람으로 가서 라반을 만남
- 에서는 야곱이 가나안 사람 중 딸을 맞이하지 말라는 것과 부모의 명을 따라 밧단아람으로 간 것을 보고 자신의 아내가 아버지 이삭을 기쁘게 못하는 것을 깨닫고 이스마엘에게 가서 이스마엘의 딸을 아내로 맞이함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 야곱은 이삭과 리브가에게 충성스러운 아들이었던 것 같다. 부모에게 충성스러운 모습을 보인 아들이었기에 이삭은 야곱이 잘못된 행동을 했더라도 그를 다시 축복하고 당부하며 아들을 위해 아브라함의 복까지 빌어준다. 
- 반면 에서는 야곱의 행동을 통해 자신의 잘못을 깨닫는다. 이방 여인을 아내로 맞이한 것을 후회했을 수도 있다. 그리고 이스마엘을 찾아 마할랏을 아내로 맞이했다. 추측건데 에서는 부모님의 명령에 순종하지 않던 아들이었을 것이다. 그런데 하나님께선 야곱을 선택하셔서 축복을 주시고 에서를 버린 것과 같이 보여지지만, 실제론 에서를 살리는 선택을 하신 것이다. 
- 훗날 야곱이 돌아올 때 에서가 야곱을 용서한 것 같이 에서가 올바른 신앙관으로 살아갈 수 있는 하나님의 가장 강력한 처방이었을 것이다. 
9. 적용(나): 
- 고난이 찾아올 때 그것이 나를 지켜주시는 하나님의 보호하심이었다는 사실에 감사하다. 죄에서 벗어나 하나님의 뜻에 맞게 살아가려 끊임없이 노력해야겠다. 
