4.주제 만들기: 야곱이 벧엘에서 하나님을 만나다

5.하나님 찾기 (관찰)
- 야곱에게 아브라함과 이삭에게 한 약속을 네게 이루실 것임을 말씀하심
- 너와 함께 있어 어디로 가든지 지키며, 이 땅으로 돌아오게 할 것이라 말씀하심
- 네가 말한 것을 다 이루기까지 야곱을 떠나지 않을 것이라 말씀하심

6.인간 찾기 (관찰)
- 한 곳에 이르러 돌을 가져다가 베개로 삼고 누워 잠듬
- 꿈에서 사닥다리와 천사들 그리고 그 위에 서 계시는 하나님의 환상을 봄
- 잠에서 깨어 여호와께서 과연 여기 계심을 깨달음
- 이 곳을 하나님의 집이요 하늘의 문이라 부름
- 아침 일찍 일어나 베개로 삼았던 돌로 기둥을 세우고 그 위에 기름을 붓고
- 그 곳 이름을 벧엘이라 부름
- 하나님께 서원함

7.하나님 찾기 (해석) 
- 에서를 피해 도망하듯 외삼촌 집으로 향하던, 절망에 빠진 야곱에게 나타나심
- 아브라함과 이삭에게 한 약속을 야곱을 통해 이루실 것을 말씀해 주심
- 지키고, 돌아오게 하며, 떠나지 않으시겠다는 말씀으로 야곱을 위로하고 평안케 하심

8.인간(해석)
- 야곱은 자신의 상황에 낙심하고 절망에 빠져 돌 베개를 의지하여 잠이 들었을 것임
- 할아버지와 아버지의 하나님에 대해 듣기만 했던 야곱은 
- 오늘 그 하나님을 뵙고 너무나 기뻤을 것임
- 절망은 희망으로 바뀌고 하나님을 의지하고 외삼촌에게 갈 힘을 얻었을 것임
- 하나님을 만난 기쁨에 기둥을 세위고 기름을 붓고 그 곳을 벧엘이라 불렀으니,
- 그 뜻은 하나님의 집이다
- 하나님의 말씀이 너무나 감사하고 위로가 되고, 힘을 얻었으나,
- 그 말씀을 정말로 이루시면 
- 여호와께서 나의 하나님이 되실 것이요
- 이 돌이 하나님의 집이 될 것이요
- 주신 모든 것에서 십분의 일을 반드시 드리겠다 말함.
- 하나님께 조건을 다는 것으로 보아 아직 성숙하지 못해 보이지만, 
- 또 한편으로는 하나님 밖에는 의지할 분이 없어서 강력히 의지하는 모습으로 보임.
- (제발 저와 함께 해주세요. 하나님이 없으면 저는 죽습니다.)

9.적용(나)
- 낙심한 자, 애통하는 자, 절망에 빠진 자와 함께 하시는 하나님을 기억해야 한다.
- 간절하게 하나님 한 분만 의지해야 한다.

10. 영적터치(단어/구절)  
  15   내가 너와 함께 있어 네가 어디로 가든지 너를 지키며 너를 이끌어 이 땅으로 돌아오게 할지라 내가 네게 허락한 것을 다 이루기까지 너를 떠나지 아니하리라 하신지라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-22', '창세기', '29장 1절 ~ 10절', '', '(창세기 29장)
1.  야곱이 길을 떠나 동방 사람의 땅에 이르러
2. 본즉 들에 우물이 있고 그 곁에 양 세 떼가 누워 있으니 이는 목자들이 그 우물에서 양 떼에게 물을 먹임이라 큰 돌로 우물 아귀를 덮었다가
3. 모든 떼가 모이면 그들이 우물 아귀에서 돌을 옮기고 그 양 떼에게 물을 먹이고는 우물 아귀 그 자리에 다시 그 돌을 덮더라
4. 야곱이 그들에게 이르되 내 형제여 어디서 왔느냐 그들이 이르되 하란에서 왔노라
5. 야곱이 그들에게 이르되 너희가 나홀의 손자 라반을 아느냐 그들이 이르되 아노라
6. 야곱이 그들에게 이르되 그가 평안하냐 이르되 평안하니라 그의 딸 라헬이 지금 양을 몰고 오느니라
7. 야곱이 이르되 해가 아직 높은즉 가축 모일 때가 아니니 양에게 물을 먹이고 가서 풀을 뜯게 하라
8. 그들이 이르되 우리가 그리하지 못하겠노라 떼가 다 모이고 목자들이 우물 아귀에서 돌을 옮겨야 우리가 양에게 물을 먹이느니라
9. 야곱이 그들과 말하는 동안에 라헬이 그의 아버지의 양과 함께 오니 그가 그의 양들을 치고 있었기 때문이더라
10. 야곱이 그의 외삼촌 라반의 딸 라헬과 그의 외삼촌의 양을 보고 나아가 우물 아귀에서 돌을 옮기고 외삼촌 라반의 양 떼에게 물을 먹이고

