7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱은 형 에서의 위협을 피하여 무작정 외삼촌이 사는 하란으로  떠났다. 떠나기 전에 아버지 이삭이 야곱에게 말하기를 "라반의 딸 중에서 아내를 맞이하라" 말한 것을 받아들이고 순종하였다.

야곱은  길에서 우연히 라반이 사는 하란의 사람들 즉 그곳의 목자들을 만난다. 그뿐만 아니라 라반의  딸들중 라헬이 양을 치기 위해 직접 몰고 야곱이 있는 곳으로 오고 있다는 말을 전해 듣는다.

 사실 우연히 이러한 일들이 이루어진 것처럼 보이지만 우연이 아니라 하나님의 섬세한 역사 하심을 알 수 있다.

특별히 라반의 딸 중 한 명인 라헬이 그를 향하여 다가온다는 사실은 마치 하나님의 자녀가 말씀에 순종하여 나아가면 하나님은 더 빠른 걸음으로 그 자녀를 향하여 다가오심을 깨우친다.

