5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 라헬에게 입맞추고 우는 야곱
- 야곱이 리브가의 아들 됨을 말함
- 라헬이 달려가 그 아버지에게 아림
- 라반이 달려와 야곱을 영접하고 집으로 데리고 옴
- 야곱이 자기의 모든 일을 라반에게 말함
- 라반이 너는 참으로 내 혈육이다라고 말하고 한 달을 함께 거주함
- 라반이 야곱에게 품삯을 어떻게 할지 말하라고 함
- 야곱이 라헬을 사랑하므로 칠 년을 섬기겠다 말함
- 라반이 받아들임
- 야곱이 라헬을 위하여 칠 년 동안 라반을 섬겼으나 그를 사랑하기 때문에 칠 년을 며칠 같이 여겼다  

7.하나님 찾기(해석)

8.인간 찾기 (해석)
- 한 번도 본 적 없는 외삼촌을 찾아 나선 야곱이 라반의 딸 라헬을 만나 기뻐함
- (에서를 피해 집을 나선 야곱은 과연 외삼촌을 만날 수 있을까 두려움이 있었을 것이다.) 
- 라헬이 야곱의 말을 듣고 반가워 라반에게 알리러 달려감
- 라헬의 말을 듣고 라반도 반가워 야곱에게 달려감
- 라반이 야곱을 집으로 데려가니 야곱의 지난 일을 모두 이야기함
- 이삭과 리브가가 자기를 외삼촌에게 보낸 것과 에서와의 일을 다 이야기 했을 것임
- 이 말을 듣고 라반이 너는 참으로 내 혈육이다고 말함
- 한 달을 함께 거주하다가 라반이 야곱에게 품삯에 대해 말함
- 야곱읍 두 딸 레아와 라헬 중 곱고 아리따운 라헬을 사랑하였으므로
- 라헬을 위하여 칠 년을 섬기겠다고 말함
- 라반은 그 말이 마음에 들었고 받아들임
- 야곱이 라헬을 사랑하여 칠 년이 며칠 같이 여겨짐 

9.적용(나)
- 벧엘에서 야곱을 만나주셨고,
- 야곱이 라반을 만나도록 인도해 주셨다.
- 내가 보기에 내 삶이 순탄하지 않더라도
- 하나님께서는 나를 순조롭게 인도하고 계신다는 것을 믿어야한다. 

