4. 주제만들기
- 깨우치게 하시는 하나님
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 야곱은 외삼촌 라반에게 약속한 기한이 찼으니 라헬을 아내로 줄 것을 요구함
- 라반은 잔치를 열고 레아를 야곱에게 데려감
- 야곱은 아침이 돼서야 레아인 것을 확인하고 라반에게 따짐
- 라반은 언니보다 아우를 먼저 주는 것은 자신의 지방에서 하지 않는 일이라며 칠 일을 참고 라헬을 줄테니, 칠년을 더 섬기라고 함
- 칠일 후 야곱은 라헬을 아내로 맞이하고 라헬을 사랑하여 칠년 동안 라반을 섬김
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 야곱은 외삼촌인 라반에게 속았다. 야곱이 자신의 형을 속인 것처럼 이번엔 외삼촌인 라반을 통해 야곱이 속임을 당하게 되었다. 하나님께선 속았다는 것을 통해 느끼는 분노, 배신감을 야곱에게 깨닫게 하셨다. 자신의 형 에서가 느꼈을 분노와 배신감은 이보다 더 컸으리라
- 외삼촌인 라반은 순간적인 판단인지, 계획된 행동인지는 모른다. 하지만 자신의 첫째 딸을 걱정했던 것 같다. 레아는 시력이 약했는지 이것이 장애를 뜻하는지는 모르겠으나 레아를 책임질 남편을 구하지 못했을 수 있다. 칠년 동안 야곱을 살펴본 라반은 야곱 정도라면 자신의 첫째 딸을 맡겨도 되겠다는 판단을 했을 것이다. 
- 하나님께선 야곱에게 깨달음을 라반에겐 부모로서 걱정을 덜게 하셨다. 내가 생각하는 최악의 상황, 가족에게 당하는 일이라도 하나님께선 선하게 사용하신다.
9. 적용(나): 
- 나에게 일어나는 모든 일들을 나의 시선에서만 해석하지 말고 하나님의 뜻을 구하며 하나님께 물어보자
10. 영적터치(단어/구절)
- 25절 나를 속이심은 어찌 됨이니이까
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-25', '창세기', '29장 31절 ~ 35절', '', '(창세기 29장)
31.  여호와께서 레아가 사랑 받지 못함을 보시고 그의 태를 여셨으나 라헬은 자녀가 없었더라
32. 레아가 임신하여 아들을 낳고 그 이름을 르우벤이라 하여 이르되 여호와께서 나의 괴로움을 돌보셨으니 이제는 내 남편이 나를 사랑하리로다 하였더라
33. 그가 다시 임신하여 아들을 낳고 이르되 여호와께서 내가 사랑 받지 못함을 들으셨으므로 내게 이 아들도 주셨도다 하고 그의 이름을 시므온이라 하였으며
34. 그가 또 임신하여 아들을 낳고 이르되 내가 그에게 세 아들을 낳았으니 내 남편이 지금부터 나와 연합하리로다 하고 그의 이름을 레위라 하였으며
35. 그가 또 임신하여 아들을 낳고 이르되 내가 이제는 여호와를 찬송하리로다 하고 이로 말미암아 그가 그의 이름을 유다라 하였고 그의 출산이 멈추었더라

