2024년 10월19일 창세기 29장31절~35절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
레아:31절 32절 33절(2) 34절(2) 35절(3)
사랑 받지 못함/괴로음: 32절(2) 33절 34절
아들을 낳고: 32절 33절 34절 35절
이제는: 32절 35절

4.주제만들기: 
비운의 여인에서 축복의 여인으로

5.하나님 찾기 (관찰)
레아의 태를 열어 주신 여호와

6.인간 찾기(관찰)
남편에게 사랑을 받지 못하는 레아.
아들 네 명을 출산한 레아.
셋 째를 낳을때까지 슬퍼하는 레아.
네번째 아들 유다를 낳고 드디어 하나님을 찬송하는 레아.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
레아는 비운의 여인인 듯하다. 남편 야곱으로부터 사랑을 받지 못하였다. 그 사랑을 독차지한 것은 다름 아닌 자기 여동생 라헬이었다. 레아는 본인이 선택도 하지 않은 결혼 그것을 강요한 아버지 그리고 남편과 경쟁자가 된 여동생.

레아 입장이 되면 누구나 절망감을 느낄 것이다. 레아 역시 수년 동안 괴로워했음을 첫째부터 셋째아들까지 이름의 의미를 보고 알 수 있다. 남편으로부터 받고 싶은 사랑인데 그렇지 못하여 받는 비통함과 괴로움의 마음의 심정으로 대신하고 있다.

그러나 레아는 사랑의 대상을 남편에서 하나님께 돌렸다. 그래서 네 번째 아들의 의미인 "여호와를 찬양하리라" 유다로 지었다.

결국 레아는 세상에서 가장 비운의 여인 중 한 명에서 지혜롭고 축복받은 여인이 되었다.

하나님은 유다의 씨를 통하여 위대하신 예수그리스도를 계보에 오르도록 은혜를 베푸셨다.

진정한 축복은 주님만을 의지하고 찬양할 때 임을 깨우치게 한다.

9.적용(나):
어떠한 환경에서도 하나님을 챤양하는 복된 삶을 살아 내야겠다.

10. 영적터치 (단어 또는 구절)
35절: 여호와를 찬송 하리로다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-26', '창세기', '30장 1절 ~ 10절', '', '(창세기 30장)
1. 라헬이 자기가 야곱에게서 아들을 낳지 못함을 보고 그의 언니를 시기하여 야곱에게 이르되 내게 자식을 낳게 하라 그렇지 아니하면 내가 죽겠노라
2. 야곱이 라헬에게 성을 내어 이르되 그대를 임신하지 못하게 하시는 이는 하나님이시니 내가 하나님을 대신하겠느냐
3. 라헬이 이르되 내 여종 빌하에게로 들어가라 그가 아들을 낳아 내 무릎에 두리니 그러면 나도 그로 말미암아 자식을 얻겠노라 하고
4. 그의 시녀 빌하를 남편에게 아내로 주매 야곱이 그에게로 들어갔더니
5. 빌하가 임신하여 야곱에게 아들을 낳은지라
6. 라헬이 이르되 하나님이 내 억울함을 푸시려고 내 호소를 들으사 내게 아들을 주셨다 하고 이로 말미암아 그의 이름을 단이라 하였으며
7. 라헬의 시녀 빌하가 다시 임신하여 둘째 아들을 야곱에게 낳으매
8. 라헬이 이르되 내가 언니와 크게 경쟁하여 이겼다 하고 그의 이름을 납달리라 하였더라
9. 레아가 자기의 출산이 멈춤을 보고 그의 시녀 실바를 데려다가 야곱에게 주어 아내로 삼게 하였더니
10. 레아의 시녀 실바가 야곱에게서 아들을 낳으매

