아직 출산을 하지 못하는 라헬
이 일로 남편 야곱에게 분을내며 그의 시녀 빌하를 통하여 아들 두명을 출산시킨 라헬(단, 납달리)

7.하나님 찾기(해석)

8.인간 찾기 (해석)
라헬은 언니 레아와 달리 성품이 온화하지 못한 듯하다. 출산이 잘되지 않으니 남편 야곱을 향하여 강력하게 겁박하는 모습을 볼 수 있다. 그럴 뿐만 아니라 자신의 시녀 빌하를 남편에게 동침시켜 아들을 두 명이나 낳게 하였다. 그 아들을 자기 아들이라 여기며 잠시 만족하는 것 같다. 그들의 이름의 의미를 보면 알 듯하다.

사실 라헬은 아직 태의 문이 열리지는 못했지만, 남편 야곱으로부터 언니 레아 와 달리 사랑을 독차지하고 있었다. 그런데도 스스로 언니를 시기하고 경쟁자로 삼은 부분이 모든 발단의 시작점이라 여겨진다.

시련 중에 여호와 하나님을 깊이 체험하여 만족감을 얻은 레아와 달리 인간적인 본성을 붙잡고 있는 라헬을 보니 다소 아쉽다는 생각이 든다.

9.적용(나):
시기심을 경계하며 더욱 주님과 동행하는 것을 우선순위로 삼고 살아내야겠다 

