2024년 10월26일 창세기 31장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천):
도망: 21절 22절 27절
쫓다: 23절 25절 
선악간에 말하지 말라:24절 29절
어찌하여: 26절 27절
하나님: 24절 29절

4.주제만들기: 
도망자 야곱과 쫓는 라반

5.하나님 찾기 (관찰)
분노에 가득찬 라반의 꿈에 등장하사 중재 역활을 하시는 하나님.

6.인간 찾기(관찰)
라반으로부터 가족과 가축을 모아 고향으로  도망가는 야곱.
그 사실을 알고 뒤쫓는 라반.
야곱을 붙잡았으나 하나님 말씀대로 해치지 않는 라반.

7.하나님 찾기(해석)
라반에게 현몽하여 나타나신 하나님이 야곱을 지켜주신다.

하나님의 자녀가 위기를 맞닥 뜨리게 될때 주님은 지켜주신다.

8.인간 찾기 (해석)
외삼촌 라반의 안색이 전과 같지 않음을 보고 있을 때 하나님께서 야곱에게 고향으로 떠나라고 지시하신다.

그 말씀에 바로 순종하여 자신의 모든 가족과 가축들을 데리고 떠난다.

문제는 외삼촌 라반에게 말하지 않고 줄행랑을 치듯 떠났다는 것이다.

뒤늦게 그 사실을 알게 된 라반은 야곱을 죽일 기세로 추격한다. 야곱에게 당도하기 전에 하나님은 라반에게 현몽 가운데 나타나셔서 야곱을 헤치지 말도록 명령하셨다.

야곱을 만난 라반은 야곱을 헤칠 수 있었는데 하나님 때문에 참았다고 말한다. 그리고 고향에 간다고 했으면 축복 가운데 보내주었을 것이라 말하였다.

이 부분을 놓고 생각해 보게 된다.

하나님의 섭리 안에서 야곱을 고향으로 보낼 때가 됐기 때문에 일부러 라반의 마음을 강퍅하게 하나님이 만드신 것일까?

또한 아무리 하나님 지시가 있었더라도 라반에게 말도 않고 떠나는 것이 옳은 행동이었을까?

라반은 정말 야곱이 미리 상의하고 떠난다고 했으면 축복해주고 보내주었을까?

아마도 이러한 모든 부분은 순간순간 변할 수가 있는 인간의 마음과 흔들릴 수 있는 감정 기복일 것이다.

9.적용(나):
모든 상황을 도와 주시고 해결 하여 주시는 주님을 더욱 의지하며 살아내야겠다 

10. 영적터치 (단어 또는 구절)
29절: 너는 삼가 야곱에게 선악간에 말하지 말라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-29', '창세기', '31장 31절 ~ 40절', '', '(창세기 31장)
31. 야곱이 라반에게 대답하여 이르되 내가 생각하기를 외삼촌이 외삼촌의 딸들을 내게서 억지로 빼앗으리라 하여 두려워하였음이니이다
32. 외삼촌의 신을 누구에게서 찾든지 그는 살지 못할 것이요 우리 형제들 앞에서 무엇이든지 외삼촌의 것이 발견되거든 외삼촌에게로 가져가소서 하니 야곱은 라헬이 그것을 도둑질한 줄을 알지 못함이었더라
33. 라반이 야곱의 장막에 들어가고 레아의 장막에 들어가고 두 여종의 장막에 들어갔으나 찾지 못하고 레아의 장막에서 나와 라헬의 장막에 들어가매
34. 라헬이 그 드라빔을 가져 낙타 안장 아래에 넣고 그 위에 앉은지라 라반이 그 장막에서 찾다가 찾아내지 못하매
35. 라헬이 그의 아버지에게 이르되 마침 생리가 있어 일어나서 영접할 수 없사오니 내 주는 노하지 마소서 하니라 라반이 그 드라빔을 두루 찾다가 찾아내지 못한지라
36. 야곱이 노하여 라반을 책망할새 야곱이 라반에게 대답하여 이르되 내 허물이 무엇이니이까 무슨 죄가 있기에 외삼촌께서 내 뒤를 급히 추격하나이까
37. 외삼촌께서 내 물건을 다 뒤져보셨으니 외삼촌의 집안 물건 중에서 무엇을 찾아내었나이까 여기 내 형제와 외삼촌의 형제 앞에 그것을 두고 우리 둘 사이에 판단하게 하소서
38. 내가 이 이십 년을 외삼촌과 함께 하였거니와 외삼촌의 암양들이나 암염소들이 낙태하지 아니하였고 또 외삼촌의 양 떼의 숫양을 내가 먹지 아니하였으며
39. 물려 찢긴 것은 내가 외삼촌에게로 가져가지 아니하고 낮에 도둑을 맞았든지 밤에 도둑을 맞았든지 외삼촌이 그것을 내 손에서 찾았으므로 내가 스스로 그것을 보충하였으며
40. 내가 이와 같이 낮에는 더위와 밤에는 추위를 무릅쓰고 눈 붙일 겨를도 없이 지냈나이다

