4.주제만들기: 
드라빔을 숨긴 라헬

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
아버지 라반의 우상신 모형(드라빔)을 갖기위해 숨긴 라헬.
그 드라빔을 찾는 것을 실패한 라반.
그러한 라반에게 책망하는 야곱.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱이 38절에 말하기를 "내가 이 이십 년을 외삼촌과 함께하였거니와"를 통하여 라반과 함께한 세월이 꽤 길었음을 알 수 있다.

20년 동안 성실하게 수고했음에도 가족 내 분위기를 보면 서로를 신뢰하고 존중하는 마음은 작아보인다.

특별히 외삼촌 라반이나 아내 라반은 우상 신의 모형인 드라빔을 서로 쟁취하려는 것을 보면 하나님에 대해 믿음도 없어 보인다.

궁금한 것은 믿음의 사람이고 하나님께 일찍이 선택받은 야곱임에도 긴 세월 동안 가까운 가족들에게 오직 하나님만이 참 신 이신 것을 각인시켜주는 것은 쉽지 않았을까 생각하게 된다.

도리어 야곱에게 사랑받지
못했던 또 다른 아내인 레아는 하나님을 깊게 체험한 것을 아들 유다를 통해 알 수 있다.

내 주변에 믿는 사람이 스스로 신앙적 영향을 줄 거라고 기대하는 것도 좋은 생각이지만 더욱 분명한 것은 스스로 기도와 말씀을 통하여 주님을 깊이 만나는 것이 귀한 것 같다.

그런 면에서 하나님은 우리에게 ''고난''이라는 변장 된 축복을 종종 사용하시어 말씀 곁으로 인도 하시는 것 같다.

9.적용(나):
마음속에 하나님 외에 의지하는 드라빔이 있는지 살펴보고 있으면 과감하게 버려야겠다.

