3. 반복단어 찾기(형광펜 추천)
- 외삼촌(라반, 41,42,43,47,48절)
- 야곱(43,45,47절)
- 하나님(42,49,50절)
- 증거(44,48절)
4. 주제만들기: 보호하시는 하나님, 깨닫게 하시는 하나님, 증인되시는 하나님
5. 하나님 찾기 (관찰)
- 야곱의 고난과 수고를 살피시고 야곱을 쫓는 라반을 책망하심
6. 인간 찾기 (관찰)
- 라반이 드라빔을 못찾자 야곱은 그간의 일들을 라반에게 말함
- 낮에는 더위, 밤에는 추위, 눈 붙일 겨를이 없었던 것과 이십년 동안 두딸을 위해 14년 외삼촌의 양떼를 위해 6년을 봉사하는 동안 외삼촌은 품삯을 열 번이나 바꿨다고 책망함
- 라반은 야곱에게 내 딸들이고, 내 자식들이고, 내 양떼들인데 자신이 무엇을 하겠냐며 야곱에게 언약을 맺자고 함
- 야곱과 라반은 돌을 세워 언약을 하고 자신의 딸을 박대하거나 다른 아내를 맞이하여 둘 사이에 아무도 없어도 하나님께서 우리 사이의 증인이 될 것이라 말함
7. 하나님 찾기 (해석) 
- 하나님께선 20년 동안 야곱의 수고를 살피셨고, 야곱을 통해 라반과 야곱 모두 번성하게 하셨으며, 20년의 과정을 통해 야곱을 깨닫게 하셨고, 야곱 뿐만 아니라 라반도 깨닫게 하셨다. 하나님은 야곱과 라반의 중재자가 되셨는데 둘 사이의 증인이 되셔서 서로를 보호하고 지켜주셨다. 하나님의 끝없는 사랑, 보호하심을 느낄 수 있다.
8. 인간(해석):
- 야곱은 드라빔이 없자 라반을 향해 그간의 설움을 쏟아 놓는다. 그리고 20년의 세월을 어떻게 보냈는지 나열하며 자신이 얼마나 성실히 지내왔는지를 말한다. 야곱은 형 에서를 속이고 장자권을 얻어 쫓겨나듯이 라반에게 가던 중 하나님을 만났다. 야곱의 20년은 야곱이 자신의 잘못을 깨닫고 뉘우치고자 스스로 선택한 고난의 길이었을지도 모른다. 20년을 성실히 일한다는 것은 보통의 체력과 정신력으로는 할 수 없다. 
- 라반은 야곱의 책망을 듣고 놀랐을 것이다. 야곱을 만만하게 봐서 품삯을 열 번이나 바꿨는지, 아니면 라반의 본래 성품인지는 모르겠지만, 네가 보는 것이 모두 자신의 것이라고 말하는걸로 봐선 본래 성품일 수 있겠단 생각이 든다. 야곱이 불 같이 화를 내자 두려웠을 것이다. 거기서 라반은 꾀를 내어 하나님을 이용해 증인으로 세운다. 끝까지 빠져나갈 길을 찾은 라반이 속임수에선 야곱보다 한 수 위 같다. 
9. 적용(나): 
- 야곱이 경험한 과정을 통해 하나님께서 내 삶을 만져주심을 느낀다. 하나님께서 나를 살펴주셨고, 깨닫게 하셨다. 모든 상황에 증인이 되시는 하나님께 감사하다. 하나님을 의지하며 하나님께서 원하시는 길에서 벗어나지 말아야겠다.
10. 영적터치(단어/구절)
- 42절 하나님이 내 고난과 내 손의 수고를 보시고
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

