8.인간(해석)
- 라반이 잘 못을 깨닫고 돌기둥과 돌무더기를 증거로 삼고 야곱을 치지 않겠다고 약속함
- 하나님께 맹세함으로 약속을 꼭 지킬 것을 다짐함
- 야곱은 하나님의 이름으로 맹세하지 않고 
- 아버지 이삭이 경외하는 이라는 말로 맹세하였는데,
- 이것은 하나님의 이름을 두고 하는 맹세가 얼마나 큰 맹세인지, 
- 이 맹세는 목숨을 거는 맹세라는 것을 알기에 
- 두려워하며 한 맹세라는 것을 알 수 있음
- 야곱은 하나님께 제사를 드렸고,
- 많이 미웠을 라반과 형제들을 위해 제사한 음식을 차리고 함께 먹고 밤을 지냄
