9.적용(나)
- 야곱은 하나님께 친밀했으나 하나님을 경외할(두려워할) 줄 알았다.
- 이삭과 야곱처럼 하나님을 두려워하는 내가 돼야 한다.
- 내가 하나님을 두려워하면, 내 자녀들도 하나님을 두려워할 것이다.
- 야곱이 하나님께 예배 후 라반과 형제들을 대접한 것을 기억하자.
- 평화는 그렇게 찾아온다.

