심히 두렵고 답답함/조금도 감당할 수 없사오나: 7절 10절

4.주제만들기: 
두려운 마음으로 에서를 향해 가는 야곱

5.하나님 찾기 (관찰)
하나님의 군대 마하나임을 야곱에게 보여주신 하나님

6.인간 찾기(관찰)
마하나임을 만난 야곱
자신의 사람들에게 형 에서의 상황을 살피라고 보낸 야곱
형이 400명의 사람들과 함께 온다는 말을 전해듣고 심히 두려워하는 야곱.
하나님께 도움을 요청하는 기도를 올리는 야곱.

7.하나님 찾기(해석)
하나님은 야곱에게 담대함을 주시기위해  하나님의 군대 마하나임을 에서 만나기 전에 보여주셨다.

8.인간 찾기 (해석)
야곱에게 하나님은 함께하심을 여러 증표로 보여주셨다. 특별히 자신을 위협할 수 있는 라반 외삼촌과 형 에서의 만남 중간에 하나님은 여호와 군대 마하나임을 보여주셨다.

그런데도 야곱은 그의 사자를 통하여 형 에서가 400명과 함께 온다는 소리를 전해 듣고 두려운 가운데 가축을 포함한 모든 무리를 두 떼로 나누었다. 여차하면 도망갈 마음이었다.

그러면서 자신에게 명령하신 하나님 말씀대로 붙잡고 기도하는 그의 이중적 태도를 볼 수 있다.

이러한 모습을 누구든지 정죄할 수 없을 것이다. 나 역시도 늘 하나님의 약속 말씀을 믿고 순종하며 따르는듯하나 조금만 예상치 못한 문제가 생기면 순간 당황하는 모습을 갖는다.

그런데도 하나님은 이러한 모습조차도 용인하시고 계속 인도하신다.

사실 세상의 어떠한 강력한 세력이 공격하더라도 우리 하나님 군대 마하나임이 있음에 감사하다.

요즘 각국에서 전쟁이 일어나서 불안을 조성하고 있는데 우리 하나님 군대가 기도하는 국가나 공동체 개인을 보호해 주실 것을 믿는다.

9.적용(나):
하나님의 인도하심에 순종했음에도 힘든 일들이 생기더라도 도우시는 하나님을 굳게 믿고 살아내야겠다.

