9.적용(나)
- 하나님을 누구보다 굳게 믿지만, 
- 두려운 일은 두려운 것이 사실이고 정직한 것이다.
- 야곱은 하나님 앞에 정직했다.
- 두렵다고 도와주시라고 간구했다.
- 그 기도와 예배가 어떠했는지, 얼마나 간절했는지 성경에는 자세히 기록되지 않았다.
- 그러나 유추해 볼 수는 있다.
- 집을 떠난 수십년의 세월 동안 야곱의 믿음이 얼마나 단련되었고,
- 하나님과 함께 한 시간동안 그가 믿음의 거장이 되었음을 짐작할 수 있다.
- 그런 그가 인간적으로 할 수 있는 최선을 다해 대책을 세운다.
- 야곱의 이런 모습을 믿음이 약하다고 생각할 것이 아니라,
- 이런 모습 또한 배워야 한다.

