4. 주제만들기: 하나님과 씨름한 야곱
5. 하나님 찾기 (관찰)
- 얍복 나루에 머문 야곱에게 나타나 야곱과 씨름을 하심
- 야곱의 허벅지 관절을 치시고, 축복을 요구하며 자신을 놓지 않는 야곱의 이름을 물으시며
- 하나님과 사람과 씨름하여 이겼다는 뜻인 이스라엘이라는 이름을 주심
- 그 후 야곱에게 축복하심
6. 인간 찾기 (관찰)
- 야곱은 얍복 나루에 혼자 남아 있음
- 어떤 사람이 와서 씨름을 하게 됨
- 그를 놓지 않고 그에게 축복을 요구함
- 허벅지 관절을 맞았고, 씨름 후에 이스라엘이라는 이름과 축복을 받음
- 하나님이라는 것을 깨닫고 하나님을 대면하였으나 죽지 않았다며 그곳을 브니엘이라 함
- 허벅지 관절로 인해 다리를 절게 됨
7. 하나님 찾기 (해석) 
- 하나님께선 왜 야곱과 씨름을 하셨을까? 야곱은 하나님을 직접 체험하지 못했다. 형 에서가 400명의 사람을 이끌고 자신에게 오자 야곱은 두려웠을 것이다. 그러자 하나님께서 직접 야곱에게 나타나셨다. 하나님은 야곱의 성품을 정확히 알고 계시는 분이다.
- 하나님을 경험하고도 여전히 인간적인 방법을 의지하는 야곱에게 하나님은 직접 나타나 이름까지 바꿔주셨다. 그 이름은 이스라엘, 하나님과 겨루어 이겼다는 뜻으로 하나님은 충분히 야곱을 이길 수 있는 분이지만 야곱에게 져줌으로써 야곱이 하나님께서 함께 함을 깨닫고 용기를 가지고 에서를 만나러 갈 수 있게 도우셨다. 
8. 인간(해석):
- 에서가 400명을 데리고 온다는 것이 마음을 얼마나 두렵게 했을까? 야곱은 하나님과의 씨름을 통해 하나님의 존재를 정확히 경험하게 된다. 그리고 깨달았을 것이다. 형 에서에게 내가 무엇을 해야하는지...
- 얄팍한 꼼수가 아닌 형에게 과거의 잘못을 진심으로 사과하고 형에게 있어서 자신의 존재를 낮추는 것이 자신의 죄를 회복하는 일임을 깨달았을 것이다. 
9. 적용(나): 
- 나는 하나님과의 갑작스러운 씨름에 버텨낼 준비가 되어 있을까? 하나님께서 나와 함께 하시는 것을 잊고 세상적인 염려와 두려움에 사로잡혀 하나님의 존재를 무시하고 있진 않을까? 모든 일은 하나님으로부터 시작되어야 온전히 해결될 수 있다.
10. 영적터치(단어/구절)
- 어떤 사람이
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-04', '창세기', '33장 1절 ~ 10절', '', '(창세기 33장)
1. 야곱이 눈을 들어 보니 에서가 사백 명의 장정을 거느리고 오고 있는지라 그의 자식들을 나누어 레아와 라헬과 두 여종에게 맡기고
2. 여종들과 그들의 자식들은 앞에 두고 레아와 그의 자식들은 다음에 두고 라헬과 요셉은 뒤에 두고
3. 자기는 그들 앞에서 나아가되 몸을 일곱 번 땅에 굽히며 그의 형 에서에게 가까이 가니
4. 에서가 달려와서 그를 맞이하여 안고 목을 어긋맞추어 그와 입맞추고 서로 우니라
5. 에서가 눈을 들어 여인들과 자식들을 보고 묻되 너와 함께 한 이들은 누구냐 야곱이 이르되 하나님이 주의 종에게 은혜로 주신 자식들이니이다
6. 그 때에 여종들이 그의 자식들과 더불어 나아와 절하고
7. 레아도 그의 자식들과 더불어 나아와 절하고 그 후에 요셉이 라헬과 더불어 나아와 절하니
8. 에서가 또 이르되 내가 만난 바 이 모든 떼는 무슨 까닭이냐 야곱이 이르되 내 주께 은혜를 입으려 함이니이다
9. 에서가 이르되 내 동생아 내게 있는 것이 족하니 네 소유는 네게 두라
10. 야곱이 이르되 그렇지 아니하니이다 내가 형님의 눈앞에서 은혜를 입었사오면 청하건대 내 손에서 이 예물을 받으소서 내가 형님의 얼굴을 뵈온즉 하나님의 얼굴을 본 것 같사오며 형님도 나를 기뻐하심이니이다
