5.하나님 찾기 (관찰)
6.인간 찾기(관찰)
에서와 함께 400명의 장정이 오는것을 보는 야곱.
가족을 셋 떼로 나누는 야곱.
형 에서와의 기쁜 만남을 갖는 야곱.
서로 입맞추고 우는 형제.
에서를 향하여 하나님의 얼굴을 본 것 같다고 말하는 야곱.
7.하나님 찾기(해석)
8.인간 찾기 (해석)
20년전에 분노에 가득 찬 형 에서를 피하여 도망쳤던 야곱이 고향으로 다시 돌아와서 형을 직접 마주하게 된다. 야곱은 오랜만에 형을 만나는 설렘보다 혹시 여전히 있을 형의 분노에 대한 걱정의 두려움이 앞섰음을 볼 수 있다. 
그 이유는 자기 가족을 셋 떼로 나눈 것으로 알 수 있다. 그리고 소식으로만 전달받은 400명의 장정들을 직접 눈으로 보면서 짧은 시간에 얼마나 많은 생각을 하였을까? 
특별히 형 에서의 얼굴이 점진적으로 다가왔을 때 야곱의 심장은 크게 요동쳤을 것이다. 야곱은 이제는 모든 것을 하나님께 의지할 수밖에 없는 절체절명의 순간이다. 
드디어 만난 형의 얼굴은 20년 전의 죽이겠다고 외쳤던 살기가 가득 찬 얼굴이 아니라 마치 하나님의 얼굴을 본 것 같은 감동을 받는다. 
그리고 서로 재회의 기쁨으로 서로를 반기며 운다. 마치 드라마의 한 장면같이 연상된다. 이 모든 것은 하나님의 은혜임을 발견하게 된다. 이 모습은 에서 와 야곱의 친모인 리브가의 절대적 바람의 모습이었을 것이다. 
겁과 꾀가 많았던 야곱이지만 20년 동안 다양한 인생의 훈련을 통해서 성장시킨 하나님께서 형을 통하여 이제는 사랑의 하나님을 더욱더 보게 하셨다.
두려운 환경을 맞닥뜨리게 되더라도 하나님이 개입하시면 평안의 공간으로 됨을 깨우친다.
9.적용(나):
갈등을 평강으로 반전시킬수 있는 능력의 주님을 더욱 의지하여야겠다.
10. 영적터치 (단어 또는 구절)
10절: 내가 형님의 얼굴을 뵈온즉 하나님의 얼굴을 본 것 같사오며
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

