5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 레아가 낳은 딸 디나는 세겜 땅의 딸들을 보러 나갔다 히위 족속 하몰의 아들 세겜으로부터 강간을 당함
- 야곱은 목축하러 간 아들들이 돌아올 때까지 가만히 있음
- 세겜은 디나를 사랑하여 하몰에게 아내로 얻게 해달라고 요청함
- 하몰은 야곱을 찾아갔고, 이를 알고 온 야곱의 아들들은 근심하고 심히 노함
- 하몰은 야곱에게 서로 통혼하게 하고 우리와 함께 거주하며 여기 머물며 땅을 얻으라고 말함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 야곱은 형 에서를 만나고 은혜의 시간을 보낸 후에, 세일로 돌아가기 위해 평안히 가나안 땅 세겜 성읍 앞에 장막을 쳤다. 거기에 제단을 쌓고 하나님께 감사를 올려드린지 얼마되지 않아 딸이 강간 당하는 사건을 맞이하게 된다. 
- 이제 평안하고 은혜로운 시간만 가득할 것 같았던 이스라엘의 삶에 자신의 딸이 타 종족에 의해 강간을 당하는 일은 이스라엘을 심히 괴롭게 하였을 것이다. 하지만 이스라엘은 타 종족이 많은 세겜 지역에서 자신의 가족을 지켜야 했기 때문에 화내고 행동하는 것에 신중했을 것이다.
- 반면 이스라엘의 아들들은 자신의 여동생이 강간 당한 것에 근심하고 심히 노할 정도로 충격적인 일이었다. 아마 근심하며 하몰의 부족을 없애고자하는 계획을 세웠을 것이다. 
- 당시 세겜이 디나를 쉽게 강간하는 행동을 봤을 때 하나님을 믿지 않은 종족이 얼마나 성적으로 문란했는지와 여자를 쉽게 주고 받는 통혼이 그들의 삶을 번영시키는 일이었음을 생각하게 된다. 하나님은 이스라엘의 가정을 이런 족속으로부터 섞이지 않도록 보호하셨다.
9. 적용(나): 
- 하나님의 깊은 은혜를 경험한 후에 좋은 일들만 있길 바라지만 실상은 어떠한 일이든 벌어질 수 있다. 그 때 믿음을 잘 간직하고, 믿음 안에서 의의 눈으로 바라보고 지혜롭게 상황을 해결할 수 있는 믿음이 필요하다. 어려운 일이 발생하면 먼저 하나님께 그 뜻을 구해야겠다. 
