7.하나님 찾기(해석)

8.인간 찾기 (해석)
인간적인 측면에서 본다면 어느 정도 이해는 되지만 너무 과했다는 생각이 든다. 시므온과 레위는 디나의 직계 오빠이면서 여동생 디나를 얼마나 평상시 얼마나 아꼈는지 알 수 있다.

 그러나 아무리 분노가 나더라도 한 종족의 남자들을 몰살시킬 정도였다면 복수하기 전에 하나님께 억울함을 토하고 방법을 물어봤으면 어떠하였을까?
본문 내용 안에는 하나님께 묻는 내용이 전혀 나타나 있지않다.

아니면 최소한 아버지 야곱에게 의논하였다면 어떠하였을까?
분명 하나님은 방법과 해결책을 야곱을 통하여 주셨을 것이다.

그 문제로 하루아침에 야곱의 아들들은 야곱을 포함하여 가족 모두 위기를 맞닥뜨리게 된다.

아브라함 때부터 이삭 아버지 야곱에게 하나님께서 보여주셨던 수많은 기적을 들었음에도 순간의 분노가 수많은 간증들을 잊도록 순간 삼켜버린 듯하다.

평상시 마음의 화를 다스리는 훈련이 얼마나 중요한지 더욱 알게 된다.

