9. 세일 산에 있는 에돔 족속의 조상 에서의 족보는 이러하고
10. 그 자손의 이름은 이러하니라 에서의 아내 아다의 아들은 엘리바스요 에서의 아내 바스맛의 아들은 르우엘이며

