4.주제만들기: 
부자가 된 에서와 그의 자손들.

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
에서의 족보가 기록됨.
야곱과 에서의 재산(가축들)이 풍부하여 에서가 자신의 모든 소유물을 가지고 가족과  떠남.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
에서는 40살에 헷족속 여자들과 결혼하여 부모인 이삭과 리브가가 마음에 근심하였다고 26절 35절에 기록되어 있다.
에서는 두 헷족속 여자 이외에도 히의 족속 여인과 심지어는 고모뻘 되는 이스마엘 딸도 아내로 맞이했다.

하나님께 특별히 축복권을 받은 아버지 이삭을 근심시키면서 아내를 맞이한 에서임에도 에서는 수많은 가축을 보유한 갑부가 되었다.

그 가축이 심히 많은 에서는 마찬가지로 큰 갑부인 동생 야곱과의 소유권 분쟁을 피하려고 자기 가족과 가축을 이끌고 그 지역을 스스로 떠난다.

할아버지인 아브라함과 롯의 이야기(많은 가축으로 인한 서로 헤어짐)와 아버지인 이삭 이야기(우물)를 교훈 삼아 동생과 혹시 생길 마찰을 피할 생각이었을 것이다.
한 가정에서 내려오는 영적 간증의 체험이 자손들에게 큰 영적 자산이 되는 것 같다.

영적으로 분별력이 다소 부족한 에서이지만 하나님은 그러한 에서조차도 크신 은혜로 그의 허물조차도 덮어주시고 그 위에 은혜로 채워주셨다는 생각이 든다. 

9.적용(나):
부족한 나를 늘 은혜로 이끄시는 하나님께 더욱 순종하며 살아내야겠다 

