에서의 11명의 족장.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
성경은 의도적으로 에돔 왕의 계보를 나열하면서 이스라엘 왕이라는 단어를 기재하였다. 

이스라엘 왕이라면 언약의 백성 의 왕이라면 에돔(에서)왕 은 일반 세상의 왕을 의미할 수 있다.

사실 이스라엘 초대 왕인 사울을 세울 때도 하나님은 그리 기뻐하지 않으셨다. 왜냐하면 언약 백성의 진정한 왕은 하나님 이시기 때문이다.

하물며 에돔왕의 8명의 왕을 소개함으로 얼마나 강력하고 풍요로운 족속인 것을 알 수 있다.

 그리고 왕권을 계승하는 방법으로는 세습이 아닌 능력제로 계승한 것 보니 매우 발전지향적인 관습을 가진 것 같다.

특별히 38절에 ''바알하난'' 이라는 이름을 가진 왕이 있는데 아마도 바알 우상을 섬긴것 같다. 

아무리  탄탄한 제도적 체계와 풍요로움이 있는 왕권계승이라도 이는 사실 매우 유한적이다.

 반면에 세상에서 조금 가난해도 주님 안에서 사명을 감당하는 사람은 영원하고 안정된 풍요로움이 보장된 사람임을 깨우친다.

9.적용(나):
세상의 유한적 풍요를 따르지 않고 영원한 하나님의 풍요를 븉잡고 살아내야겠다 

