4.주제 만들기: 요셉의 꿈

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 야곱이 가나안 땅에 거주함
- 야곱의 아들 요셉이 17세에 그의 이복형들과 양을 침
- 이복형들의 잘못을 아버지에게 말함
- 야곱이 요셉을 다른 아들들보다 더 사랑하여 채색옷을 지음
- 형들이 아버지가 요셉을 더 사랑함을 보고 요셉을 미워함
- 요셉이 꿈을 꾸고 형들에게 말한 후에는 형들이 더욱 미워함
- 요셉이 형들에게 곡식 단 꿈에 대해 이야기함
- 요셉이 해와 달과 열한 별이 절하는 꿈에 대해 형들에게 말함
- 아버지와 형들에게 이야기함
- 야곱이 요셉을 꾸짖음

7.하나님 찾기 (해석) 

8.인간(해석)
- 요셉은 이복형들의 잘못을 아버지에게 말하였다.
- 이복형들이 어떤 잘못을 했는지는 모르겠으나,
- 이복형들이 요셉을 미워했을 것은 불을 보듯 뻔하다.
- 그런데 야곱이 요셉을 특별히 사랑하여 채색옷을 지어 입혔는데, 
- 이복형들은 그런 옷이 없었다.
- 그렇잖아도 어머니의 신분이 몸종이었던 이복형들은 어머니들의 삶을 봐 왔을 것이고,
- 살아오면서 많은 차별 대우를 받았을 것인데,
- 옷까지 채색 옷을 입히니 정말 기분이 나빴을 것이다.
- 이복형들은 아마도 목동의 옷을, 다 헤어진 옷을 입고 다녔을 것이다.
- 그렇잖아도 요셉이 미운데,
- 꿈 이야기라고 자랑을 하는데 자기들이 요셉에게 절을 한다는 것이다.
- 형들의 입장은 불을 보듯 뻔하다.
- 정말 미웠을 것이다.
- 그러나 요셉은 하나님이 주신 꿈을 꾸었기에 그 감동이 컸을 것이며, 
- 여운이 계속 남았을 것이다.
- 그래서 자신이 미움을 받을 것도 모르고, 더 자랑한 것으로 유추된다.
- 그리고 요셉은 해와 달과 열한 별 이야기를 하며 다시 자랑한다.
- 이런 요셉을 형들은 정말 미워할 수 밖에 없었다.
- 해와 달과 열한 별 이야기를 아버지 앞에서 형들이 듣는 곳에서 다시 이야기하는 요셉.
- 야곱은 이 꿈 이야기를 듣고 요셉을 꾸짖는다. 

9.적용(나)
- 하나님이 주신 꿈을 꾸고 싶다.
- 기분이 너무나 좋고, 계속 기억나는 그런 꿈을 꾸고 싶다.
- 기분이 너무나 좋을 때, 
- 주변 사람을 배려하며, 
- 조심히 그 꿈을 나누고 싶다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-14', '창세기', '37장 11절 ~ 20절', '죄의 시작은 시기', '[창37:11-20]
11 그의 형들은 시기하되 그의 아버지는 그 말을 간직해 두었더라
12 그의 형들이 세겜에 가서 아버지의 양 떼를 칠 때에
13 이스라엘이 요셉에게 이르되 네 형들이 세겜에서 양을 치지 아니하느냐 너를 그들에게로 보내리라 요셉이 아버지에게 대답하되 내가 그리하겠나이다
14 이스라엘이 그에게 이르되 가서 네 형들과 양 떼가 다 잘 있는지를 보고 돌아와 내게 말하라 하고 그를 헤브론 골짜기에서 보내니 그가 세겜으로 가니라
15 어떤 사람이 그를 만난즉 그가 들에서 방황하는지라 그 사람이 그에게 물어 이르되 네가 무엇을 찾느냐
16 그가 이르되 내가 내 형들을 찾으오니 청하건대 그들이 양치는 곳을 내게 가르쳐 주소서
17 그 사람이 이르되 그들이 여기서 떠났느니라 내가 그들의 말을 들으니 도단으로 가자 하더라 하니라 요셉이 그의 형들의 뒤를 따라 가서 도단에서 그들을 만나니라
18 요셉이 그들에게 가까이 오기 전에 그들이 요셉을 멀리서 보고 죽이기를 꾀하여
19 서로 이르되 꿈 꾸는 자가 오는도다
20 자, 그를 죽여 한 구덩이에 던지고 우리가 말하기를 악한 짐승이 그를 잡아먹었다 하자 그의 꿈이 어떻게 되는지를 우리가 볼 것이니라 하는지라

