4. 주제만들기: 죄의 시작은 시기
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 형들은 요셉을 시기함
- 아버지 이스라엘은 그 말을 간직함
- 이스라엘은 요셉을 시켜 형들이 양 떼를 잘 간직하는지 가서 보고 오라 시킴
- 요셉은 헤브론 골짜기에서 세겜으로 갔고, 들에서 형들을 찾지 못하고 방황하고 있을 때 어떤 사람을 만나 형들이 도단으로 가게 된 것을 알고 도단으로 감
- 멀리서 요셉이 오는 것을 본 형들은 그를 죽이자고 모의함. 그를 죽이고, 구덩이에 넣어 악한 짐승이 그를 잡아 먹었다 할 것이며, 그의 꿈이 어떻게 되는지 보자고 말함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 요셉의 행동이 얼마나 얄미웠을까... 형들은 요셉을 많이 미워하게 된다. 시기와 질투는 요셉을 살해하고자 모의하는 죄를 짓게 만든다. 과거 다나의 강간 사건과 요셉의 사건 모두 행동이 앞서는 형들의 어리석음을 볼 수 있다. 그들은 요셉을 멀리서 보고 요셉이 그들에게 오는 순간 요셉을 죽이고자 모의한다. 그 짧은 시간, 그들의 마음은 질투와 화로 가득찬다. 
- 이스라엘은 요셉의 말을 간직해두었다. 이스라엘이 자녀를 향한 사랑이 동일했다면 어땠을까... 그럼에도 요셉이 특별히 이뻤나보다. 
- 요셉은 아버지의 말에 순종해 형들에게 간다. 아버지의 말을 잘 따랐기에 이스라엘이 요셉을 특별히 더 이뻐했을 수도 있다.
9. 적용
- 항상 겸손한 삶을 살아야겠다. 나에겐 무의식적으로 나오는 언행이 있는데 다른 사람이 상처 받을 수 있다는 것을 안다. 이러한 경솔함이 고쳐지도록 기도한다.
- 다른 사람을 시기하지 않고 진심으로 기뻐하는 마음이 내 안에 생기길 소망한다. 시기는 죄를 낳는다. 죄의 유혹에 빠지지 않도록 하나님의 은혜를 소망해야겠다.
10. 영적터치(단어/구절)
- 요셉을 멀리서보고
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-15', '창세기', '37장 21절 ~ 30절', '', '(창세기 37장)
21. 르우벤이 듣고 요셉을 그들의 손에서 구원하려 하여 이르되 우리가 그의 생명은 해치지 말자
22. 르우벤이 또 그들에게 이르되 피를 흘리지 말라 그를 광야 그 구덩이에 던지고 손을 그에게 대지 말라 하니 이는 그가 요셉을 그들의 손에서 구출하여 그의 아버지에게로 돌려보내려 함이었더라
23. 요셉이 형들에게 이르매 그의 형들이 요셉의 옷 곧 그가 입은 채색옷을 벗기고
24. 그를 잡아 구덩이에 던지니 그 구덩이는 빈 것이라 그 속에 물이 없었더라
25. 그들이 앉아 음식을 먹다가 눈을 들어 본즉 한 무리의 이스마엘 사람들이 길르앗에서 오는데 그 낙타들에 향품과 유향과 몰약을 싣고 애굽으로 내려가는지라
26. 유다가 자기 형제에게 이르되 우리가 우리 동생을 죽이고 그의 피를 덮어둔들 무엇이 유익할까
27. 자 그를 이스마엘 사람들에게 팔고 그에게 우리 손을 대지 말자 그는 우리의 동생이요 우리의 혈육이니라 하매 그의 형제들이 청종하였더라
28. 그 때에 미디안 사람 상인들이 지나가고 있는지라 형들이 요셉을 구덩이에서 끌어올리고 은 이십에 그를 이스마엘 사람들에게 팔매 그 상인들이 요셉을 데리고 애굽으로 갔더라
29. 르우벤이 돌아와 구덩이에 이르러 본즉 거기 요셉이 없는지라 옷을 찢고
30. 아우들에게로 되돌아와서 이르되 아이가 없도다 나는 어디로 갈까

