요셉의 형들: 23절 26절 27절 28절

4.주제만들기: 
형들로부터 애굽에 팔려간 요셉

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
요셉의 채색옷을 벗기고 구덩이에 던진 요셉의 형들.
르우벤과 유다는 최소한 요셉을 죽이려고 하는 것을 막으려고 노력함.
결국 동생 요셉을 애굽으로 가는 미디안 상인들에게 은 이십에 판 형들.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉의 형들은 요셉의 입고 있는 채색옷을 강제로 벗기고 그를 잡아 구덩이 속으로 던졌다.

벗겨진 채색옷에 모든 것이 함축되어 있다. 아버지 야곱으로부터 받았던 특별한 사랑이 채색옷의 상징이라면 또 다른 마음인 시기와 미움의 태풍을 만났음을 알 수 있다.

그로 인하여 그는 최고의 즐거움에서 최악 절망의 인생의 구덩이에 빠진다. 심지어 그는 애굽으로 팔려 가는 신세가 되었다. 십칠 세 청소년이 감당하기 너무 처절하고 참혹한 과정이었을 것이다.

그가 형들을 자극하게 만든 것은 다름 아닌 하나님이 요셉에게 보여주신 꿈이요 비전이다. 이것은 사실 요셉의 꿈 이 아닌 하나님의 꿈이라 여겨진다.

사실 하나님이 요셉에게 보여주신 꿈은 수수하신 하나님의 사랑이다. 그런데도 요셉은 미성숙함으로 대처를 못 했다. 요셉이 조금 성숙하였다면 마음에 홀로 간직하고 있었으면 어떠하였을까 생각하게 된다.

더군다나 채색옷을 홀로 입을 정도로 독보적 사랑을 받은 요셉은 채색옷이 찢기는 일은 없었을 것이다.

결국 우리에게 하나님이 다른 사람들이 경험하지 못한 큰 자비를 베푸셨더라도 먼저 겸손과 지혜가 필요할듯하다. 마치 사도바울이 천국을 경험하는 특권을 누렸을 때 그는 성경에 기록할 때 ''내가 이런 사람을 아노니'' 라는 3인칭 기법을 사용하듯이 말이다

그런데도 다른 측면에서 보면 하나님은 비전을 미리 주시고 요셉에게 큰 인물(애굽 국무총리)을 이루게 하시는 방법임을 깨우치게 보여주신다. 특별히 연단의 고난으로 포장된 하나님의 축복을 통하여 그분의 뜻을 이루어 나가시는 것을 알 수 있다.

9.적용(나):
매사에 지혜와 겸손함을 갖도록 힘써야겠다.

10. 영적터치 (단어 또는 구절)
24절: 그가 입은 채색옷을 벗기고

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-16', '창세기', '37장 31절 ~ 36절', '', '(창세기 37장)
31. 그들이 요셉의 옷을 가져다가 숫염소를 죽여 그 옷을 피에 적시고
32. 그의 채색옷을 보내어 그의 아버지에게로 가지고 가서 이르기를 우리가 이것을 발견하였으니 아버지 아들의 옷인가 보소서 하매
33. 아버지가 그것을 알아보고 이르되 내 아들의 옷이라 악한 짐승이 그를 잡아 먹었도다 요셉이 분명히 찢겼도다 하고
34. 자기 옷을 찢고 굵은 베로 허리를 묶고 오래도록 그의 아들을 위하여 애통하니
35. 그의 모든 자녀가 위로하되 그가 그 위로를 받지 아니하여 이르되 내가 슬퍼하며 스올로 내려가 아들에게로 가리라 하고 그의 아버지가 그를 위하여 울었더라
36. 그 미디안 사람들은 그를 애굽에서 바로의 신하 친위대장 보디발에게 팔았더라

