4.주제만들기: 
아들 요셉의 죽음으로 여겨  비통하는 야곱.

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
아버지 야곱에게 가짜 요셉의 죽음을 알린 야곱의 자녀들.
아들의 비보를 전달 받은 야곱은 몹시 슬퍼함.
애굽 바로의 신하 친위대장 보디발에게 팔려간 요셉.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱은 특별히 사랑하는 아들 요셉이 짐승에게 죽임을 당했다는 소식을 듣고 오열한다. 자신이 다른 아들보다 더욱 사랑했음을 상징하는 채색옷에 피가 묻어있음을 직접 눈으로 확인하고 이성을 놓을 만큼 슬퍼한다.

나머지 자녀가 위로해주어도 받아들일 여유가 없어 보인다. 급기야 그는 스올(지옥)까지 가더라도 아들을 만나기를 바라고 있다.

이러한 모습을 바라보는 나머지 자녀들은 아버지 야곱을 속이면서까지 위로하였지만 그들의 속 마음은 어떠하였을까?

각자 조금씩 다른 마음이겠지만 대부분 시기 질투의 대상인 동생 야곱이 없어져서 다행이라 생각했을지 모른다.

이제는 사랑을 독차지한 대상이 없어졌기에 나름 앞으로는 공정한 사랑을 받을 기대하고 있을듯하다

그리고 그들의 한 악행에 대하여 애써 정당성을 가지려 했을 것이다.
무지함과 시기와 질투의 마음이 충돌하면 일어나는 현상으로는 분노와 슬픔 그리고 자신을 속이는 마음과 상처밖에 없는 것을 볼 수 있다.

한편 자신의 생명보다 아끼는 요셉을 생각하며 지옥이라도 갈 것이라고 하는 마음을 보면 우리 하나님의 마음을 간접 체험하게 된다.

거룩하신 주님이 지옥에 갈 수밖에 없는 나와 사람들을 구원하시기 위해 천국 보좌에서 내려오사 친히 모든 죄를 뒤집어쓰고 십자가에서 대신 돌아가신 사랑의 마음을 느끼게 된다.

사랑하는 자녀를 잃는다는 것은 어떠한 위로도 받을 수 없는 지상 최대의 슬픔일 것이다

그 슬픔을 이기시고 하나님 아버지는 독생자 예수를 죽이시고 우리를 구원하신 것을 생각하면 내가 얼마나 주님께 귀한 존재이고 아울러 하나님 아버지가 얼마나 감사한 분인지 더욱 깨우치게 된다.

9.적용(나):
나를 위하여 대신 죽으신 크신 사랑의 주님을  묵상 하며 더욱 감사 해야겠다.

10. 영적터치 (단어 또는 구절)
35절: 내가 슬퍼하며 스올로 내려가 아들에게로 가리라 하고

