- 여호와 보시기에 악하므로(7,10절)
4. 주제만들기: 여호와 보시기에 악한 유다의 자녀들
5. 하나님 찾기 (관찰)
- 하나님이 보시이기에 악한 유다의 자녀 엘과 오난을 죽이신 하나님
6. 인간 찾기 (관찰)
- 유다는 자기 형제들로부터 떠나 아둘람 사람 히라와 가까이 했고, 가나안 사람 수아라는 자의 딸을 아내로 맞이해 첫째, 엘, 둘째, 오난, 셋째 셀라를 낳음
- 유다는 첫째 엘을 위해 다말을 데려와 아내로 맞이하게 함. 
- 엘은 여호와가 보시이기에 악하여 죽임을 당함
- 유다는 동생 오난을 시켜 엘의 아내를 맞이해 아우된 본분으로 형의 씨를 있게하라 명령함
- 오난은 형수에게 들어가 잠자리를 갖지만 자신의 씨가 되지 않을 것을 알고 땅에 설정함
- 여호와께서 보시기에 오난의 행동이 악하므로 그도 죽임을 당함
7. 하나님 찾기 (해석) 
- 공의롭고 정의로우신 하나님께서 과거 유다의 죄를 깨닫게 하려 하셨을까? 자녀를 둘이나 죽임을 당하게 하셨다. 유다는 자신의 잘못을 뉘우치기는커녕, 형제들을 떠나 이방 사람들과 어울린 듯 하다. 하나님께선 그런 유다에게 잘못을 깨닫게 하시고 돌이키게 하시기 위해 직접 행동하셨다. 
8. 인간(해석):
- 유다는 자신의 아들을 매우 사랑한 듯하다. 자녀를 위해 아내를 직접 데려왔다. 
- 엘의 죽음에 깊은 슬픔을 느꼈을 것이다. 마치 자신의 아버지가 요셉을 잃은 것을 슬퍼하셨던 것과 같은 감정을 유다도 느꼈을까?
- 유다는 둘째 아들 오난에게 형의 씨를 이으라 명한다. 아들이 그리웠을 것이다. 
- 오난은 형수와 잠자리를 갖지만 땅에 설정하는 죄를 범한다. 무엇이 그렇게 싫었을까? 형과 관계가 좋지 않았을까? 자신들이 요셉을 질투한 것처럼 자신의 자녀도 동일한 상황을 겪지 않았을까?
- 결국 유다는 아들 둘을 잃게 된다. 그런데 다말의 처지가 처량하다. 남편을 잃었는데, 자신이 선택 받지도 못한 남자와 잠자리를 갖게 된다. 그러나 그 사람은 자신에게 씨를 줄 마음이 없다. 치욕스러운 감정만 남았을 것이다.   
9. 적용(나): 
- 때론 하나님께선 역지사지로 우리를 깨닫게 하신다. 내가 얼마나 죄인인지, 하나님께서 나의 죄를 얼마나 참고 계신지, 더 이상 참을 수 없어, 최후의 방법으로 나의 죄를 통해 내가 얼마나 큰 죄인인지를 깨닫게 하신다. 하나님께서 나에게 주신 고난의 대부분은 나의 죄로 인함이다. 나의 악함을 돌이켜보고 하나님께 돌아가는 영적 회복의 시간을 주심에 감사하다.
10. 영적터치(단어/구절)
- 여호와께서 보시기에 악하므로
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-18', '창세기', '38장 11절 ~ 20절', '유다와 며느리 다말', '창세기 38장
11   유다가 그의 며느리 다말에게 이르되 수절하고 네 아버지 집에 있어 내 아들 셀라가 장성하기를 기다리라 하니 셀라도 그 형들 같이 죽을까 염려함이라 다말이 가서 그의 아버지 집에 있으니라
12   얼마 후에 유다의 아내 수아의 딸이 죽은지라 유다가 위로를 받은 후에 그의 친구 아둘람 사람 히라와 함께 딤나로 올라가서 자기의 양털 깎는 자에게 이르렀더니
13   어떤 사람이 다말에게 말하되 네 시아버지가 자기의 양털을 깎으려고 딤나에 올라왔다 한지라
14   그가 그 과부의 의복을 벗고 너울로 얼굴을 가리고 몸을 휩싸고 딤나 길 곁 에나임 문에 앉으니 이는 셀라가 장성함을 보았어도 자기를 그의 아내로 주지 않음으로 말미암음이라
15   그가 얼굴을 가리었으므로 유다가 그를 보고 창녀로 여겨
16   길 곁으로 그에게 나아가 이르되 청하건대 나로 네게 들어가게 하라 하니 그의 며느리인 줄을 알지 못하였음이라 그가 이르되 당신이 무엇을 주고 내게 들어오려느냐
17   유다가 이르되 내가 내 떼에서 염소 새끼를 주리라 그가 이르되 당신이 그것을 줄 때까지 담보물을 주겠느냐
18   유다가 이르되 무슨 담보물을 네게 주랴 그가 이르되 당신의 도장과 그 끈과 당신의 손에 있는 지팡이로 하라 유다가 그것들을 그에게 주고 그에게로 들어갔더니 그가 유다로 말미암아 임신하였더라
19   그가 일어나 떠나가서 그 너울을 벗고 과부의 의복을 도로 입으니라
20   유다가 그 친구 아둘람 사람의 손에 부탁하여 염소 새끼를 보내고 그 여인의 손에서 담보물을 찾으려 하였으나 그가 그 여인을 찾지 못한지라


