6.인간 찾기 (관찰)
- 유다가 며느리 다말에게 셀라가 클 때까지 친정 아버지 집으로 가서 지내라고 함.
- 셀라를 다말에게 주었다가는 셀라도 형들처럼 죽을까 염려함.
- 가나안 사람 수아의 딸 유다의 아내가 죽음.
- 유다가 아둘람 사람 히라와 함께 딤나로 올라감.
- 다말이 유다가 딤나에 올라온 사실을 알게 됨.
- 다말이 과부 의복을 벗고 너울로 얼굴을 가리고 야곱을 만나러 감.
- 셀라가 장성했음에도 자신을 아내로 주지 않았기 때문에 유다를 만나러 감.
- 유다는 다말의 복장을 보고 창녀라고 생각하고 들어가게 하라고 말함.
- 유다가 염소새끼를 값으로 주겠다고 하자,
- 다말이 도장과 끈과 지팡이를 담보물로 요구함.
- 유다가 담보물을 주고 다말에게 들어감.
- 다말이 임신함.
- 담보물을 찾으러 갔으나 다말은 집으로 돌아가고 없었음.

7.하나님 찾기 (해석) 

8.인간(해석)
- 요셉을 미디안 상인에게 팔아 넘긴 이후,
- 유다는 형제를 떠나 이방 사람들과 어울렸으며,
- 가나안 사람 수아의 딸과 결혼을 하였다. 
- 요셉을 해하고 나서도 하나님의 말씀에 순종하지 않고 
- 자기 원대로 살아간 유다는 셀라를 다말과 결혼시켰다가는 
- 셀라도 형들처럼 죽을 것이라는 미신적인 생각을 하게 된다.
- 다말은 이스라엘의 전통(형의 자손을 동생이 이어가게 하는)을 어기고 
- 셀라를 자신에게 주지 않은 유다에게 계획적으로 접근한다.
- 창녀처럼 보이도록 너울로 가리고 접근했고,
- 경건치 못했던 유다는 다말의 계획에 따라 쉽게 다말에게 들어간다.
- 다말은 셀라가 아닌 유다의 씨로 엘의 자손을 이어간다.
- 유다도 경건치 못했으며, 다말 또한 가나안 사람 수아의 딸로서 경건치 몼했던 것이 분명하다.
- 그러나 우리가 잘 알 듯, 
- 이들의 추악한 죄에도 불구하고 
- 하나님은 이들의 씨를 통해 영광을 받으실 것이다.

9.적용(나)
- 하나님께서는 나의 실수를 통해서도, 
- 죄를 통해서도 역사하신다.
- 그러나 나는 그럴지라도 경건하지 않은 것과 이 세상 정욕은 다 버리고,
- 신중하고, 의롭게, 그리고 경건하게 이 세상을 살아갈 것이다.
- 이를 위해 오늘도 예수님을 바라봐야 한다. 

