행음: 24절(2) 
해산: 27절 28절
임신: 24절 25절 

4.주제만들기: 
유다보다 옳은자 다말

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
다말을 찾지 못하는 유다의친구.
며느리 다말의 행음소식을 듣고 분노하여 화형을 시키라 명령하는 유다.
자신이 다말을 행음하고 임신시킨 사람인것을 알고 다말을 자신보다 옳게 생각함.
베레스와 세라를 출산한 다말.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
23절에 유다는 친구와 더불어 "우리가 부끄러움을 당할까 하노라." 말한 것처럼 그는 자신이 행한 음란한 행위에 대하여 죄책감을 느끼고 있음을 볼 수 있다

그러한 유다는 며느리 다말의 임신 소식을 듣고 분노하여 화형을 치르기를 선포한다.

결국 며느리 다말을 임신케 한 장본인이 자신인 사실을 알고 다말이 자신보다 옳다고 말한다.

그리고 쌍둥이를 잉태하는데 뱃속에서 동생이 먼저 출산하고 이름을 베레스라 불렀다.

유다는 자신의 셋째아들 셀라를 보호하기 위해 다말을 속이려다 자신이 직접 이스라엘 혈통을 아들 대신 잇는 주역이 된다.

이성적인 측면에서는 다말이나 유다의 윤리적 행위를 이해하기가 어렵다.

그런데도 하나님은 과부 다말의 간절함을 받아주시고 그를 통하여 계보가 이어지게 하셨다.

숨기고 싶은 부끄러움조차도 공개적으로 드러내시고 오직 인간의 간절함에 마음을 귀히 보시고 인물을 사용하시는 하나님으로 여겨진다.

덕분에 유다도 자신의 모든 부끄러움이 드러나고 도리어 자유로움을 얻고 반성하며 변화되는 계기가 된 듯하다.

결국 둘째 아들 베르사를 통하여 이 땅에 육신으로 오신 예수님의 혈통을 잇는 영광을 얻었다.

9.적용(나):
내 자신 스스로도 유다처럼 연약한 존재임을 생각하며 늘 깨어서 기도생활에 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
26절: 그는 나보다 옳도다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-20', '창세기', '39장 1절 ~ 10절', '하나님 앞에서 살아간 요셉', '창세기 39장
1   요셉이 이끌려 애굽에 내려가매 바로의 신하 친위대장 애굽 사람 보디발이 그를 그리로 데려간 이스마엘 사람의 손에서 요셉을 사니라
2   여호와께서 요셉과 함께 하시므로 그가 형통한 자가 되어 그의 주인 애굽 사람의 집에 있으니
3   그의 주인이 여호와께서 그와 함께 하심을 보며 또 여호와께서 그의 범사에 형통하게 하심을 보았더라
4   요셉이 그의 주인에게 은혜를 입어 섬기매 그가 요셉을 가정 총무로 삼고 자기의 소유를 다 그의 손에 위탁하니
5   그가 요셉에게 자기의 집과 그의 모든 소유물을 주관하게 한 때부터 여호와께서 요셉을 위하여 그 애굽 사람의 집에 복을 내리시므로 여호와의 복이 그의 집과 밭에 있는 모든 소유에 미친지라
6   주인이 그의 소유를 다 요셉의 손에 위탁하고 자기가 먹는 음식 외에는 간섭하지 아니하였더라 요셉은 용모가 빼어나고 아름다웠더라
7   그 후에 그의 주인의 아내가 요셉에게 눈짓하다가 동침하기를 청하니
8   요셉이 거절하며 자기 주인의 아내에게 이르되 내 주인이 집안의 모든 소유를 간섭하지 아니하고 다 내 손에 위탁하였으니
9   이 집에는 나보다 큰 이가 없으며 주인이 아무것도 내게 금하지 아니하였어도 금한 것은 당신뿐이니 당신은 그의 아내임이라 그런즉 내가 어찌 이 큰 악을 행하여 하나님께 죄를 지으리이까
10   여인이 날마다 요셉에게 청하였으나 요셉이 듣지 아니하여 동침하지 아니할 뿐더러 함께 있지도 아니하니라

