4.주제 만들기: 하나님 앞에서 살아간 요셉

5.하나님 찾기 (관찰)
- 요셉과 함께 하심 
- 여호와께서 요셉의 범사에 형통하게 하심
- 요셉을 위하여 그 애굽 사람의 집에 복을 내리시므로 여호와의 복이 그의 집과 밭에 있는 모든 소유에 미침

6.인간 찾기 (관찰)
- 바로의 신하 친위대장 애굽 사람 보디발이 요셉을 삼
- 보디발이 여호와께서 요셉과 함께 하심을 봄
- 또 여호와께서 요셉의 범사에 형통하게 하심을 봄
- 보디발이 요셉을 가정 총무로 삼고 자기의 소유를 다 그의 손에 위탁함
- 소유를 다 요셉의 손에 위탁하고 자기가 먹는 음식 외에는 간섭하지 아니함
- 요셉은 용모가 빼어나고 아름다움
- 보디발의 아내가 요셉을 유혹함
- 요셉이 내가 어찌 이 큰 악을 행하여 하나님께 죄를 지으리이까 대답하며 유혹을 뿌리침
- 보디발의 아내가 날마다 동침하자고 말함
- 요셉은 동침하지 아니할 뿐 아니라,
- 함께 있지도 않음

7.하나님 찾기 (해석) 
- 요셉에게 꿈을 주신 하나님은 
- 비록 요셉이 노예로 끌려가게 하셨지만,
- 크신 계획 속에서 그렇게 하셨고,
- 늘 요셉과 함께 하시며,
- 지키시고 도우심

8.인간(해석)
- 요셉은 노예 신분이었으나, 
- 경건하여 늘 하나님과 동행함
- 보디발은 처음에는 요셉의 용모를 보고 노예로 샀으나,
- 보는 눈이 있어서 여호와 하나님께서 요셉과 함께 하시고, 
- 형통하게 하심을 봄(물론 하나님께서 알아보게 하셨을 것임)
- 보디발은 요셉과 함께 하시는 하나님과 경건한 요셉을 보고 마음에 들었고,
- 그리하여 자신의 모든 소유를 요셉에게 맡기게 됨
- 보디발의 아내가 용모가 뺴어나고 아름다운 요셉과 동침하려고 유혹하였으나
- 요셉은 하나님과 동행하고 있었기에
- 하나님 앞에서 범죄하지 않기 위하여 그 유혹을 뿌리침
- 보디발의 지위를 보았을 때 보디발의 아내는 심히 아름다운 여자였을 것이라고 유추해 볼 수 있음.
- 아름다운 여인의 유혹을 뿌리치고,
- 나아가 날마다 유혹하는데도 불구하고 거절하고,
- 함께 있지도 않은 것을 보면 요셉은 하나님의 불꽃 같은 눈동자를 늘 의식하고 살았던 것으로 보임    

9.적용(나)
- 내 몸은 하나님의 성전이고 하나님의 성령님께서 거하신다.
- 늘 주 안에서 깨어 기도하고 성령님과 깊이 교제함으로,
- 성령충만하여 성적 유혹을 뿌리쳐야 한다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-21', '창세기', '39장 11절 ~ 23절', '옷을 버려두고 도망간 요셉', '[창39:11-20]
11 그러할 때에 요셉이 그의 일을 하러 그 집에 들어갔더니 그 집 사람들은 하나도 거기에 없었더라
12 그 여인이 그의 옷을 잡고 이르되 나와 동침하자 그러나 요셉이 자기의 옷을 그 여인의 손에 버려두고 밖으로 나가매
13 그 여인이 요셉이 그의 옷을 자기 손에 버려두고 도망하여 나감을 보고
14 그 여인의 집 사람들을 불러서 그들에게 이르되 보라 주인이 히브리 사람을 우리에게 데려다가 우리를 희롱하게 하는도다 그가 나와 동침하고자 내게로 들어오므로 내가 크게 소리 질렀더니
15 그가 나의 소리 질러 부름을 듣고 그의 옷을 내게 버려두고 도망하여 나갔느니라 하고
16 그의 옷을 곁에 두고 자기 주인이 집으로 돌아오기를 기다려
17 이 말로 그에게 말하여 이르되 당신이 우리에게 데려온 히브리 종이 나를 희롱하려고 내게로 들어왔으므로
18 내가 소리 질러 불렀더니 그가 그의 옷을 내게 버려두고 밖으로 도망하여 나갔나이다
19 그의 주인이 자기 아내가 자기에게 이르기를 당신의 종이 내게 이같이 행하였다 하는 말을 듣고 심히 노한지라
20 이에 요셉의 주인이 그를 잡아 옥에 가두니 그 옥은 왕의 죄수를 가두는 곳이었더라 요셉이 옥에 갇혔으나
21 여호와께서 요셉과 함께 하시고 그에게 인자를 더하사 간수장에게 은혜를 받게 하시매
22 간수장이 옥중 죄수를 다 요셉의 손에 맡기므로 그 제반 사무를 요셉이 처리하고
23 간수장은 그의 손에 맡긴 것을 무엇이든지 살펴보지 아니하였으니 이는 여호와께서 요셉과 함께 하심이라 여호와께서 그를 범사에 형통하게 하셨더라

