1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 요셉(11,12,13,14,15,16,17,18,20,21,22,23절)
- 여인(12,13,14,19절)
- 옷(12,13,15,16,18절)
- 버려두고(12,13,15,18절)
- 나가다(12,13,15,18절)
- 주인(16,19,20절)
- 간수장(21,22,23절)
- 여호와께서 요셉과 함께 하시고(21,23절)
4. 주제만들기: 옷을 버려두고 도망간 요셉
5. 하나님 찾기 (관찰)
- 여호와께서 요셉과 함께 하시고 인자를 더하시고, 간수장으로부터 은혜 받게 하심
- 요셉을 범사에 형통케 하심
6. 인간 찾기 (관찰)
- 요셉은 일을 하러 주인의 집에 갔더니 집 사람들은 하나도 없었고 주인의 아내가 요셉과 동침하려하자 옷을 버려두고 도망감
- 주인의 아내는 집사람들을 불러 요셉이 희롱하려 한다고 말하며 그가 나와 동침하려하여 내가 소리를 질렀다고 말함
- 주인의 아내는 주인이 올 때까지 그의 옷을 곁에두고 주인이 돌아오자 당신의 종 히브리 사람이 나를 희롱하려 했다고 말함
- 주인은 심히 노하고 요셉을 잡아 옥에 가둠, 그 옥은 왕의 죄수를 가두는 곳이었음
- 요셉은 간수장에게 은혜를 받아 옥중 죄수를 다 요셉에게 맡기고 제반 사무를 요셉이 다 처리함
- 간수장은 요셉의 손에 맡긴 것은 무엇이든지 살펴보지 않음
7. 하나님 찾기 (해석) 
- 하나님의 계획은 요셉을 위기에 빠뜨리지 않는 것이 아니라 더 큰 일을 이루는 것에 초점이 맞추어져있다. 하나님과 함께하시면 요셉이 위기에 빠지지 않는게 가장 좋은 일일텐데 요셉은 번번히 위기에 빠진다. 하나님은 요셉에게 어떤 훈련을 시켜 성장시키려 하셨을까?
- 하나님 입장에서 죄를 짓지 않기 위해 노력한 요셉이 기특했을 것이다.
8. 인간(해석):
- 요셉은 성장했다. 주인의 아내의 동침 요구를 번번히 거절했고, 집에 갔을 때 아무도 없는 합리적 의심의 상황에서 아내의 강력한 요구에 옷을 버려두고 도망갔다. 요셉의 성품은 성장해있었다. 과거 자신의 경솔한 행동으로 자신의 행동을 돌아보았을까?
- 주인은 아내를 많이 사랑했던 것 같다. 요셉이 죄가 없었음을 분명히 알았을 것이다. 그러나 자신의 아내를 지키기 위해 요셉을 옥에 가두는 선택을 했다. 그럼에도 그가 요셉을 많이 아낀 것을 느낄 수 있는데 왕의 죄수를 가두는 곳에 요셉을 보낸 것이다. 요셉이 아내를 동침하려 했다는 것을 알면 종에 불가한 히브리사람을 죽여야하는 것이 마땅치 않은가?
- 하나님께서 함께하는 요셉은 가는 곳마다 자신의 능력을 발휘한다. 죄수가 죄수를 관리하고, 각종 제반 사무를 맡게 된다. 하나님게선 도무지 우리가 상상할 수 없는 방법으로 도우시는 분이시다. 요셉도 그것을 느꼈을 것이다.
9. 적용(나): 
- 죄의 유혹에서 벗어날 수 있는 믿음 갖길 기도해야겠다.
- 위기의 상황에서도 하나님을 굳게 신뢰할 수 있는 믿음을 갖도록 기도해야겠다.
10. 영적터치(단어/구절)
- 여호와께서 요셉과 함께 하시고
11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-22', '창세기', '40장 1절 ~ 10절', '', '(창세기 40장)
1.  그 후에 애굽 왕의 술 맡은 자와 떡 굽는 자가 그들의 주인 애굽 왕에게 범죄한지라
2. 바로가 그 두 관원장 곧 술 맡은 관원장과 떡 굽는 관원장에게 노하여
3. 그들을 친위대장의 집 안에 있는 옥에 가두니 곧 요셉이 갇힌 곳이라
4. 친위대장이 요셉에게 그들을 수종들게 하매 요셉이 그들을 섬겼더라 그들이 갇힌 지 여러 날이라
5. 옥에 갇힌 애굽 왕의 술 맡은 자와 떡 굽는 자 두 사람이 하룻밤에 꿈을 꾸니 각기 그 내용이 다르더라
6. 아침에 요셉이 들어가 보니 그들에게 근심의 빛이 있는지라
7. 요셉이 그 주인의 집에 자기와 함께 갇힌 바로의 신하들에게 묻되 어찌하여 오늘 당신들의 얼굴에 근심의 빛이 있나이까
8. 그들이 그에게 이르되 우리가 꿈을 꾸었으나 이를 해석할 자가 없도다 요셉이 그들에게 이르되 해석은 하나님께 있지 아니하니이까 청하건대 내게 이르소서
9. 술 맡은 관원장이 그의 꿈을 요셉에게 말하여 이르되 내가 꿈에 보니 내 앞에 포도나무가 있는데
10. 그 나무에 세 가지가 있고 싹이 나서 꽃이 피고 포도송이가 익었고

