2024년 11월23일 창세기 40장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천):
애굽 왕/바로: 1절 2절 
술 맡은 관원장: 2절 5절 9절
떡 굽는 관원장: 2절 5절
두 관원장: 2절 5절 6절 7절 8절
요셉: 4절(2) 6절 7절 8절 9절
근심의 빛: 6절 7절
꿈: 5절 8절 9절
해석: 8절(2)

4.주제만들기: 
두 관원장들의 꿈 해석을 청하는 요셉

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
애굽 왕에게 범죄하여 감옥에 갇힌 술 맡은 관원장과 떡 굽는 관원장.
해석을 스스로 할수없는 기묘한 꿈을 꾼 두 관원장.
그로 인하여 얼굴에 근심의 빛이  생긴 두 관원장.
그 꿈을 해석할수 있다고 청하는 요셉.
요셉은 해석의 능력은 하나님께 있다고 말함.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
노예 생활에서 한 단계 아래의 밑바닥 인생의 자리로 요셉은 떨어졌다.
비록 억울한 상황이었지만 요셉은 하나님께 은혜를 받은 까닭에 감옥 안에서도 당당함을 유지하였다.
그뿐만 아니라 애굽왕 바로의 분노로 감옥에 갇힌 술 맡은 관원장과 떡 굽는 관원장의 기묘한 꾼 꿈을 해석하겠다고 청하였다.
비록 감옥에 일시적으로 갇혀있지만, 과거 왕의 보좌 옆에서 시중들었던 위치이기 때문에 군대 장관조차도 그들에게 예의를 갖추고 있는 그것을 보아 함부로 대할 수 없는 사람들인 것은 분명하다. 

그들이 언제 다시 원래 자리로 복귀할지 모르기 때문이다. 그런데도 요셉은 담대하게 그들에게 꿈을 해석하기를 자청했다.
그러면서 요셉은 말한다. "모든 꿈의 해석은 하나님께 있지 아니하니이까"
과거 채색옷을 입고 자신을 높였던 요셉은 이제는 비록 죄수복을 입고 있지만 하나님을 높이는 사람이 되어있음을 발견한다.

9.적용(나):
어떠한 환경에서도 하나님을 높여드리는 사람이 되야겠다 

10. 영적터치 (단어 또는 구절)
8절: 해석은 하나님께 있지 아니하니이까 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-23', '창세기', '40장 12절 ~ 23절', '', '(창세기 40장)
11. 내 손에 바로의 잔이 있기로 내가 포도를 따서 그 즙을 바로의 잔에 짜서 그 잔을 바로의 손에 드렸노라
12. 요셉이 그에게 이르되 그 해석이 이러하니 세 가지는 사흘이라
13. 지금부터 사흘 안에 바로가 당신의 머리를 들고 당신의 전직을 회복시키리니 당신이 그 전에 술 맡은 자가 되었을 때에 하던 것 같이 바로의 잔을 그의 손에 드리게 되리이다
14. 당신이 잘 되시거든 나를 생각하고 내게 은혜를 베풀어서 내 사정을 바로에게 아뢰어 이 집에서 나를 건져 주소서
15. 나는 히브리 땅에서 끌려온 자요 여기서도 옥에 갇힐 일은 행하지 아니하였나이다
16. 떡 굽는 관원장이 그 해석이 좋은 것을 보고 요셉에게 이르되 나도 꿈에 보니 흰 떡 세 광주리가 내 머리에 있고
17. 맨 윗광주리에 바로를 위하여 만든 각종 구운 음식이 있는데 새들이 내 머리의 광주리에서 그것을 먹더라
18. 요셉이 대답하여 이르되 그 해석은 이러하니 세 광주리는 사흘이라
19. 지금부터 사흘 안에 바로가 당신의 머리를 들고 당신을 나무에 달리니 새들이 당신의 고기를 뜯어 먹으리이다 하더니
20. 제삼일은 바로의 생일이라 바로가 그의 모든 신하를 위하여 잔치를 베풀 때에 술 맡은 관원장과 떡 굽는 관원장에게 그의 신하들 중에 머리를 들게 하니라
21. 바로의 술 맡은 관원장은 전직을 회복하매 그가 잔을 바로의 손에 받들어 드렸고
22. 떡 굽는 관원장은 매달리니 요셉이 그들에게 해석함과 같이 되었으나
23. 술 맡은 관원장이 요셉을 기억하지 못하고 그를 잊었더라

