6.인간 찾기(관찰)
요셉의 꿈 해석처럼 그대로 이루어졌다. 술 맡은 관원장은 다시 지신의 위치로 회복됨.

빵 굽는 관원장은 죽임을 당함.

요셉은 술 맡은 관원장에게 자신을 감옥에서 나갈수 있도록 부탁함(꿈 해석당시).

술 맡은 관원장은 다시 회복된후 요셉을 잊어버림.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 하나님이 주신 은사로 두 관원장의 기묘한 꿈을 해석해 주었다. 그리고 삼일 후 그대로 이루어졌다. 술 맡은 관원장은 다시 복귀하였고 나머지 떡 굽는 관원장은 왕으로부터 사형선고를 받았다.

그러한 술 맡은 관원장에게 자신이 억울하게 감옥에 갇혀서 훗날 보직에 복귀하게 되면 풀어달라고 부탁하였다. 하나님을 늘 의지했던 요셉이 잠시 사람을 의지하는 모습을 보였다.

그런 까닭에 술 맡은 관원장이 복귀한 후 요셉을 잊었다고 의도적으로 성경에 기록한 것을 보면 하나님이 한 인간에게 원하시는 바가 있음을 보게 된다.

하나님이 함께하실 때는 이미 모든 능력과 도울 준비가 완료된 것을 의미할 것이다. 그러한 까닭에 하나님은 끝까지 하나님 자신만을 의지하기를 매우 바라시는 것 같다.

9.적용(나):
더욱 하나님만 의지하는 삶을 살아내야겠다 

