6. 인간 찾기 (관찰)
- 만 2년이 지난 후 바로는 꿈을 꾸었는데
- 살진 일곱 암소가 파리한 일곱 암소에게 잡아 먹히는 꿈과, 무성하고 충실한 일곱 이삭이 가늘고 동품에 마른 일곱 이삭에게 삼킴을 당하는 꿈을 꿈
- 바로의 꿈을 해석하기 위해 점술가와 현인을 불렀으나 해석하는 이가 없고
- 관원장이 과거 자신의 꿈을 해석한 요셉을 떠올림
7. 하나님 찾기 (해석)
- 인간을 의지하려 했던 요셉을 2년 동안 하나님께선 훈련 시키셨을 것이다. 그리고 요셉을 전면에 내세울 환경을 만들어주셨다. 
8. 인간(해석):
- 2년이 지날 동안 요셉은 여전히 감옥에서 옥살이를 하고 있었다. 2년의 시간 동안 요셉은 친위대장의 집에 있는 옥에 갇혀 옥살이를 했으나 그 집안의 모든 행정을 살폈을 것이고, 친위대장으로부터 많은 신뢰를 얻었을 것이며, 요셉이 죄 지을만한 행동을 하지 않았을 것이라는 믿음도 보였을 것이다.  
- 세상에 아무리 뛰어난 학식도 하나님의 뜻을 해석하는 것은 불가능하다. 
- 바로는 왕이지만 하나님을 알지 못해 번민이 되더라도 해결하지 못하고 사람들의 뜻을 구하는 처지이다. 하나님을 알았더라면 하나님께서 해결해주셨을 것이다.
9. 적용(나): 
- 하나님은 나를 위해, 결정적인 상황을 만들어두시고 훈련을 시키시는 중이다. 하나님께 감사하자. 결정적인 때를 위해 더욱 나를 단련시키자
- 하나님을 알고, 하나님을 믿을 수 있음에 감사하다. 우리는 그저 하나님께 간구하면 된다. 그러면 하나님께서 모든 것을 해결해주신다.
10. 영적터치(단어/구절)
- 9절 내가 오늘 내 죄를 기억하나이다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

