6.인간 찾기 (관찰)
- 술 관원장이 바로가 괴로워할 때 요셉을 떠올리고,
- 2년 전 요셉이 자신과 떡 굽는 관원장의 꿈을 해석해 주었는데,
- 그 해석되로 되었음을 바로에게 말함
- 바로는 이 말을 듣고 요셉을 불러오라 명함
- 요셉은 단정히 하고 왕 앞으로 나아감
- 왕이 요셉에게 네가 꿈을 능히 푼다고 들었다고 말하자,
- 요셉은 자기가 아니라 하나님께서 알려주신다고 말함
- 왕은 자신의 꿈 이야기를 함
- 그렇게 흉측한 모습은 처음 본다고 한 것으로 보아,
- 바로에게 큰 두려움을 주는 모습의 소였을 것이며,
- 그 모습과 소를 잡아먹는 모습이 바로에게 큰 충격과 공포를 안겨준 것으로 보임.

7.하나님 찾기 (해석) 
- 하나님의 때가 이르매, 요셉을 바로 앞에 세움  

8.인간(해석)
- 술 관원장은 2년 전 일을 생각하며, 아차 싶었을 것이다.
- 그러나 자신이 사랑하는 바로의 고통을 보며,
- 2년 전 요셉을 기억했고, 바로에게 보고한다.
- 그러나 이것은 하나님의 계획하심이다.
- 바로 왕은 술관원장의 말을 듣고 굉장히 기쁘면서,
- 동시에 그는 누구이며, 그는 과연 내 꿈을 풀 수 있을까 궁금했을 것이다.
- 요셉은 바로의 명을 듣고 기뻤을 것이다.
- 동시에 하나님께 감사와 찬양을,
- 그리고 바로의 꿈을 해석해 주시길 간절히 기도했을 것이다.
- 바로가 꿈을 잘 푼다고 들었다 라고 말하자,
- 요셉은 내가 아니라 하나님께서 알게 하실 것이다 라고 담대하게 말한다.
- 바로 왕은 큰 기대와 함께 의심하며 꿈 이야기를 했을 것이다.

9.적용(나)
- 내 상황과 상관없이 나는 주님과 동행함으로 기쁨과 평안을 누리고 있는가?
- 하나님의 음성이 몇 년간 들리지 않는다고,
- 상황에 부딪혀 괴로워하고 있지는 않은가? 

