7.하나님 찾기(해석)

8.인간 찾기 (해석)
진정한 왕은 하나님이신 것을 보여준다. 다른 내용의 같은 의미가 있는 꿈을 해석하여 바로왕에게 요셉은 설명하고 있다.

꿈의 해석으로는 7년 풍년 후 겪는 7년 기근을 의미한다. 잠시 세상에서 가질 부귀영화가 있더라도 이후에 있을 몰락을 생각한다면 아무리 세상의 귄세자라 하더라도 하나님 앞에서는 그저 약한 피조물이라 알려준다.

한편 죄수 요셉은 하나님이 함께하시고 꿈 해석의 능력을 주니 당당히 능력을 사용하는 것을 볼 수 있다.

요셉이 지속해 그런 능력을 행할 수 있는 동기는 그의 말을 통하여 발견한다.

"하나님이 그가 하실 일을 바로에게 보이심이니이다." 즉 요셉은 모든 능력의 주관자는 하나님이라 진심으로 믿고 선포하는 자이다.

