4.주제 만들기: 요셉의 해석과 바로의 반응

5.하나님 찾기 (관찰)
- 요셉이 꿈을 정확히 해석하도록 도우심

6.인간 찾기 (관찰)
- 요셉이 꿈을 해석함
- 하나님께서 결정하신 일이고, 그 일을 꼭 그대로 할 것임을 말함
- 명철하고 지혜있는 자를 세워 풍년에 흉년을 대비할 것을 권함
- 바로는 하나님이 너에게 모든 것을 알리셨으니 네가 바로 적임자라고 말하며
- 바로의 집을 다스리게 하고 백성이 요셉의 명령에 복종하도록 함

7.하나님 찾기 (해석) 
- 때가 되자 하나님은 극적으로 요셉을 들어 사용하신다.

8.인간(해석)
- 요셉은 풍년 이후의 흉년이 극심하여 풍년을 기억조차 못할 정도라고 말한다.
- 이 말을 듣는 모든 사람은 두려움에 사로 잡혔을 것이다.
- 요셉은 여기서 멈추지 않고, 흉년을 이겨낼 해법까지 제시한다.
- 명철하고 지혜로운 자가 애굽을 다스리게 하고
- 풍년 때 모든 곡물의 오분의 일을 거두어 저장하라는 해법을 제시한다.
- 이 말을 들은 바로는 요셉이 적임자라고 말하며
- 하나님의 영에 감동된 사람이라는 표현을 한다
- 바로는 요셉의 해석과 해법을 듣고
- 자신의 모든 불안이 해소되는 것을 느꼈을 것이다.
- 요셉으로 인해 바로는 확실히 하나님의 존재를 믿게 되었을 것이다.
- 그리고 바로는 그 자리에서 요셉에게 내 집을 다스리라고 명한다.
- 이것은 아주 파격적인 인사가 아닐 수 없다.
- 바로가 꿈으로 인해 얼마나 괴로웠으며, 
- 요셉의 해석과 해법으로 인해 얼마나 마음이 상쾌해지고 
- 이것은 확실하다고 확신에 찼는지 알 수 있는 부분이다.

9.적용(나)
- 하나님의 영에 감동된 사람 요셉과 같이 늘 성령충만하길 원한다.
- 다른 사람들이 나와 함께 하시는 하나님을 경험하게 되기를,
- 그리하여 다른 사람들이 하나님의 존재를 확신하게 되기를 원하다.

10. 영적터치(단어/구절)  
  38   바로가 그의 신하들에게 이르되 이와 같이 하나님의 영에 감동된 사람을 우리가 어찌 찾을 수 있으리요 하고

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-28', '창세기', '41장 41절 ~ 50절', '총리가 된 요셉', '[창41:41-50]
41 바로가 또 요셉에게 이르되 내가 너를 애굽 온 땅의 총리가 되게 하노라 하고
42 자기의 인장 반지를 빼어 요셉의 손에 끼우고 그에게 세마포 옷을 입히고 금 사슬을 목에 걸고
43 자기에게 있는 버금 수레에 그를 태우매 무리가 그의 앞에서 소리 지르기를 엎드리라 하더라 바로가 그에게 애굽 전국을 총리로 다스리게 하였더라
44 바로가 요셉에게 이르되 나는 바로라 애굽 온 땅에서 네 허락이 없이는 수족을 놀릴 자가 없으리라 하고
45 그가 요셉의 이름을 사브낫바네아라 하고 또 온의 제사장 보디베라의 딸 아스낫을 그에게 주어 아내로 삼게 하니라 요셉이 나가 애굽 온 땅을 순찰하니라
46 요셉이 애굽 왕 바로 앞에 설 때에 삼십 세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니
47 일곱 해 풍년에 토지 소출이 심히 많은지라
48 요셉이 애굽 땅에 있는 그 칠 년 곡물을 거두어 각 성에 저장하되 각 성읍 주위의 밭의 곡물을 그 성읍 중에 쌓아 두매
49 쌓아 둔 곡식이 바다 모래 같이 심히 많아 세기를 그쳤으니 그 수가 한이 없음이었더라
50 흉년이 들기 전에 요셉에게 두 아들이 나되 곧 온의 제사장 보디베라의 딸 아스낫이 그에게서 낳은지라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
