1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 바로(41,43,44,45,46절)
- 요셉(41,42,43,44,45,46,48,50절)
- 총리(41,43절)
- 온의 제사장 보디베라의 딸 아스낫(45,50절)
- 애굽 온 땅을 순찰하다(45,46절)
- 곡물(48,49절)
4. 주제만들기: 총리가 된 요셉
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 바로는 요셉을 애굽의 총리로 임명함
- 바로는 자신의 인장 반지와 세마포 옷을 입히고, 금 사슬을 목에 걸어 버금 수레에 태워줌
- 요셉 앞에서 소리쳐 모두 엎드리라 말하며 애굽의 총리로 임명함
- 바로는 요셉의 허락 없이는 자신의 손이나 발을 움직일 자가 없을 것이라며 전권을 부여함
- 요셉의 이름을 사브낫바네아라 명하고 제사장 보디베라의 딸을 맞이하게 함
- 요셉의 나이는 삼십세였고, 바로 앞을 떠나 애굽을 순찰함
- 일곱해 동안 풍년이었고 곡식을 소출해 각 성에 저장하였으며, 수를 셀 수 없이 많은 곡식이 소출됨
- 요셉은 두 아들을 낳음
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 기적과 같이 상황을 반전시키신 하나님은 바로를 통해 요셉을 애굽의 총리로 임명하게 하신다. 요셉의 세마포 옷과 삼십세라는 나이를 강조함으로써 하나님께서 섭리하신 것을 강하게 드러내셨다. 
- 요셉이 아버지의 색깔 옷을 입었을 땐 철 없었고, 자기중심적인 삶을 살았다면, 노예복과 죄수복을 입으며 하나님으로부터 완성된 성품을 훈련 받았다. 이번에 요셉은 세마포 옷이라는 색깔 옷과는 비교할 수 없는 옷을 바로로부터 수여 받았다. 요셉은 과거의 자신의 잘못을 뼈저리 느끼고 뉘우쳤을 것이다. 하나님은 요셉이 준비되었을 때 세마포 옷으로 요셉이 상황을 반전시켜 주셨다.
- 요셉의 입장에서 하나님을 의지해 꿈을 해석했을 뿐인데 갑자기 한 나라의 총리가 되었다. 보디발과 친위대장의 집을 관리하며 행정력을 키웠을테지만 그럼에도 부담스러운 자리였을 것이다. 만약 7년 동알 풍년이 오지 않거나, 흉년이 오지 않는다면 바로로부터 목숨을 담보 받지 못했을 것인데 요셉은 총리로서 임무를 잘 감당했다. 기적과 같이 상황이 반전했음에도 기적과 같은 일을 또 경험해야했다.  
9. 적용(나): 
- 하나님께선 인간이 생각하기에 기적과 같은 일을 만드시는 것은 매우 쉬운 일이다. 그 분은 우리에게 기적과 같은 일들을 자주 제공하고 싶지만 우리가 준비되어 있지 않다. 
- 하나님께선 우리에게 그분에 대해선 완전함을 요구하신다. 나의 연약함은 하나님께 문제가 되지 않는다. 그러나 하나님을 향한 나의 생각, 행동은 완전함을 기다리신다. 그 분을 만난 후 내가 변화될 영역들이 해소될 때, 임계점을 넘어서는 것 같이 하나님께선 기적과 같은 일을 만드시는 분이시다. 그 분을 신뢰하며 매일매일 하나님께 집중하는 삶, 하나님께서 기뻐하시는 삶을 살도록 노력해야겠다.
10. 영적터치(단어/구절)
- 세마포 옷, 삼십세
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-29', '창세기', '41장 51절~60절', '', '(창세기 41장)
51. 요셉이 그의 장남의 이름을 므낫세라 하였으니 하나님이 내게 내 모든 고난과 내 아버지의 온 집 일을 잊어버리게 하셨다 함이요
52. 차남의 이름을 에브라임이라 하였으니 하나님이 나를 내가 수고한 땅에서 번성하게 하셨다 함이었더라
53. 애굽 땅에 일곱 해 풍년이 그치고
54. 요셉의 말과 같이 일곱 해 흉년이 들기 시작하매 각국에는 기근이 있으나 애굽 온 땅에는 먹을 것이 있더니
55. 애굽 온 땅이 굶주리매 백성이 바로에게 부르짖어 양식을 구하는지라 바로가 애굽 모든 백성에게 이르되 요셉에게 가서 그가 너희에게 이르는 대로 하라 하니라
56. 온 지면에 기근이 있으매 요셉이 모든 창고를 열고 애굽 백성에게 팔새 애굽 땅에 기근이 심하며
57. 각국 백성도 양식을 사려고 애굽으로 들어와 요셉에게 이르렀으니 기근이 온 세상에 심함이었더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
