1:감동받는 단어나 구절 찾기(영적터치)

2024년 11월30일 창세기 41장51절~57절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천):
기근: 54절 56절(2) 57절
자녀 이름(므낫세, 에브라임): 51절 52절
백성: 55절(2) 56절 57절
기근이 심함: 56절 57절
양식을 구함: 55절 57절

4.주제만들기: 
풍년후 도래한 심한 흉년

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
풍년시기에  두 아들을 얻은 요셉.
그 자녀들에게 므낫세 그리고 에브라임 이라 이름을 지어줌.
풍년후 심한 기근이 와서 백성들이 양식을 구하기위해 부르짖음.
바로왕은 요셉에게 실권을 맡김.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉의 꿈 해석대로 애굽 땅에 7년 풍년 후 7년 기근이 왔다. 요셉은 풍년 시기에 아들 두 자녀를 얻는다.
첫째아들 이름은 므낫세이고 둘째는 에브라임이다. 13년 동안 고통의 시간을 가진 요셉은 이제는 모든 고난을 지나 번창하는 인생의 길을 가는 것을 자녀들 이름의 의미로 알 수 있다.

그런데 궁금한 것은 죄수의 신분에서 국무총리 자리에 오른 것은 바로의 권위 때문이라 본다면 요셉은 얼마든지 바로의 명령에 다시 감옥신세를 가질 수도 있다는 방증을 갖게 된다.

그런 면에서 요셉에게는 7년 기근이 오기 직전의 미래에 대한 확신이 있음을 볼 수 있다.

사실 인간적인 측면에 본다면 7년의 기근이 오지 않는다면 바로 왕에게 거짓을 말한 사람으로서 왕을 농락한 죄로 큰 어려움을 당할 처지가 될 것이 분명하다.

그런데도 요셉이 당당한 것은 어둡고 답답한 긴 감옥 속에서 하나님의 음성을 듣는 훈련을 받았기 때문이라 생각된다.

지금 환경이 조금 불편하고 답답해도 도리어 감사할 것은 지금이야말로 더욱 주님과 친밀감을 느끼는 시간이기 때문이다.

9.적용(나):
비전대로 이루시는 하나님을 더욱 의지하고 순종하며 살아내야겠다.

10. 영적터치 (단어 또는 구절)
51절: 내게 내 모든 고난과 내 아버지의 온 집 일을 잊어버리게 하셨다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-11-30', '창세기', '42장 1절~10절', ' ', '(창세기 42장)
1.  그 때에 야곱이 애굽에 곡식이 있음을 보고 아들들에게 이르되 너희는 어찌하여 서로 바라보고만 있느냐
2. 야곱이 또 이르되 내가 들은즉 저 애굽에 곡식이 있다 하니 너희는 그리로 가서 거기서 우리를 위하여 사오라 그러면 우리가 살고 죽지 아니하리라 하매
3. 요셉의 형 열 사람이 애굽에서 곡식을 사려고 내려갔으나
4. 야곱이 요셉의 아우 베냐민은 그의 형들과 함께 보내지 아니하였으니 이는 그의 생각에 재난이 그에게 미칠까 두려워함이었더라
5. 이스라엘의 아들들이 양식 사러 간 자 중에 있으니 가나안 땅에 기근이 있음이라
6. 때에 요셉이 나라의 총리로서 그 땅 모든 백성에게 곡식을 팔더니 요셉의 형들이 와서 그 앞에서 땅에 엎드려 절하매
7. 요셉이 보고 형들인 줄을 아나 모르는 체하고 엄한 소리로 그들에게 말하여 이르되 너희가 어디서 왔느냐 그들이 이르되 곡물을 사려고 가나안에서 왔나이다
8. 요셉은 그의 형들을 알아보았으나 그들은 요셉을 알아보지 못하더라
9. 요셉이 그들에게 대하여 꾼 꿈을 생각하고 그들에게 이르되 너희는 정탐꾼들이라 이 나라의 틈을 엿보려고 왔느니라
10. 그들이 그에게 이르되 내 주여 아니니이다 당신의 종들은 곡물을 사러 왔나이다

