5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
기근으로 인하여 먹을 곡물을 구하러 애굽으로 10아들을 보낸 야곱.
12째 아들 베냐민은 걱정돼서 보내지 않은 야곱.
애굽으로 떠난 10형제들.
애굽에서 요셉을 만나고 동생인지 알아보지 못한 요셉의 형들.
반면에 형들을 알아본 요셉.
과거의 꿈을 생각해낸 요셉.
형들을 정탐꾼으로 추궁하는 요셉.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 22년 만에 형들과 재회하였다. 형들을 본 요셉은 순간 어떠한 감정이었을까? 상상되지 않는다. 

아마 수많은 감정이 생겼으며 그리움과 섭섭함 그리고 분노 등 복잡한 마음이 생겼을 것 같다. 자신을 미워하여 어린 자신을 노예로 팔았던 형들이 이제는 자신의 앞에서 곡물을 팔아달라고 거의 구걸하듯 하고 있다. 

그리고 그들은 요셉의 얼굴을 보고도 알아보지 못했다. 반면 요셉은 그들을 대번 알아보았다. 형들로서는 동생 요셉이 감히 그러한 높은 위치에 있을 거라 상상하지 못했기 때문에 더욱 알아보지 못했을 것이다. 

그때 요셉은 잊고 있었던 꿈을 생각하게 된다. 첫째 아들 므낫세 의미인 가족을 잊었다고 하듯 그는 어렸을 때 가졌던 꿈조차도 잊고 살았음을 짐작할 수 있다. 

하지만 형들을 다시 보았을 때 잊고 있었던 어렸을 때 꾸었던 그 꿈을 다시 기억하게 되었다. 결국 그 꿈은 요셉의 꿈이 아닌 하나님이 요셉에게 보여주신 꿈인 비전인 것 같다.

하나님! 우리의 꿈이 아닌 당신의 꿈이 우리 NKFC 공동체 가운데 늘 실천되게 하옵소서!!

9.적용(나):
주님이 주신 비전을 더욱 믿음으로 굳게 붙잡고 살아야겠다.

