5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 요셉은 형들을 알아보지만 정탐꾼으로 몰아 형들을 시험함
- 형들은 자신들은 확실한 자들이며 열두 형제로 가나안 땅의 한 사람의 아들이고, 막내는 아버지와 함께 있으며, 하나는 없어졌다고 말함
- 요셉은 정탐꾼이 아님을 증명하라 말하며 막내 아우를 데려오라 하고 삼일을 옥에 가둠.
- 사흘 만에 요셉은 자신은 하나님을 경외하는 자로 생명을 보전하기 위해 한 사람은 옥에 갇히고 나머진 집으로 돌아가 굶주림을 해결하고 막내 아우를 데려오면 너희의 말이 진실이 되고 죽지 않을 것이라 말함
- 형들은 요셉의 말을 그대로 행함
7. 하나님 찾기 (해석) 
- 하나님의 비전을 이루시는 하나님
8. 인간(해석):
- 요셉은 형들이 반가웠을 것이다. 그리고 원망스러운 마음도 들었을 것이다. 그러나 하나님이 요셉과 함께하여 비전을 보이시고, 비전을 완성하셨기 때문에 원망보단 반가운 마음이 더컸을 것이다.
- 그럼에도 요셉은 형들을 시험하고자 했다. 자신의 동생인 막내 베냐민을 형들이 지켜주는지 테스트하고자 했다. 그러기 위해선 형들을 정탐꾼으로 몰아야했고, 베냐민이 자신에게 오도록 한명을 볼모로 삼아야 했다.
- 형들은 자신들이 정탐꾼이 아님을 증명하기 위해 확실한 자들이 말한다. 신분이 확실하다라는 의미도 있겠지만 자신들은 정직한 사람들이란 의미도 있었을 것이다. 형들에겐 아직 씻기지 않은 교만이 있다. 굶어죽을 위기에 처한 자신들의 족장에 당장 필요한 것은 식량인데, 바싹 엎드려 자신들의 처지를 겸손히 말해도 부족할 판에 당당히 자신들은 12형제이며, 야곱의 아들임을 강조한다.
- 형들은 요셉에게 당신의 종이라 말하며 아부하고 있다. 하나님의 비전, 요셉의 꿈이 정확히 이루어지고 있다. 하나님의 때는 알 수 없으나 하나님께서 계획하신 일은 반드시 이루어진다. 
9. 적용(나):
- 아직 내 안에 형들과 같은 교만함이 남아있지 않은지 점검해야겠다. 나는 확실한 자가 아니라 겸손히 하나님 앞에 엎드려, 매달려 내 삶을 그분께 의탁해야 한다.  
10. 영적터치(단어/구절)
- 확실한 자
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

