6.인간 찾기(관찰)
- 형들이 요셉의 말을 듣고 요셉에게 한 행동으로 이 괴로움을 당한다 말함
- 르우벤이 자신의 말을 듣지 않은 형제들을 책망함
- 그들은 요셉이 알아듣는 줄 몰랐다
- 요셉이 형들을 떠나가서 울고 다시 돌아옴
- 형들 중에서 시므온을 끌어내어 결박함
- 형제들에게 곡물을 주고 돈을 자루에 도로 넣게 하고
- 길 양식을 그들에게 주게 함
- 형제들이 집으로 돌아가는 길에서 자루에 돈이 있는 것을 발견함
- 혼이 나서 떨며 서로 돌아봄
- 형들이 야곱에게 이르러 그동안 있었던 일을 자세히 알림

7.하나님 찾기(해석)

8.인간 찾기 (해석)
- 형들이 요셉과의 일로 인해 지금 괴로움을 당한다라고 말하며 괴로워 함
- 르우벤이 동생들을 책망함
- 요셉은 형들이 주고 받는 말을 듣고, 
- 형들의 후회와 반성, 그리고 르우벤이 자신을 살리려 했음을 듣고 
- 감정이 북받쳐 자리를 옮겨 올고 돌아옴
- 형들 중 시므온을 결박하였는데, 
- 시므온이 남은 것이 형들의 결정인지,
- 아니면 지난 날 시므온이 요셉을 가장 많이 괴롭혔기에 요셉이 결정한 것인지 정확히 알 수는 없으나, 여동생 디나 사건 등을 고려하면 그렇게 유추해 볼 수는 있음.
- 시므온은 결박당하며 지난 날을 더욱 후회하며 반성했을 것이다
- 요셉이 형들에게 곡물과 길 양식을 줄 뿐만 아니라,
- 곡물 값으로 지불한 돈을 다시 자루에 넣어서 보냄
- 형들이 돌아가는 길에 자루에 담긴 돈을 보고 놀라서 떨며,
- 서로를 보며 하나님이 어찌하여 이런 일을 우리에게 행하셨는가 말함
- 정직한 자라고 강하게 말하고 시므온까지 두고 돌아왔는데,
- 지불한 돈이 자루에서 발견되었으니, 요셉을 속인 꼴이 된 것
- 형들이 야곱의 집에 돌아와서 야곱에게 모든 일을 이야기 함
- 아마도 두려워하며 아버지를 걱정하며 말했을 것임

