2024년 12월04일 창세기 42장31절~38절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천):
정탐꾼: 31절 34절 
돈뭉치: 35절(2)
없어지고: 32절 36절
베냐민(막내): 32절 34절 36절 
그 땅의 주인(요셉):32절  33절 38절
야곱: 36절 37절 38절
확실한 자들이요: 31절 33절

4.주제만들기: 
우리는 확실한 자들이요

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
 형들을 정탐꾼이라 시험하는 요셉.
요셉에게 자신듵은 확실한 자들이라 말하는 요셉의 형들.
자루 속에 돈뭉치를 발견하고 두려워하는 형제들.
소식을 듣고 매우 슬퍼하는 야곱.


7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉의 형들은 그들 자신을 ‘확실한 자들’이라 말한다. 즉 정탐꾼이 아니라고 말하고 있다. 그러면서 과거 베냐민 형인 요셉에 대하여 말할 때는 그저 없어졌다고 말한다. 

그러나 성경은 철저히 그들이 숨기고 있는 사실을 양심이라는 잣대로 찌르고 있음을 보여주고 있다. 그들은 확실할 정도로 정직한 자들이 아니다. 

물론 정탐꾼은 아니지만 22년 전에 아우를 노예로 팔은 무정한 자들이다. 그들은 자신의 죄를 숨기고 없어졌다고 하지만 그의 아버지 야곱은 죽었다고 말하고 있다. 

무자비한 잘못된 선택으로 얼마나 오랫동안 스스로 정죄를 받으며 상처를 줄 수 있는지 알 수 있다. 

한편 요셉은 스스로 겪었던 상처들을 떨고 그들의 마음을 시험하는 동시에 자신의 친 육인 동생 베냐민을 만나기 위해 지혜를 발휘한다.

9.적용(나):
늘 너그러운 마음으로 살아야겠다.

10. 영적터치 (단어 또는 구절)
31절: 우리는 확실한 자들이요

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-04', '창세기', '43장 1절~10절', '계속 되는 기근', '창세기 43장
1   그 땅에 기근이 심하고
2   그들이 애굽에서 가져온 곡식을 다 먹으매 그 아버지가 그들에게 이르되 다시 가서 우리를 위하여 양식을 조금 사오라
3   유다가 아버지에게 말하여 이르되 그 사람이 우리에게 엄히 경고하여 이르되 너희 아우가 너희와 함께 오지 아니하면 너희가 내 얼굴을 보지 못하리라 하였으니
4   아버지께서 우리 아우를 우리와 함께 보내시면 우리가 내려가서 아버지를 위하여 양식을 사려니와
5   아버지께서 만일 그를 보내지 아니하시면 우리는 내려가지 아니하리니 그 사람이 우리에게 말하기를 너희의 아우가 너희와 함께 오지 아니하면 너희가 내 얼굴을 보지 못하리라 하였음이니이다
6   이스라엘이 이르되 너희가 어찌하여 너희에게 또 다른 아우가 있다고 그 사람에게 말하여 나를 괴롭게 하였느냐
7   그들이 이르되 그 사람이 우리와 우리의 친족에 대하여 자세히 질문하여 이르기를 너희 아버지가 아직 살아 계시느냐 너희에게 아우가 있느냐 하기로 그 묻는 말에 따라 그에게 대답한 것이니 그가 너희의 아우를 데리고 내려오라 할 줄을 우리가 어찌 알았으리이까
8   유다가 그의 아버지 이스라엘에게 이르되 저 아이를 나와 함께 보내시면 우리가 곧 가리니 그러면 우리와 아버지와 우리 어린 아이들이 다 살고 죽지 아니하리이다
9   내가 그를 위하여 담보가 되오리니 아버지께서 내 손에서 그를 찾으소서 내가 만일 그를 아버지께 데려다가 아버지 앞에 두지 아니하면 내가 영원히 죄를 지리이다
10   우리가 지체하지 아니하였더라면 벌써 두 번 갔다 왔으리이다

