5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 애굽에서 가져온 먹을 것이 모두 떨어지자 
- 야곱이 아들들에게 다시 애굽에 가서 먹을 것을 가져오라고 말함
- 유다가 베냐민을 데려가야 함을 말하며 아버지의 허락을 구함
- 야곱이 어째서 막내 동생이 있음을 애굽 총리에게 말하였느냐고 아들들을 나무람
- 유다는 애굽 총리가 묻는 말에 대답했을 뿐이라고 대답함
- 유다가 막내 동생을 데리고 다녀오게 해달라고 다시 요구함
- 그래야 온 가족이 살 수 있다고 말하며
- 막내 동생을 데려오지 못하면 자신이 그 죄를 평생 받겠다고 말함

7.하나님 찾기 (해석) 

8.인간(해석)
- 야곱이 기근이 심하여 먹을 것이 떨어지자 애굽에 다시 다녀오라고 말함.
- 유다가 베냐민을 데려가야 함을 말하자,
- 야곱이 괴로워하며 아들들을 나무람
- 야곱은 사랑하는 라헬의 아들 중 요셉은 죽고 베냐민만 남았는데, 
- 베냐민까지 잃을까 두려웠을 것임.
- 그러나 먹을 것을 얻기 위해서는 베냐민을 보낼 수밖에 없음을 야곱은 잘 알고 있었을 것.
- 유다가 온 가족을 살리기 위해 베냐민과 다녀오게 해달라고 허락을 구함
- 야곱을 설득하기 위해 베냐민을 데려오지 못하면 자신이 모든 죄를 평생 받겠다고 다짐함
- 야곱이 레아의 아들들 앞에서 라헬의 아들을 더욱 귀히 여기는 모습을 계속 보이는데,
- 레아의 아들들은 과거 자신들의 잘못이 있더라도 서운할 수도 있는 부분임
- 그러나 르우벤도 유다도 아버지께 간곡하게 다녀오겠다고 허락을 구하는 것으로 보아,
- 장년이 되어 어느 정도 성숙했음을 알 수 있음

9.적용(나)
- 나그네 인생길에서 어려운 순간이 없을 수 없다.
- 그때에 놀라운 선물을 준비하시는 하나님을 기대하며,
- 묵묵히 내가 할 수 있는 일을 해야 한다.

