2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 돈(12,15절)
- 베냐민(14,15,16절)
- 요셉(15,16,17,18,19절)
- 청지기(16,17,19절)
4. 주제만들기: 이스라엘의 내려놓음
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 이스라엘은 아름다운 소산(유향, 꿀, 몰약, 유향나무 열매, 감복숭아)과 예물을 요셉에게 드리라고 말하며 자루에 들어있던 돈의 배가 되는 돈을 가지고 요셉에게 가라고 말함
- 베냐민을 데리고 가고 전능하신 하나님께서 다른 형제와 베냐민을 돌려보내길 바란다고 말함
- 형제들이 애굽으로 떠남
- 요셉은 형제들이 오는 것을 보고 베냐민을 포함된 것을 본 후 청지기를 통해 먹을 것을 준비하라고 함
- 형제들은 청지기의 인도로 요셉의 집에 가게 되자 자루에 있던 일로 자신들이 노예가 될 것을 두려워함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 이스라엘은 베냐민을 보낼 수 밖에 없는 상황에 처했다. 요셉을 잃고 베냐민만큼은 다른 곳으로 보내고 싶지 않았을 것이다. 이스라엘에게 요셉과 베냐민은 하나님을 더 사랑하게 만드는 존재였을까? 다른 형제들보다 요셉과 베냐민을 더 사랑했고, 그것을 티냈던 이스라엘이 베냐민을 보낼 수 밖에 없는 상황이 되자 하나님을 의지하고 하나님께서 시므온과 베냐민이 함께 돌아오게 하실 것을 바란다고 말하며 모든 아들에 대한 걱정과 하나님을 그제야 의지하는 모습을 보여준다.
- 요셉은 형들이 베냐민을 데려온 모습을 보고, 형제들을 위해 음식을 제공한다. 하나님께서 이루신 비전을 요셉은 알고 있기에 형들에게 자신의 존재를 즉시 밝히면 될 것이다. 그러나 요셉은 형들에게 만찬을 베풀고 마지막 테스트를 준비한다. 그것은 형들이 자신에게 가질 죄책감을 해소시키기 위함일 것이다. 
- 마치 예수님께서 우리를 사랑하셔서 우리에게 수많은 기회와 환경을 제공하는 것처럼 요셉의 따듯한 마음이 느껴진다.
9. 적용(나): 
- 아들을 잃으면 잃으리라 말하는 이스라엘과 같은 믿음이 생기길 소망한다. 
- 무한히 기회를 주시는 예수님의 사랑에 감사하며 영적인 삶을 살아가도록 더욱 노력해야겠다.
10. 영적터치(단어/구절)
- 내가 자식을 잃게 되면 잃으리로다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-06', '창세기', '43장 21절~34절', ' ', '(창세기 43장)
21. 여관에 이르러 자루를 풀어본즉 각 사람의 돈이 전액 그대로 자루 아귀에 있기로 우리가 도로 가져왔고
22. 양식 살 다른 돈도 우리가 가지고 내려왔나이다 우리의 돈을 우리 자루에 넣은 자는 누구인지 우리가 알지 못하나이다
23. 그가 이르되 너희는 안심하라 두려워하지 말라 너희 하나님, 너희 아버지의 하나님이 재물을 너희 자루에 넣어 너희에게 주신 것이니라 너희 돈은 내가 이미 받았느니라 하고 시므온을 그들에게로 이끌어내고
24. 그들을 요셉의 집으로 인도하고 물을 주어 발을 씻게 하며 그들의 나귀에게 먹이를 주더라
25. 그들이 거기서 음식을 먹겠다 함을 들었으므로 예물을 정돈하고 요셉이 정오에 오기를 기다리더니
26. 요셉이 집으로 오매 그들이 집으로 들어가서 예물을 그에게 드리고 땅에 엎드려 절하니
27. 요셉이 그들의 안부를 물으며 이르되 너희 아버지 너희가 말하던 그 노인이 안녕하시냐 아직도 생존해 계시느냐
28. 그들이 대답하되 주의 종 우리 아버지가 평안하고 지금까지 생존하였나이다 하고 머리 숙여 절하더라
29. 요셉이 눈을 들어 자기 어머니의 아들 자기 동생 베냐민을 보고 이르되 너희가 내게 말하던 너희 작은 동생이 이 아이냐 그가 또 이르되 소자여 하나님이 네게 은혜 베푸시기를 원하노라
30. 요셉이 아우를 사랑하는 마음이 복받쳐 급히 울 곳을 찾아 안방으로 들어가서 울고
31. 얼굴을 씻고 나와서 그 정을 억제하고 음식을 차리라 하매
32. 그들이 요셉에게 따로 차리고 그 형제들에게 따로 차리고 그와 함께 먹는 애굽 사람에게도 따로 차리니 애굽 사람은 히브리 사람과 같이 먹으면 부정을 입음이었더라
33. 그들이 요셉 앞에 앉되 그들의 나이에 따라 앉히게 되니 그들이 서로 이상히 여겼더라
34. 요셉이 자기 음식을 그들에게 주되 베냐민에게는 다른 사람보다 다섯 배나 주매 그들이 마시며 요셉과 함께 즐거워하였더라

