2024년 12월07일 창세기 43장21절~34절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천):
자루에 넣은 돈: 21절 22절 23절 
요셉: 24절 26절 27절 29절 30절 32절 33절 34절
절하니/절하더라: 26절 28절
요셉의 형들: 21절 22절 28절 32절 33절 34절
음식을 차림: 31절 32절

4.주제만들기: 
동생 베냐민을 만난 요셉

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
자루속 돈뭉치 사건으로 두려워하는 요셉의 형들을 안심시키는 요셉의 청지기.
요셉에게 절 하는 그의 형들.
동생 베냐민을 보고 몰래 숨어서 우는 요셉.
자신의 형들에게 음식을 베푸는 요셉.
다른 사람보다 음식을 베냐민에게 다섯 배나 주는 요셉.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 꿈에도 그리던 혈육인 동생 베냐민을 만났다. 잠시 만난 후 정을 억제하지 못하고 숨어서 울었다. 

잠시 이 부분을 묵상할 때 마음이 아팠다. 17세 어린 나이에 강제적으로 헤어져 하루아침에 이산가족이 된 요셉이 약 23년의 얼마나 큰 인간적인 그리움이 있었을지 상상이 되지 않는다. 

그러면서 섬기는 탈북민들을 생각해 보게 된다. 탈북민들도 어쩌면 요셉 같은 삶을 살고 있을 것이라는 생각에 마음이 매여온다.

23년 전 하나님이 보여주신 꿈의 내용처럼 형들이 요셉에게 절하는 현실을 맞이하고 있다. 

분명 달라진 것은 요셉은 그저 꿈의 내용처럼 자신을 향하여 절하는 모습에 자랑하는 어린 요셉이 아니라 베냐민을 보고 사랑을 교감하는 성숙한 사랑의 사람 요셉으로 완성되어있는 모습을 볼 수 있다.

9.적용(나):
비전이 영혼사랑이라 생각하며 살아내야겠다.

10. 영적터치 (단어 또는 구절)
29절: 하나님이 네게 은혜 베푸시기를 원하노라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-07', '창세기', '44장 1절~10절', ' ', '(창세기 44장)
1.  요셉이 그의 집 청지기에게 명하여 이르되 양식을 각자의 자루에 운반할 수 있을 만큼 채우고 각자의 돈을 그 자루에 넣고
2. 또 내 잔 곧 은잔을 그 청년의 자루 아귀에 넣고 그 양식 값 돈도 함께 넣으라 하매 그가 요셉의 명령대로 하고
3. 아침이 밝을 때에 사람들과 그들의 나귀들을 보내니라
4. 그들이 성읍에서 나가 멀리 가기 전에 요셉이 청지기에게 이르되 일어나 그 사람들의 뒤를 따라 가서 그들에게 이르기를 너희가 어찌하여 선을 악으로 갚느냐
5. 이것은 내 주인이 가지고 마시며 늘 점치는 데에 쓰는 것이 아니냐 너희가 이같이 하니 악하도다 하라
6. 청지기가 그들에게 따라 가서 그대로 말하니
7. 그들이 그에게 대답하되 내 주여 어찌 이렇게 말씀하시나이까 당신의 종들이 이런 일은 결단코 아니하나이다
8. 우리 자루에 있던 돈도 우리가 가나안 땅에서부터 당신에게로 가져왔거늘 우리가 어찌 당신의 주인의 집에서 은 금을 도둑질하리이까
9. 당신의 종들 중 누구에게서 발견되든지 그는 죽을 것이요 우리는 내 주의 종들이 되리이다
10. 그가 이르되 그러면 너희의 말과 같이 하리라 그것이 누구에게서든지 발견되면 그는 내게 종이 될 것이요 너희는 죄가 없으리라

