은잔을 몰래 형제들 자루에 넣게한 요셉.
청지기를 통해 형들을 심문함(없어진 은잔).
목숨을 담보로 결백을 주장하는 형들.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 의도적으로 자신이 귀하게 사용하는 은잔을 베냐민 자루에 숨겨 넣었다. 그리고 고향을 향하는 그의 형제들을 청지기가 검색하게 시켰다. 
놀란 형제들은 목숨을 걸 정도로 자신들의 결백을 주장하고 있다.

요셉은 극적으로 스스로 사건을 연출시키는 듯하다. 요셉 측면에서 보면 이미 형제들의 자루에 돈과 양식을 넣은 것은 이미 용서와 자비를 베풀 준비가 되어있음을 알 수 있다.

다만 잠시 후 있을 자신의 신분을 밝히기 전 최종적으로 형들의 마음의 더욱 알고 싶었던 그것 같다.

처음부터 쉽게 자기 국무총리의 위치를 밝히지 않고 우회적인 방법과 촌극을 만들어가는 요셉을 생각하게 된다.

 아마 형들이 과거의 죄를 뉘우치고 스스로 회복하는 방법을 선택한 것 같다.

그런 면에서 요셉은 사람을 잘 다스리는 영적 통솔력까지 갖춘 것을 느끼게 해준다.

9.적용(나):
지혜로운 사람이 되도록 더욱 하나님께 간구 해야겠다.

