7. 하나님 찾기 (해석) 
8. 인간(해석):
- 그럴리 없을거라 확신하지만 베냐민의 자루에서 잔이 나오고 말았다. 망연자실한 형들은 자신들의 옷을 찢고 성으로 돌아갔다. 그리고 요셉의 앞에 바짝 엎드려 자신들을 변론한다. 이 때 유다가 나서서 이야기를 하는데 르우벤이 맞형임에도 유다가 나선 이유를 생각해본다.(요셉을 팔 때 르우벤은 없었지만... 가담한 것은 사실이니...)
- 아마 유다는 요셉을 노예로 팔고 난 후 한켠에는 자신의 잘못에 대한 찔림이 있었던 것 같다. 이스라엘이 사랑하는 아들이 또 떠나갈 수 있는 상황에서 과거와 같이 동생을 버리는 것이 아니라 적극적으로 동생을 지키려는 모습을 보여준다. 
- 유다의 말에는 어떠한 변명거리도 없다. 하나님이 우리의 죄악을 찾아내셨음을 고백하고 모든 형들과 베냐민까지 종이 되겠다고 선언한다. 유다와 형들은 요셉을 노예로 팔았지만 그로인한 죄책감이 상당했을 것이다. 다신 과거와 같은 죄는 짓지 않겠다는 강한 의지가 보인다. 
- 요셉은 유다의 반응이 얼마나 감사했을까? 자신과 형들 모두를 회복시킬 수 있는 마지막 테스트를 형들이 잘 선택해주길 바랬을 것이다. 요셉은 더 강하게 몰아붙인다. 베냐민만을 종으로 삼겠다고 선언한다. 요셉은 형들이 자신의 존재를 알게 되었을 때 죄책감과 죄악에서 벗어나고 하나님을 깊이 체험할 수 있는 제대로 된 판을 깔아주었다. 
- 유다는 과거의 죄에서 벗어나고 싶었을 것이다. 잊으려해도 잊혀지지 않는 과거의 나의 죄와 동일한 죄를 짓지 않으려 큰 결단을 하고 베냐민을 보호한다. 
9. 적용(나): 
- 하나님의 은혜로 우리는 구원 받았고, 죄에서 벗어날 수 있게 되었음을 감사드린다. 하나님께선 우리의 연약함을 자신의 능력으로 채워주길 바라신다. 그 분의 능력을 의지하고 죄악된 모습에서 벗어나길 소망한다.
- 유다가 베냐민을 지켰던 것처럼 하나님의 사랑을 받은 우리도 누군가를 지켜주어야 한다. 새터민을 더욱 사랑해야겠다.
10. 영적터치(단어/구절)
- 하나님이 종들의 죄악을 찾아내셨으니 우리와 이 잔이 발견된 자가 다 내 주의 노예가 되겠나이다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-09', '창세기', '44장 21절~34절', '약속을 지키는 유다', '창세기 44장
21   주께서 또 종들에게 이르시되 그를 내게로 데리고 내려와서 내가 그를 보게 하라 하시기로
22   우리가 내 주께 말씀드리기를 그 아이는 그의 아버지를 떠나지 못할지니 떠나면 그의 아버지가 죽겠나이다
23   주께서 또 주의 종들에게 말씀하시되 너희 막내 아우가 너희와 함께 내려오지 아니하면 너희가 다시 내 얼굴을 보지 못하리라 하시기로
24   우리가 주의 종 우리 아버지에게로 도로 올라가서 내 주의 말씀을 그에게 아뢰었나이다
25   그 후에 우리 아버지가 다시 가서 곡물을 조금 사오라 하시기로
26   우리가 이르되 우리가 내려갈 수 없나이다 우리 막내 아우가 함께 가면 내려가려니와 막내 아우가 우리와 함께 가지 아니하면 그 사람의 얼굴을 볼 수 없음이니이다
27   주의 종 우리 아버지가 우리에게 이르되 너희도 알거니와 내 아내가 내게 두 아들을 낳았으나
28   하나는 내게서 나갔으므로 내가 말하기를 틀림없이 찢겨 죽었다 하고 내가 지금까지 그를 보지 못하거늘
29   너희가 이 아이도 내게서 데려 가려하니 만일 재해가 그 몸에 미치면 나의 흰 머리를 슬퍼하며 스올로 내려가게 하리라 하니
30   아버지의 생명과 아이의 생명이 서로 하나로 묶여 있거늘 이제 내가 주의 종 우리 아버지에게 돌아갈 때에 아이가 우리와 함께 가지 아니하면
31   아버지가 아이의 없음을 보고 죽으리니 이같이 되면 종들이 주의 종 우리 아버지가 흰 머리로 슬퍼하며 스올로 내려가게 함이니이다
32   주의 종이 내 아버지에게 아이를 담보하기를 내가 이를 아버지께로 데리고 돌아오지 아니하면 영영히 아버지께 죄짐을 지리이다 하였사오니
33   이제 주의 종으로 그 아이를 대신하여 머물러 있어 내 주의 종이 되게 하시고 그 아이는 그의 형제들과 함께 올려 보내소서
34   그 아이가 나와 함께 가지 아니하면 내가 어찌 내 아버지에게로 올라갈 수 있으리이까 두렵건대 재해가 내 아버지에게 미침을 보리이다

