8.인간(해석)
- 한 때 아버지 집을 떠나 이방인들과 가까이 지내고. 
- 며느리와 동침하는 실수까지 범한 유다.
- 그 유다가 어떤 계기가 있어 뉘우쳤는지는 정확히 알 수 없으나, 
- 아버지께 돌아와 형제들과 함께 살고 있고,
- 이제는 아버지께 약속한 것을 지키고자 목숨을 걸고 요셉을 설득한다.
- 유다의 말을 통해 아버지 야곱이 자신을 얼마나 사랑하고 
- 그리워하는지를 듣게 된 요셉은 감정이 복받쳐 올랐을 것이다.
- 요셉은 친어머니의 아들이자 자신의 친동생인 베내민을 야곱이 그토록 사랑하고
- 자기 몸처럼 여긴다는 말을 듣고 가슴이 뜨거워졌을 것이다
- 유다는 아버지와의 약속을 지키기 위해, 
- 목숨을 걸고 베냐민 대신 종이 되어 애굽에 남고자 한다.
- 그리고 이것은 아버지뿐만 아니라 나아가 형제들과 
- 고향에서 식량을 기다리는 온 가족의 생명을 지키기 위한 희생이었다
- 요셉은 아버지를 향한 유다의 사랑과 희생하는 모습을 보며 
- 여러 가지 생각이 떠올랐을 것이다.

