7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 형들 앞에서 억누르고 있는 정을 더는 참지 못하고 대서 통곡을 한다. 그리고 두려워하는 형들을 안심시킨 후 이렇게 말한다.

 "하나님이 생명을 구원하시려고 나를 당신들보다 먼저보내셨나니." 얼마나 영적으로 성숙한 모습일까? 

이성적으로는 요셉도 분명히 기억하고 있다. 형들이 자신을 애굽에 팔았던 사실을 그런데도 요셉은 용서를 넘어 큰 계획을 세우신 하나님의 비전을 깨우친 것이다.

약 22년 전에 하나님이 보여주셨던 꿈은 단지 자신의 높아짐을 위함이 아닌 구원의 하나님이신 것을 알게 되었다고 생각이 된다. 

요셉은 하나님이 절대적 주권자임을 받아들이고 형들을 더는 미워하지 않는 겸손히 하나님을 높여드리는 믿음의 사람으로 승화된 것 같다.

우리도 때때로 고난을 받을 수 있는데 결국에는 모든 것이 하나님의 사랑을 알고 그 뜻을 통하여 하나님이 얼마나 영혼을 사랑하며 영혼 구원에 관심을 두고 계신 것을 더욱 깨우치게 된다.

9.적용(나):
모든 것을 선하게 인도하시는 하나님을 더욱 찬양하는 삶을 살아내야겠다.

