5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 요셉이 아직 흉년이 5년 더 남았음을 알리고
- 모든 가족을 고센 땅으로 초대함
- 요셉이 형들과 베냐민이 보고 있는 대로 내가 애굽의 총리가 되었음을 
- 아버지께 말씀드리고 모시고 오라고 말함
- 베냐민과 서로 안고 울고, 형들과도 입맞추고 부둥켜 안고 울었다.
- 형들이 그제야 요셉과 대화를 했다.
- 바로와 신하들이 요셉의 형제들이 왔다는 소식을 듣고 기뻐하였다
- 바로는 요셉의 부친과 가족을 모시고 오라고 명하며, 좋은 땅을 주겠노라 말함
- 또한 모시고 올 수레도 여러 대 주겠노라 말하며
- 좋은 땅을 줄 것이니 물건을 아끼지 말라 말함

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 자신이 요셉임을 밝히고 가족을 초대한 요셉
- 친동생 베냐민과 어서 인사하고 말하고 싶었을 것이다
- 베냐민을 끌어안으며, 자신에게 안기는 베냐민의 체온을 느끼며 눈물과 콧물을 흘리며 기뻐했을 것이다. 
- 우리나라 이산가족 상봉 때를 생각하면 비슷할까.
- 요셉의 형들은 애굽 총리가 자신의 동생이라는 말을 듣고
- 현실 감각이 없기도 하고, 동생의 꿈 이야기가 떠오르기도 하고, 
- 이 모든 것이 하나님의 구원 계획이라는 것 등 
- 여러 가지를 생각하느라 혼란에 빠졌을 것이다.
- 멍하니 있다가 요셉이 울면서 내려와 베냐민과 안으며 인사하고,
- 자신들에게 와서 인사하자 그제야 말을 하기 시작한다
- 총리님이 내 동생 요셉이라니요. 요셉아 정말 미안했다. 그 꿈이 현실이 되었구나. 등등
- 바로와 신하들이 요셉의 형제들이 왔다는 소식을 듣고 함께 기뻐한다.
- 요셉이 애굽에서 그동안 얼마나 중요한 역할을 선하게 잘 수행했는지 엿볼 수 있는 대목이다   
- 왕과 신하가 함께 기뻐한 것으로 보아,
- 왕에게 신임을 받을 뿐 아니라 신하들에게도 선한 리더였음을 추측해 볼 수 있다
- 왕이 그런 요셉의 가족을 후히 대우한다

9.적용(나) 
- 새터민의 가족에 대한 그리움이 얼마나 클지 생각해 본다.
- 그들에게 한 명의 형제가 되어 줄 수 있으면 좋겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-12', '창세기', '45장 21절~28절', '요셉이 살아있단 소식을 듣게된 이스라엘', '[창45:21-28]
21 이스라엘의 아들들이 그대로 할새 요셉이 바로의 명령대로 그들에게 수레를 주고
 길 양식을 주며
22 또 그들에게 다 각기 옷 한 벌씩을 주되 베냐민에게는 은 삼백과 옷 다섯 벌을 주고
23 그가 또 이와 같이 그 아버지에게 보내되 수나귀 열 필에 애굽의 아름다운 물품을 실리고 암나귀 열 필에는 아버지에게 길에서 드릴 곡식과 떡과 양식을 실리고
24 이에 형들을 돌려보내며 그들에게 이르되 당신들은 길에서 다투지 말라 하였더라
25 그들이 애굽에서 올라와 가나안 땅으로 들어가서 아버지 야곱에게 이르러
26 알리어 이르되 요셉이 지금까지 살아 있어 애굽 땅 총리가 되었더이다 야곱이 그들의 말을 믿지 못하여 어리둥절 하더니
27 그들이 또 요셉이 자기들에게 부탁한 모든 말로 그에게 말하매 그들의 아버지 야곱은 요셉이 자기를 태우려고 보낸 수레를 보고서야 기운이 소생한지라
28 이스라엘이 이르되 족하도다 내 아들 요셉이 지금까지 살아 있으니 내가 죽기 전에 가서 그를 보리라 하니라

