4. 주제만들기: 요셉이 살아있단 소식을 듣게된 이스라엘
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 요셉은 바로의 명령대로 수레를 형들에게 주고 옷을 한번씩 주었는데 베냐민에게는 은 삼백과 다섯벌의 옷을 줌
- 수나귀와 암나귀에 아름다운 물품과 양식을 실어주며, 가는 길에 서로 다투지 말라고 함
- 형들은 가나안에 도착하여 아버지 야곱에게 요셉이 애굽의 총리로 살아있다고 말함
- 아버지 야곱은 믿지 못했지만 요셉이 보낸 수레를 보고 기운이 소생해 족하도다라고 말하며 죽기전에 그를 보리라 함 
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 요셉은 형들에게 좋은 옷을 한 벌씩 주었고, 특별히 베냐민에겐 은 삼백과 다섯 벌의 옷을 주었다. 베냐민이 요셉이 없는 동안 형들 사이에서 얼마나 위축되며 살아왔을까? 요셉은 베냐민을 위로해주고 싶었을 것이다. 그리고 이 기간을 잘 버텨준 동생이 기특했을 것이다. 
- 요셉은 놀란 형들이 돌아가면서 서로 다투지 않도록 말하며 그들을 안심시켰다. 하나님의 계획을 깨달은 요셉이기에 과거 형들의 행동을 쉽게 용서하고 잊을 수 있게 되었을 것이다.
- 요셉이 살아있단 소식을 전해들을 때 성경에서 야곱이라 표현한 것은 어떤 의미일까? 요셉을 잃고, 영적으로 침체되어 있던 이스라엘의 모습을 표현하고자 했을까? 요셉이 살아있단 소식을 듣고, 수레가 온 것을 보고 그제서야 이스라엘은 생기가 생겼다. 아들을, 가족을 잃는 슬픔이 얼마나 컸을지 생각해본다. 요셉이 살아있다는 소식을 듣고 침체되었던 이스라엘은 영혼이 되살아난 것 같은 힘을 얻게 된 것이다. 하나님께선 우리가 상상하지 못한 방법으로 우리를 위로하신다. 
9. 적용(나): 
- 오늘 등산 행사에서 새터민들을 많이 위로하고 격려해야겠다.
- 가족을 보지 못하는 슬픔을 그 동안 헤아리지 못했다. 북한에 있을 가족 중 상심이 큰 분들도 계실텐데 그들을 위해 기도해야겠다. 
10. 영적터치(단어/구절)
- 기운이 소생한지라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-13', '창세기', '46장 1절~10절', ' ', '(창세기 46장)
1.  이스라엘이 모든 소유를 이끌고 떠나 브엘세바에 이르러 그의 아버지 이삭의 하나님께 희생제사를 드리니
2. 그 밤에 하나님이 이상 중에 이스라엘에게 나타나 이르시되 야곱아 야곱아 하시는지라 야곱이 이르되 내가 여기 있나이다 하매
3. 하나님이 이르시되 나는 하나님이라 네 아버지의 하나님이니 애굽으로 내려가기를 두려워하지 말라 내가 거기서 너로 큰 민족을 이루게 하리라
4. 내가 너와 함께 애굽으로 내려가겠고 반드시 너를 인도하여 다시 올라올 것이며 요셉이 그의 손으로 네 눈을 감기리라 하셨더라
5. 야곱이 브엘세바에서 떠날새 이스라엘의 아들들이 바로가 그를 태우려고 보낸 수레에 자기들의 아버지 야곱과 자기들의 처자들을 태우고
6. 그들의 가축과 가나안 땅에서 얻은 재물을 이끌었으며 야곱과 그의 자손들이 다함께 애굽으로 갔더라
7. 이와 같이 야곱이 그 아들들과 손자들과 딸들과 손녀들 곧 그의 모든 자손을 데리고 애굽으로 갔더라
8. 애굽으로 내려간 이스라엘 가족의 이름은 이러하니라 야곱과 그의 아들들 곧 야곱의 맏아들 르우벤과
9. 르우벤의 아들 하녹과 발루와 헤스론과 갈미요
10. 시므온의 아들은 여무엘과 야민과 오핫과 야긴과 스할과 가나안 여인의 아들 사울이요

