3.반복단어 찾기(형광펜 사용 추천)
브엘사바: 1절 5절
야곱: 2절(3) 4절(2) 5절 6절 7절 8절 
하나님: 1절 2절 3절(3) 4절
애굽으로 감: 6절 8절
자손: 6절 7절

4.주제만들기: 
온 기족들과 함께 애굽으로 떠나는 야곱

5.하나님 찾기 (관찰)
이상 중에 이스라엘 에게 나타나 부르시는 하나님.
두려워하는 야곱에게 용기를 주시며 그를 애굽으로 떠나라고 지시 하시는 하나님.
그에게 큰 민족을 이루리라 말씀 하심.
함께 하시겠다고 약속하심.

6.인간 찾기(관찰)
애굽으로 온가족과 더불어 떠나는 것을 두려워하는 야곱.
하나님 말씀에 순종하여 떠나는 야곱.

7.하나님 찾기(해석)
두려워하는 야곱을 부르시고 애굽으로 가라 명령하시는 하나님.
하나님은 야곱의 아버지 이삭과 할아버지인 아브라함에게 큰 민족을 이룰 것을 이미 약속하신 바 있다.
그 약속을 지키사 후대인 야곱에게 재차 확인하여 주신다.

8.인간 찾기 (해석)
내용을 보면 야곱은 매우 두려워하는 상태임을 알 수 있다. 인간적인 측면에서 보면 충분히 이해된다. 노년의 나이에 오랫동안 정착한 고향을 떠난다는 것은 매우 부담스러운 일일 것이다. 

과거에도 한 사건으로 오랜 세울 동안 타향살이를 했던 야곱이었다. 그런데도 그에게 다가오신 하나님의 명령을 순종함으로 애굽으로 떠난다. 

야곱이 하나님의 음성을 들을 수 있었던 그것 중 하나는 브엘세바로 가서 희생 제사를 지낸 그것도 한몫하였다고 볼 수 있다. 브엘세바의 의미는 언약의 의미가 내포되어 있다. 

9.적용(나):
새로운 변화를 이끄시는 주님의 음성에 귀를 기울이고 순종하는 삶을 살아내야겠다.

10. 영적터치 (단어 또는 구절)
46절: 브엘세바

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-14', '창세기', '46장 11절~20절', ' ', '(창세기 46장)
11. 레위의 아들은 게르손과 그핫과 므라리요
12. 유다의 아들 곧 엘과 오난과 셀라와 베레스와 세라니 엘과 오난은 가나안 땅에서 죽었고 베레스의 아들은 헤스론과 하물이요
13. 잇사갈의 아들은 돌라와 부와와 욥과 시므론이요
14. 스불론의 아들은 세렛과 엘론과 얄르엘이니
15. 이들은 레아가 밧단아람에서 야곱에게 난 자손들이라 그 딸 디나를 합하여 남자와 여자가 삼십삼 명이며
16. 갓의 아들은 시뵨과 학기와 수니와 에스본과 에리와 아로디와 아렐리요
17. 아셀의 아들은 임나와 이스와와 이스위와 브리아와 그들의 누이 세라며 또 브리아의 아들은 헤벨과 말기엘이니
18. 이들은 라반이 그의 딸 레아에게 준 실바가 야곱에게 낳은 자손들이니 모두 십육 명이라
19. 야곱의 아내 라헬의 아들 곧 요셉과 베냐민이요
20. 애굽 땅에서 온의 제사장 보디베라의 딸 아스낫이 요셉에게 낳은 므낫세와 에브라임이요

