2024년 12월15일 창세기 46장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
아들: 11절 12절 13절 14절 16절 17절 18절
낳은: 18절 20절

4.주제만들기: 
야곱의 가족들 그리고 이름.

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
나열된 야곱의 가족들 그리고 이름.
애굽으로 내려간 이스라엘 가족.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱은 대가족을 이끌고 고향 가나안 땅을 떠나 애굽으로  대이동을 한다. 

그러면서 성경은 야곱(이스라엘) 가족의 손주 이름까지, 구체적으로 나열하였다. 하나님이 아브라함과 이삭 그리고 야곱에게 주신 자손 번성의 복을 볼 수 있다. 

그런데도 유독 12절에 유다 자손에 관한 내용이 옥에 티처럼 들어온다. 자손의 축복 계보 속에 유다의 자녀 ''엘과 오난''은 가나안 땅에서 죽었다고 되어있다. 

무슨 이유로 그들이 죽었는지 기록하지 않지만 적어도 아비 유다는 많은 고통 기운데 살았을 것으로 생각된다. 

사실 요셉이 그의 형들에 대한 시험 곧 요셉이 정을 억제하지 못하고 자신의 신분을 알렸던 계기가 유다의 행동 때문이었다고 볼 수 있다. 베냐민 대신 자신이 노예로 잡혀있겠다고 말하였었다. 

어쩌면 특별히 사랑했던 요셉을 잃었다고 슬퍼하는 야곱의 심정을 느꼈던 사람이 야곱의 아들중 유다가 가장 유력했다고 생각된다. 유다는  그 고통이 얼마나 큰지를 이미 알고 있었다.

그러한 측면에서 하나님은 나를 포함한 모든 인간의 죄를 용서하시고 구원하시기 위하여 가장 사랑하는 독생자 예수를 희생물로 주셨다. 그 사랑이 얼마나 큰지 절대로 가늠되지 않는다. 

9.적용(나):
하나님의 크신 사랑을 더욱 묵상 해야겠다.

10. 영적터치 (단어 또는 구절)
12절: 엘과 오난은 가나안 땅에서 죽었고

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-15', '창세기', '46장 21절~34절', '요셉을 만나는 야곱', '[창46:21-34]
21 베냐민의 아들 곧 벨라와 베겔과 아스벨과 게라와 나아만과 에히와 로스와 뭅빔과 훕빔과 아릇이니
22 이들은 라헬이 야곱에게 낳은 자손들이니 모두 십사 명이요
23 단의 아들 후심이요
24 납달리의 아들 곧 야스엘과 구니와 예셀과 실렘이라
25 이들은 라반이 그의 딸 라헬에게 준 빌하가 야곱에게 낳은 자손들이니 모두 칠 명이라
26 야곱과 함께 애굽에 들어간 자는 야곱의 며느리들 외에 육십육 명이니 이는 다 야곱의 몸에서 태어난 자이며
27 애굽에서 요셉이 낳은 아들은 두 명이니 야곱의 집 사람으로 애굽에 이른 자가 모두 칠십 명이었더라
28 야곱이 유다를 요셉에게 미리 보내어 자기를 고센으로 인도하게 하고 다 고센 땅에 이르니
29 요셉이 그의 수레를 갖추고 고센으로 올라가서 그의 아버지 이스라엘을 맞으며 그에게 보이고 그의 목을 어긋맞춰 안고 얼마 동안 울매
30 이스라엘이 요셉에게 이르되 네가 지금까지 살아 있고 내가 네 얼굴을 보았으니 지금 죽어도 족하도다
31 요셉이 그의 형들과 아버지의 가족에게 이르되 내가 올라가서 바로에게 아뢰어 이르기를 가나안 땅에 있던 내 형들과 내 아버지의 가족이 내게로 왔는데
32 그들은 목자들이라 목축하는 사람들이므로 그들의 양과 소와 모든 소유를 이끌고 왔나이다 하리니
33 바로가 당신들을 불러서 너희의 직업이 무엇이냐 묻거든
34 당신들은 이르기를 주의 종들은 어렸을 때부터 지금까지 목축하는 자들이온데 우리와 우리 선조가 다 그러하니이다 하소서 애굽 사람은 다 목축을 가증히 여기나니 당신들이 고센 땅에 살게 되리이다

