4. 주제만들기: 요셉을 만나는 야곱
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 라헬이 야곱으로부터 낳은 자손은 14명이고 종 빌하가 낳은 자손은 7명이며, 야곱이 애굽 땅에 데려간 자손은 며느리 제외하고 66명으로 요셉의 자손을 포함하면 70명이 됨
- 야곱은 유다를 보내어 요셉을 고센 땅으로 인도하고 요셉은 수레를 갖추고 고센으로 가서 아버지를 만남.
- 요셉은 바로를 만날 때 직업을 목자라 하도록 명하고, 고센 땅에 살게 될 것을 말함
7. 하나님 찾기 (해석) 
- 아브라함의 자손을 번성시키신 하나님
8. 인간(해석):
- 66명이나 되는 대가족을 이끌고 가나안을 떠나 애굽으로 온 야곱은 꿈에 그리던 아들을 만나게 된다. 얼마나 기쁘고 슬펐을까? 그들의 기쁨을 헤아릴 수 없을 것이다. 동시에 하나님께서 기적과 같이 아들을 만나게 하시고, 기적과 같이 자신의 가족을 살리신 것에 감사하였을 것이다. 
- 요셉 역시 아버지를 만났다는 것이 꿈꾸는 것과 같을 것이다. 나를 너무도 사랑했던 아버지, 아버지의 품을 떠나 산 날이 훨씬 많아진 지금 아버지를 만난다는 것은 벅찬 감동이었을 것이다.
- 야곱은 대가족이 되었음에도 어려움을 직면했다. 하나님께 복을 받았음에도 어려운 상황은 누구나 직면할 수 있는 것이다. 하나님은 굶어 죽을 위기에 처한 야곱의 가족을 말도 안되는 상황으로 반전시키셨다. 우리 모두에게 이러한 일이 벌어지는 것은 충분히 가능하다. 제한 없으신 하나님의 능력을 의지해야한다.
9. 적용(나): 
- 소망을 품고, 부모님과의 만남을 기다리는 새터민들을 위해 기도해야겠다.
- 하나님의 능력을 제한하지 말고 그 분을 더욱 붙잡아야겠다. 
10. 영적터치(단어/구절)
- 내가 네 얼굴을 보았으니 지금 죽어도 족하도다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-16', '창세기', '47장 1절~10절', '고센 땅으로 가다', '창세기 47장
1   요셉이 바로에게 가서 고하여 이르되 내 아버지와 내 형들과 그들의 양과 소와 모든 소유가 가나안 땅에서 와서 고센 땅에 있나이다 하고
2   그의 형들 중 다섯 명을 택하여 바로에게 보이니
3   바로가 요셉의 형들에게 묻되 너희 생업이 무엇이냐 그들이 바로에게 대답하되 종들은 목자이온데 우리와 선조가 다 그러하니이다 하고
4   그들이 또 바로에게 고하되 가나안 땅에 기근이 심하여 종들의 양 떼를 칠 곳이 없기로 종들이 이 곳에 거류하고자 왔사오니 원하건대 종들로 고센 땅에 살게 하소서
5   바로가 요셉에게 말하여 이르되 네 아버지와 형들이 네게 왔은즉
6   애굽 땅이 네 앞에 있으니 땅의 좋은 곳에 네 아버지와 네 형들이 거주하게 하되 그들이 고센 땅에 거주하고 그들 중에 능력 있는 자가 있거든 그들로 내 가축을 관리하게 하라
7   요셉이 자기 아버지 야곱을 인도하여 바로 앞에 서게 하니 야곱이 바로에게 축복하매
8   바로가 야곱에게 묻되 네 나이가 얼마냐
9   야곱이 바로에게 아뢰되 내 나그네 길의 세월이 백삼십 년이니이다 내 나이가 얼마 못 되니 우리 조상의 나그네 길의 연조에 미치지 못하나 험악한 세월을 보내었나이다 하고
10   야곱이 바로에게 축복하고 그 앞에서 나오니라

