4.주제 만들기: 고센 땅으로 가다

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 요셉이 바로에게 자신의 가족이 고센 땅에 왔음을 알리고
- 형들 중 다섯 명을 바로에게 보임
- 바로가 형들에게 생업이 무엇이냐 묻자
- 형들은 요셉이 시킨대로 대대로 목자라고 대답하고
- 고센 땅에 머무르게 해달라고 요청한다 
- 바로가 요셉에게 네 가족들이 고센 땅에 머무르게 하고
- 그들 중 능력 있는 자가 있다면 자기 가축도 관리하라고 명함
- 요셉아 야곱을 바로 앞에 서게 하니 야곱이 바로에게 축복함
- 바로가 야곱에게 나이를 물음
- 야곱이 백삼년을 살았고 험악한 세월을 보내었다 대답함
- 야곱이 바로를 축복하고 그 앞에서 나옴

7.하나님 찾기 (해석) 

8.인간(해석)
- 형들은 요셉이 시킨 대로 바로에게 대답함
- 요셉은 지독한 기근에서 가족을 살릴 수 있는 지혜를 발휘했고,
- 형들은 이 기근 속에서 살 수 있는 유일한 방법을 수행했다.
- 이 지혜와 유일한 방법은 요셉에게서 난 것도 아니요, 
- 형들에게서 난 것도 아니다.
- 오직 하나님의 구원 계획과 섭리에 의한 지혜요 살 방법이었다.
- 바로가 고센 땅에 거주하는 것을 허락하고,
- 나아가 자신의 가축까지 관리할 수 있는 기회를 주었다.
- 요셉은 야곱을 바로 앞에 서게 하였다.
- 이것은 요셉이 자기 아버지를 바로에게 소개하는 것을 넘어 
- 바로가 말한 능력 있는 자를 바로 앞에 소개한 것이라고 볼 수 있다.
- 야곱은 하나님의 사람으로서 바로를 축복하였고
- 바로는 나이가 얼마냐 물었고
- 이는 존중의 의미도 있지만, 
- 동시에 나이가 그렇게 많은데 가축을 관리할 수 있겠는가 묻는 것으로 볼 수 있다.  
- 야곱은 조상들에 비하면 짧은 세월이지만, 험악한 백삼십 년을 보내었다 대답했고
- 이것은 비록 나이는 많지만, 이 정도 일은 아무것도 아니다 라고 대답한 것으로 볼 수 있다.
- 야곱은 하나님의 사람으로서 바로를 한 번 더 축복하고 나왔다

9.적용(나)
- 내가 존재하고, 나아가고, 구원받고, 앞날을 기대하며 기도하는 것은 내가 하는 것이 아니요.
- 하나님께서 하시는 것이고, 은혜로 주신 것이다.
- 내게 생명을 주셨고, 또 위급할 때 피할 길을 주시는 
- 하나님을 의지하며, 사랑하며, 감사하며 살아가야겠다.
- 나는 영적으로 축복하여도, 상대방은 육적으로 대답할 수 있다.
- 그때 육적으로 반응하지 않고, 영적으로 축복하는 그런 사람이 돼야겠다.

10. 영적터치(단어/구절)  
  10   야곱이 바로에게 축복하고 그 앞에서 나오니라
11. 믿음과 회개 및 감사기도로 마무리
