기근이 더욱 심해짐

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
기근이 더욱 심해져서 애굽과 가나안 사람들이 돈을 주고 요셉에게 곡식을 삼.
계속되는 기근으로 돈도 떨어져 그들의 가축을 주고 곡식을 삼.
그 다음 해에는 토지도 팔고 곡식을 장만한 백성들.
바로왕이 모든 것을 소유함.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉은 7년의 심한 기근을 이미 예측하여 창고에 충분한 곡식을 보관하였다. 애굽과 가나안 지역에 사는 사람들은 돈을 주고 곡식을 샀다. 

해가 거듭될수록 더욱 심한 기근을 견디지 못하고 애굽백성은 가축을 요셉에게 주고 곡식을 샀다.
급기야 그마저도 떨어져  토지도 요셉에게 매각하고 곡식을 사는 상황까지 왔다.

요셉은 백성들에게 받은 모든 돈과 가축들 그리고 토지를 바로 왕에게 전달함으로써 충직하고 지혜로운 국무총리 역할을 잘한 것 같다.

덕분에 백성들은 당장 아사를 피할 수 있게 되어 다행이고 바로는 부강한 왕권과 통치력을 얻게 되었다.

요셉은 7년의 가뭄을 예측한 것으로 인정받아 죄수 신분에서 국무총리가 되어 애굽 백성뿐만 아니라 가나안 백성들까지 살리는데 귀하게 쓰임을 받았다. 하지만 이 모든 것을 알려주신 분은 하나님이시다. 

7년의 예측으로도 큰 영향을 끼치는데 영원한 시간을 다스리고 모든 미래를 이미 아시는 분이 우리 참 아버지 하나님이신 것을 생각하니 큰 안심과 위로가 된다. 

전능하신 하나님을 더욱 가까이하고 의지하는 삶만이 복된 인생인 것을 알게 된다.


9.적용(나):
전능하신 하나님을 더욱 의지하며 살아내야겠다.


10. 영적터치 (단어 또는 구절)
