4.주제 만들기: 토지법의 탄생과 이스라엘의 번성

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 요셉이 애굽 백성을 성읍들에 옯김
- 제사장들의 토지는 사지 않음
- 제사장들은 바로에게서 녹을 받기 때문에 토지를 팔지 않을 수 있음
- 요셉이 백성에게 토지법을 공포하되,
- 오분의 일은 바로(국가)에게 상납하고,
- 오분의 사는 백성들이 원하는 대로 사용하도록 함.
- 백성들은 살 수 있음에 감사하며 바로의 종이 되겠다고 말함. 
- 이스라엘 족속은 고센 땅에 거주하며 거기서 생육하고 번성함
- 야곱이 애굽 땅에 십칠 년을 거주했고 나이가 백사십칠 세가 됨
- 이스라엘이 요셉을 불러 내가 죽거든 애굽이 아니라 조상의 묘지에 장사하라고 말하고
- 요셉이 맹세하도록 함
- 요셉이 이스라엘의 말대로 맹세함
- 이스라엘이 침상 머리에서 하나님을 경배함

7.하나님 찾기 (해석) 

8.인간(해석)
- 풍년 때 오분의 일을 거둬 들이게 하여 흉년을 대비한 요셉은
- 흉년에 백성들의 땅을 사고 그 땅에서 난 것의 오분의 일을 바치게 하였다
- 우리는 요셉의 지혜를 본받아 평소 우리가 사용하는 물질의 오분의 일을 모아둘 필요가 있다.
- 이스라엘은 구원을 받았고,
- 이집트 백성은 토지법의 구조 속에서 살아가게 되었다.
- 요셉이 정한 이 토지법에 의하면, 
- 일하여 얻은 것의 80% 일한 사람의 것이고, 
- 20%는 나라 것이다. 
- 오늘날의 사회 구조는 그렇지 않다.
- 우리 기독교인들이 수입을, 물질을 어떻게 대하고 사용해야 할 것인지 고민해야 할 부분이다.
- 이스라엘 족속은 극심한 기근 중에 풍요로운 고센 땅에 정착하여 생육하고 번성하였다.
- 하나님의 구원의 역사는 신묘막측하다. 
- 이스라엘은 조상들과 같이 가나안 땅에 뭍히기를 소원하였다.
- 하나님이 약속하신 땅에 뭍히길 간절히 원하고, 
- 후손들도 그곳에 머물기를 간절히 바라는 것임을 알 수 있다.

9.적용(나)
- 세상은 매우 위태롭지만, 구원받은 사람들은 날로 늘어가고 있다(지금도 중동 지방 아프리카 지방은 급속하게 늘어나고 있다).
- 하나님께 감사할 뿐이다.
- 한편 주위를 돌아보면 어려운 사람들이 너무도 많다.
- 일하고 싶어도 일자리가 없는 사람, 일을 열심히 해도 남들보다 적게 버는 사람, 월세 낼 돈이 없는 사람, 경제난에 목숨을 끊는 사람.
- 어제는 학생들과 연탄 나눔을 하고 왔다.
- 강남의 고층 빌딩과 아파트들 바로 옆에,
- 무허가 판자촌이 있다. 무허가라 인터넷 지도로 검색도 안 되는 곳이다.
- 연탄을 나누며, 마음이 따뜻해 지기도 하지만,
- 이 사회에 대해 고민하게 되는 날이었다.
- 요셉의 토집법의 지혜는 애굽 백성과 함께 국가도 살리는 대단한 것이었음을 다시 한번 느낀다. 

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-19', '창세기', '48장 1절~10절', '이스라엘의 자녀로 인정 받은 에브라임과 므낫세', '[창48:1-10]
1 이 일 후에 어떤 사람이 요셉에게 말하기를 네 아버지가 병들었다 하므로 그가 곧 두 아들 므낫세와 에브라임과 함께 이르니
2 어떤 사람이 야곱에게 말하되 네 아들 요셉이 네게 왔다 하매 이스라엘이 힘을 내어 침상에 앉아
3 요셉에게 이르되 이전에 가나안 땅 루스에서 전능하신 하나님이 내게 나타나사 복을 주시며
4 내게 이르시되 내가 너로 생육하고 번성하게 하여 네게서 많은 백성이 나게 하고 내가 이 땅을 네 후손에게 주어 영원한 소유가 되게 하리라 하셨느니라
5 내가 애굽으로 와서 네게 이르기 전에 애굽에서 네가 낳은 두 아들 에브라임과 므낫세는 내 것이라 르우벤과 시므온처럼 내 것이 될 것이요
6 이들 후의 네 소생은 네 것이 될 것이며 그들의 유산은 그들의 형의 이름으로 함께 받으리라
7 내게 대하여는 내가 이전에 밧단에서 올 때에 라헬이 나를 따르는 도중 가나안 땅에서 죽었는데 그 곳은 에브랏까지 길이 아직도 먼 곳이라 내가 거기서 그를 에브랏 길에 장사하였느니라 (에브랏은 곧 베들레헴이라)
8 이스라엘이 요셉의 아들들을 보고 이르되 이들은 누구냐
9 요셉이 그의 아버지에게 아뢰되 이는 하나님이 여기서 내게 주신 아들들이니이다 아버지가 이르되 그들을 데리고 내 앞으로 나아오라 내가 그들에게 축복하리라
10 이스라엘의 눈이 나이로 말미암아 어두워서 보지 못하더라 요셉이 두 아들을 이끌어 아버지 앞으로 나아가니 이스라엘이 그들에게 입맞추고 그들을 안고

