- 아버지,야곱,이스라엘(1,2,8,9,10절)
- 복(3,9절)
4. 주제만들기: 이스라엘의 자녀로 인정 받은 에브라임과 므낫세
5. 하나님 찾기 (관찰)
- 가나안 땅 루스에서 야곱에게 나타나셔서 복을 주시고 생육하고 번성하게 하여 많은 백성이 나고 이 땅은 후손에게 주어 영원한 소유가 되게 하겠다 말씀하심
6. 인간 찾기 (관찰)
- 이스라엘이 병들었다 함을 듣고 두 아들을 데리고 아버지를 찾은 요셉
- 요셉에게 과거 하나님의 축복을 말하며 요셉의 두 아들은 자신의 아들이 되리라 말하는 이스라엘
- 이들 후의 소생이 요셉의 자녀가 될 것이고, 이스라엘의 유산을 형들과 같이 므낫에와 에브라임도 받게 될 것이라고 함
- 이스라엘은 가나안 땅 에브랏(베들레헴)으로 가는 길목에 라헬을 묻어주었다고 말함
- 이스라엘은 요셉의 아들을 축복하기 위해 자신에게 데려오라 말함
7. 하나님 찾기 (해석) 
- 하나님의 구원 사역은 하나님의 뜻에 따라 하나님의 때에 이루어진다.
8. 인간(해석):
- 이스라엘은 요셉의 아들을 자신의 자녀로 인정하겠다고 선포하여 12지파가 완성되었다. 그러나 요셉은 자신의 사랑하는 아들 요셉에게 축복을 하지 않고 요셉의 자녀들에게 축복을 할 준비를 하고 있다. 자신보다 많은 것을 누리는 요셉에게 자신의 재산과 축복은 무의미했을까? 아니다. 이스라엘은 자신이 가장 사랑하는 아들 요셉에게 두배의 축복을 부어주고 싶었을 것이다. 하나님의 계획, 하나님의 구원 사역은 두 자녀를 통해 더 빠르고 크게 이스라엘이 번성하는 계기가 되었을 것이다.
- 요셉의 자녀는 므낫세와 에브라임인데 이스라엘을 만날 때 의도적으로 에브라임과 므낫세로 표기한다. 이스라엘이 어떤 선택을 하게 될지 보여주는 대목이다. 이스라엘이 의도적으로 둘째에게 더 큰 축복을 했을 수도 있지만 하나님의 구원은 누구에게나 주어져있다는 것으로 해석할 수 있다. 
- 므낫세와 에브라임의 자손을 통해 예수님이 나타나신게 아닌, 유다의 자손을 통해 예수님이 이 땅에 오셨듯, 하나님에게 축복과 구원은 온전히, 전적으로 하나님의 섭리로 이루어진다. 
9. 적용(나):
- 하나님의 은혜로 하나님을 믿게 되었음을 감사하다. 하나님의 은혜에 보답하기 위해 전도에 더욱 힘써야겠다. 
10. 영적터치(단어/구절)
- 이스라엘이 힘을 내어 침상에 앉아
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-20', '창세기', '48장 11절~22절', ' ', '(창세기 48장)
11. 요셉에게 이르되 내가 네 얼굴을 보리라고는 생각하지 못하였더니 하나님이 내게 네 자손까지도 보게 하셨도다
12. 요셉이 아버지의 무릎 사이에서 두 아들을 물러나게 하고 땅에 엎드려 절하고
13. 오른손으로는 에브라임을 이스라엘의 왼손을 향하게 하고 왼손으로는 므낫세를 이스라엘의 오른손을 향하게 하여 이끌어 그에게 가까이 나아가매
14. 이스라엘이 오른손을 펴서 차남 에브라임의 머리에 얹고 왼손을 펴서 므낫세의 머리에 얹으니 므낫세는 장자라도 팔을 엇바꾸어 얹었더라
15. 그가 요셉을 위하여 축복하여 이르되 내 조부 아브라함과 아버지 이삭이 섬기던 하나님, 나의 출생으로부터 지금까지 나를 기르신 하나님,
16. 나를 모든 환난에서 건지신 여호와의 사자께서 이 아이들에게 복을 주시오며 이들로 내 이름과 내 조상 아브라함과 이삭의 이름으로 칭하게 하시오며 이들이 세상에서 번식되게 하시기를 원하나이다
17. 요셉이 그 아버지가 오른손을 에브라임의 머리에 얹은 것을 보고 기뻐하지 아니하여 아버지의 손을 들어 에브라임의 머리에서 므낫세의 머리로 옮기고자 하여
18. 그의 아버지에게 이르되 아버지여 그리 마옵소서 이는 장자이니 오른손을 그의 머리에 얹으소서 하였으나
19. 그의 아버지가 허락하지 아니하며 이르되 나도 안다 내 아들아 나도 안다 그도 한 족속이 되며 그도 크게 되려니와 그의 아우가 그보다 큰 자가 되고 그의 자손이 여러 민족을 이루리라 하고
20. 그 날에 그들에게 축복하여 이르되 이스라엘이 너로 말미암아 축복하기를 하나님이 네게 에브라임 같고 므낫세 같게 하시리라 하며 에브라임을 므낫세보다 앞세웠더라
21. 이스라엘이 요셉에게 또 이르되 나는 죽으나 하나님이 너희와 함께 계시사 너희를 인도하여 너희 조상의 땅으로 돌아가게 하시려니와
22. 내가 네게 네 형제보다 세겜 땅을 더 주었나니 이는 내가 내 칼과 활로 아모리 족속의 손에서 빼앗은 것이니라

