8.인간 찾기 (해석)
야곱이 임종을 앞두고 요셉의 아들들에게 축복기도를 해준다.

 요셉은 장남인 므낫세가 차남인 에브라임보다 전통적으로 더욱 장자로써의 축복권을 받기를 원했다. 하지만 야곱은 차남인 에브라임에게 오른손으로 머리에 안수하고 장남인 므낫세에게는 왼손을 얹었다. 

요셉은 기뻐하지 않았지만, 야곱은 하나님의 뜻대로 자행하였다. 야곱은 손주들에게 구분된 축복을 하면서 아마 차남인 자신과 장남이었던 형 에서를 생각했을 것 같다.

인간이 만든 전통적인 관례보다 크신 하나님의 절대 주권이 더욱 정확하고 옳은 것을 야곱의 축복 기도를 통하여 배울 수 있는 것 같다.


9.적용(나):
하나님의 섭리를 늘 감사하며 받아들이는 자세를 더욱 가져야겠다.

