야곱의 유언

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
아들 르우벤과 시므온 레위 그리고 유다에게 유언하는 야곱.
장자인 르우벤(권능이 탁월하지만 아버지 침상을 범함)
시므온과 레위(과거 칼을 사용한 그들은 폭력의 도구, 저주로는 이스라엘 중에서 흩어짐)
