7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱이 임종을 앞두고 12 아들을 불러 그들에게 축복기도를 해준다. 야곱은 하나님으로부터 받은 영감으로 각자에게 대한 짧은 메시지와 함께 부끄러운 과거와 조심할 것들과 미래에 대하여 선포한다. 

보통 일반적인 부모라면 무조건 축복만 할 듯함에도 받은 그대로 선포하는 야곱의 모습을 볼 수 있다. 

그중에서 유다는 축복의 메시지만 받았다. 내용으로는 ‘형제의 찬송이 될지라’ 표현하였다. 마치 과거에 유다의 어머니인 레아가 유다를 출산하고 지은 이름처럼 ‘찬송’이라는 뜻을 같이 사용하였다. 

그 당시에는 레아는 남편 야곱에게 사랑을 받지 못하는 비운의 여인이었지만 내적 고난을 이겨내고 오직 하나님만을 찬양하는 여인으로 승화된다. 

그러한 축복으로 태어난 유다는 아버지로부터도 큰 축복을 받는다. 훗날 하나님은 그러한 유다의 계보를 구원의 왕 예수님이 이 땅에 오시는 축복의 통로로 사용하셨다.

9.적용(나):
하나님께 더욱 찬송을 드리는 삶을 살아야겠다.

10. 영적터치 (단어 또는 구절)
