4. 주제만들기: 연약한 자를 통해 이 땅에 오실 예수님
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 이스라엘은 자신의 자녀들에게 축복을 이어간다.
- 유다에게는 나귀를 포도나무에 매며, 포도즙으로 옷을 빨 것이고, 눈은 포도주로 인하여 붉겠고, 이는 우유로 말미암아 희리라 축복함.
- 스불론은 해변에 거주하고 경계가 시돈까지 되리라 축복함
- 잇사갈은 건장한 나귀로, 어깨를 낮춰 종이 돼 섬기게 되리라 축복함
- 단은 자기 백성을 심판할 것이라 축복함
- 갓은 적들의 공격을 받으나 오히려 적을 공격할 것이라 축복함
- 아셀은 왕의 수라상을 차리라 축복함
7. 하나님 찾기 (해석) 
- 하나님께선 최고의 사람을 택하여 자신의 뜻을 이루시기도 하지만, 연약한 자를 살피시고 보살피시는 분이며, 연약한 사람을 통해서도 그분의 뜻을 이루시는 분이다. 
- 레아는 야곱으로부터 사랑 받지 못했으나, 하나님을 누구보다 의지했고, 그 분을 찬양했다. 남편에게 사랑받지 못한 불쌍한 여인을 살피신 하나님은 그분을 의지하는 여자를 통해 예수님의 자손이 되는 영광을 주셨다. 하나님의 기준은 세상에서의 지식, 학식, 명예 등이 아니라 그분을 얼마나 사랑하는 것인가이다.
- 유다의 회심은 하나님으로부터 엄청난 축복을 얻게 되는데, 나귀 소유와 포도주로 옷을 빨 정도로 유다의 자손은 물질의 복을 얻게 된다. 더욱이 유다 자손으로부터 이스라엘의 왕이 세워지고, 암나귀와 포도주로 겉옷을 빨게 된다는 말씀을 통해 예수님이 오실 것을 예비하게 되었다. 하나님께선 깨닫고 돌이키는 자를 사용하신다.
8. 인간(해석):
- 유다는 요셉을 팔 때 함께 행동한 공범이다. 그러나 유다는 자신의 자녀를 잃고 아버지의 슬픔을 깊이 깨달았다. 유다는 깊이 깨달은 것에서 멈추지 않고 회심하였다. 자신의 동생을 위해 요셉에게 자신이 대신 감옥에 가겠다고 말하며 아버지의 깊은 슬픔을 헤아려달라고 요구하는 유다는 펑펑 울며 요셉에게 말하지 않았을까? 그런 유다의 모습을 보고 요셉은 눈물을 참을 수 없었을 것이다.
9. 적용(나):  
- 하나님은 나같은 연약한 자도 사용하심을 감사하며 주님 말씀따라 살아가야겠다.
10. 영적터치(단어/구절)
- 나귀, 포도주, 우유
11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-23', '창세기', '49장 21절~33절', '야곱의 축복과 죽음', '창세기 49장
21   납달리는 놓인 암사슴이라 아름다운 소리를 발하는도다
22   요셉은 무성한 가지 곧 샘 곁의 무성한 가지라 그 가지가 담을 넘었도다
23   활쏘는 자가 그를 학대하며 적개심을 가지고 그를 쏘았으나
24   요셉의 활은 도리어 굳세며 그의 팔은 힘이 있으니 이는 야곱의 전능자 이스라엘의 반석인 목자의 손을 힘입음이라
25   네 아버지의 하나님께로 말미암나니 그가 너를 도우실 것이요 전능자로 말미암나니 그가 네게 복을 주실 것이라 위로 하늘의 복과 아래로 깊은 샘의 복과 젖먹이는 복과 태의 복이리로다
26   네 아버지의 축복이 내 선조의 축복보다 나아서 영원한 산이 한 없음 같이 이 축복이 요셉의 머리로 돌아오며 그 형제 중 뛰어난 자의 정수리로 돌아오리로다
27   베냐민은 물어뜯는 이리라 아침에는 빼앗은 것을 먹고 저녁에는 움킨 것을 나누리로다
28   이들은 이스라엘의 열두 지파라 이와 같이 그들의 아버지가 그들에게 말하고 그들에게 축복하였으니 곧 그들 각 사람의 분량대로 축복하였더라
29   그가 그들에게 명하여 이르되 내가 내 조상들에게로 돌아가리니 나를 헷 사람 에브론의 밭에 있는 굴에 우리 선조와 함께 장사하라
30   이 굴은 가나안 땅 마므레 앞 막벨라 밭에 있는 것이라 아브라함이 헷 사람 에브론에게서 밭과 함께 사서 그의 매장지를 삼았으므로
31   아브라함과 그의 아내 사라가 거기 장사되었고 이삭과 그의 아내 리브가도 거기 장사되었으며 나도 레아를 그 곳에 장사하였노라
32   이 밭과 거기 있는 굴은 헷 사람에게서 산 것이니라
33   야곱이 아들에게 명하기를 마치고 그 발을 침상에 모으고 숨을 거두니 그의 백성에게로 돌아갔더라

