6.인간 찾기(관찰)
- 야곱이 아들들에게 축복을 다 하고,
- 아브라함과 사라, 이삭과 리브가, 그리고 레아가 장사 된, 
- 마므레 앞 막벨라 굴에 자신도 장사하라고 말함

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 야곱은 아들들의 분량대로 알맞게 축복하되,
- 요셉을 특별히 크게 축복한다.
- 적들이 요셉을 공격할지라도 요셉이 더 강할 것이라고 말하며,
- 그 근원이 전능하신 하나님께 있음을 강조하여 말한다.
- 전능하신 하나님을 경험한 야곱은
- 자신이 받은 복에 대해 평가하기를 영원한 산들이 받은 복보다 풍성하다고 말하며,
- 이제는 그 복이 요셉에게 임할 것이라고 말하며 요셉을 축복한다.
- 아들들을 축복한 후에,
- 야곱은 자신은 가나안 헤브론 땅에 장사해 달라고 말한다.
- 그곳은 아브라함과 사라, 이삭과 리브가, 그리고 레아가 장사된 곳이다.
- 야곱은 라헬을 평생 사랑하며 살았는데, 라헬은 베들레헴 가는 길에 장사되고,
- 헤브론에 장사 된 사람은 레아이다.

9.적용(나) 
- 야곱이 말하기를 전능하신 하나님께 받은 복이, 
- 영원한 산들이 받은 복보다 많다고 표현했다.
- 영원한 산들을 창조하신 전능하신 하나님께서는 야곱도 돌보시고, 
- 이스라엘과 세상을 돌보시고,
- 예수님을 통해 나와 모든 믿는 자들을 돌보신다.
- 오늘도 나를 돌보시는 하나님을 바라보며,
- 영원한 산들이 받은 복보다 풍성한 복을 내게 주신, 
- 하나님의 복을 헤아려보는 삶을 살아야겠다.

