4.주제만들기: 
이스라엘의 장례를 치루는 요셉

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
아버지 이스라엘 죽음에 슬퍼하며 우는 요셉.
그의 장례를 준비하는 요셉.
애굽 사람들은 칠십일 동안 곡함.
야곱의 시신을 가나안 땅으로 가는 것을 허락하며 많은 병거와 기병까지 지원해 주는 바로왕.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
야곱이 147세 나이로 본향으로 돌아갔다. 야곱은 가나안 땅에서 요셉이 있는 애굽으로 대 이동할 당시 나이가 130세라고 기록된 것으로 보아 17년을 애굽 땅에 산 셈이다.

요셉이 강제로 애굽으로 팔릴 때 나이가 17살이라고 하는 것을 생각할 때 17년은 우연보다는 하나님의 의도성을 느끼게 된다. 마치 오래 헤어진 요셉을 그리워하는 마음을 노년에 충분히 아들 요셉과 정을 나누고자 하는 하나님의 사랑과 배려가 아니었나 생각이 된다. 

한편 야곱 장례를 치를 때 야곱 가족뿐만 아니라 애굽 사람들이 70일 동안 곡을 하였다고 하는 것을 보니 평상시 요셉이 얼마나 애굽 백성들에게 존경받고 있는지 가늠케 된다. 사실 애굽 사람 대부분은 목축업을 하는 사람들을 무시하는 사회적 시선이 있었으나 야곱 가족만큼은 예외였던 것 같다.

백성들뿐만 아니라 애굽의 왕에게도 신임받고 있음을 알 수 있다. 바로 왕은 야곱의 바람대로 그의 유골을 가나안 땅에 묻히도록 허락하고 그곳으로 갈 때 많은 병거와 기병으로 호위하게 함께 보내주었다.

요셉은 아랫사람 뿐만 아니라 윗사람에게 또한 충성스러운 사람임을 알 수 있다.

9.적용(나):
모든 사람들과  더불어 좋은 관계를 가지도록 힘써야겠다.

10. 영적터치 (단어 또는 구절)
3절: 애굽 사람들은 칠십 일 동안 그를 위하여 곡하였더라

