4.주제 만들기: 합력하게 하여 구원을 이루시는 하나님

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 요셉과 함께 한 모든 사람의 애통을 보고 
- 그 땅 이름을 아벨미스라임(애굽인의 애곡)이라 함
- 야곱의 아들들이 아버지의 유언대로 마므레 앞 막벨라 굴에 아버지를 장사함
- 요셉 일행이 애굽으로 돌아옴
- 요셉의 형들이 요셉이 자기들이 행한 모든 악을 다 갚을까 두려워하며
- 요셉에게 ‘형들을 허물과 죄를 용서하라.’는 아버지의 말을 전하게 함
- 이 말을 들은 요셉이 움.
- 형들이 요셉 앞에 엎드려 우리는 당신의 종입니다 라고 말하자
- 요셉이 두려워 말라고 말하며 내가 하나님을 대신하리이까
- 형들은 나를 해하려 하였으나 
- 하나님은 그것을 선으로 바꾸사, 많은 백성의 생명을 구원하게 하셨다고 말함

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 야곱의 장례를 마치자 형들은 요셉이 과거의 일로 
- 복수할 것이라 생각하며 두려워 하였으나,
- 요셉은 내가 하나님을 대신하겠느냐 말하며, 
- 모든 것을 하나님께서 이루셨음 선포한다.
  일을 이루시고 성취하시는 분도 하나님이시고, 사람을 벌하시는 분도 하나님이시다
- 요셉은 형들의 악한 행위를 하나님께서 선으로 바꾸시고 
- 많은 사람을 구원하셨다고 말한다.
- 요셉이 하나님의 구원 계획을 깨닫게 된 시기가 바로의 꿈을 해석할 때인지,
- 흉년 때인지, 풍년 어느 때인지 알 수 없으나,
- 요셉은 하나님의 일을 하며,
- 하나님의 신묘막측한 구원 계획을 깨닫고 그 성취를 누리는 삶을 살았을 것이다.
- 사람의 생각과 하나님의 생각은 크게 다르다.

9.적용(나) 
- 하나님께서는 악한 일까지도 합력하게 하여 선을 이루신다.
- 악한 일까지 계획하신 것인지, 
- 악한 일까지 사용하신 것인지 나는 정확히 모른다.
- 다만, 하나님은 모든 것을 합력하게 하시고, 
- 결국 선을 이루시는 분이라는 것을 믿는다.
- 하나님의 구원 사역 안에서 살아가는 것에 감사하며,
- 그것을 누리며,
- 오늘도 내가 해야 할 일을 묵묵히 해야겠다.

10.영적 터치(단어/구절)
  20   당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 많은 백성의 생명을 구원하게 하시려 하셨나니

11.믿음과 회개 및 감사기도로 마무리
