4. 주제만들기: 요셉의 죽음
5. 하나님 찾기 (관찰)
- 이스라엘 자손을 돌보심
- 하나님의 때에 애굽 땅에서 인도하사 아브라함, 이삭, 야곱에게 맹세하신 땅으로 이끄심
6. 인간 찾기 (관찰)
- 요셉은 불안해하는 형들을 간곡한 말로 위로함. 그리고 형들과 형들의 자손을 기르겠다 함
- 요셉은 백십세를 살며 에브라임의 자손을 3대까지 보고, 므낫세의 아들들도 양육함
- 요셉은 죽음이 임박하자 형들에게 하나님이 당신들을 돌보시고 이 땅에서 인도하여 아브라함, 이삭, 야곱에게 맹세하신 땅으로 이끄실 것이라 말함
- 요셉은 이스라엘 자손에게 맹세시켜 자신의 해골을 메고 올라가라 말함
- 요셉이 죽음
7. 하나님 찾기 (해석) 
- 이스라엘 자손 입장에서 애굽에서의 삶은 하나님과 요셉으로 인해 풍족했을 것이다. 그러나 언약의 하나님은 하나님의 때에 자신의 언약을 성취하고자 이스라엘 자손을 가나안 땅으로 이끄실 것을 요셉이 언급했는데, 애굽에서의 풍족한 삶을 최대한 누리게 하신 후에 이스라엘 자손이 어려움을 겪을 때 하나님의 일을 성취하신다. 하나님께선 우리가 풍족한 삶을 누리는 것도 매우 기뻐하시는 분이시다.
8. 인간(해석):
- 요셉은 걱정하는 형들을 염려시켰는데, 간곡한 말로 그들을 위로했다 표현할 정도로 형들을 안심시켰다. 자신이 이룬 것은 자신의 성취가 아닌 하나님께서 계획하신 일임을 믿는 요셉에겐, 과거의 아픔은 하나님의 구원 계획이었기에 더 이상 상처가 되지 않는다. 
- 요셉은 자신의 자녀, 에브라임의 자손을 삼대까지 보았는데, 얼마나 큰 기쁨이었을까? 30살 이후의 요셉은 백십세까지 축복과 기쁨을 충분히 누리고 죽음을 맞이했다. 괴롭고 힘든 일들이 많았던 요셉이 그 과정을 이겨내자 하나님께서 축복을 더하여 주셨다.
9. 적용(나): 
- 때론 이해하기 힘든 어려운 일이 발생하더라도, 하나님을 의지해야하는 것은 그것이 회복되지 않더라도 하나님께서 주시는 은혜가 있기 때문이다. 불평불만, 원망보다 하나님을 의지하는 믿음이 내 안에 가득하길 소망한다.
10. 영적터치(단어/구절)
- 그들을 간곡한 말로 위로하였더라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

