4.주제만들기: 
강한 이스라엘 백성을 두려워하는 애굽의 새 왕

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
수백년이 지나고 애굽의 새 왕은 요셉을 알지 못한다.
번성하고 강한 애굽내 있는 이스라엘 백성을 두려워하는 애굽의 새 왕.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
요셉이 본향으로 떠난 지 수백 년이 지났을 때 요셉을 알지 못하는 애굽에 새 왕이 세어졌다. 그 새 왕은 이스라엘 자손들이 크게 번성하고 강한 것에 대하여 두려워하였다.

요셉이 애굽땅에 생존하였을 때만 하여도 이스라엘 백성들은 애굽 백성들과 왕에게도 관계성에서 전혀 경계심을 주지 않았었다.

덕분에 이스라엘 자손들도 함께 그 땅에서 안정되게 정착할 수 있었다. 더군다나 그 당시 큰 기근이 있었을 때 그것을 대비하도록 알려준 하나님의 존재도 바로 왕은 인정했었다. 

그러나 오랜 세월이 지나고 당시 구원하신 하나님에 관한 이야기 또는 영웅이었던 국무총리 요셉조차도 기억 못 하는 상황이 되었다. 

이를 통하여 느끼는 것은 복음 안에서 제자 삼는다는 것과 어린 자녀들에게 올바른 기독교적 역사 또는 교육이나 학습 전달이 얼마나 중요한지 다시 깨우치게 되었다.

9.적용(나):
자녀들에게 또는 새터민들에게 살아계신 주님에 대하여 더욱 적극적으로 학습 지도 해야겠다.

10. 영적터치 (단어 또는 구절)
8절: 요셉을 알지 못하는 새 왕이 일어나 애굽을 다스리더니

