4.주제만들기: 
학대를 받는 이스라엘 자손들

5.하나님 찾기 (관찰)
하나님을 경외하는 산파들의 집안을 흥왕하게 하시는 하나님.

6.인간 찾기(관찰)
이스라엘 자손들에게 심한 노역을 주어 학대하는 애굽왕.
그럼에도 더욱 번성하는 이스라엘 자손들.
산파들에게 출산중 이스라엘 남자 아이들을 죽이라고 지시하는 애굽왕.
하나님을 더욱 두려워하여 애굽왐의 악한 지시를 따르지 않는 산파들.
하나님은 그러한 산파들 가정에 복을 주시사 흥왕케 하셨다.

7.하나님 찾기(해석)
보이지는 않지만, 만물의 통치자이신 하나님은 자신을 경외하고 세상의 악하고 강한 권세를 따르지 않은 산파들에게 복을 주셨다. 

사실 이 부분은 이성적으로 알고는 있지만 현재 사는 세상에서는 결코 쉬운 일은 아닐 것이다. 

그런데도 믿음을 가지고 주님의 길을 붙잡는다면 주님은 반드시 좋은 길로 인도하실 것을 믿는다.

8.인간 찾기 (해석)
산파들은 애굽왐을 속이고 그 악행을 이행하지 않았다. 그들이 지혜롭게 대처하고 따르지 않은 것은 명확하다. 

세상 왕의 권세보다 참 왕이신 하나님이 진짜 권세자 인 것을 믿고 있었다. 즉 하나님을 경외하는 백성들이었다. 덕분에 하나님으로부터 가정에 복도 받았다. 

자칫 잘못하면 히브리 남자 출생 아들을 죽이지 않으면 자신들의 생명이 위태로울 수 있었는데 대단한 믿음인 것 같다. 

 하나님의 진리의 길을 선택하고 따른다는 것은 때때로 목숨을 걸어야 하는 것 같다.

9.적용(나):
하나님을 더욱 경외하는 사람이 되야겠다.

10. 영적터치 (단어 또는 구절)
21절: 하나님을 경외하였으므로 

11. 믿음과 회개 및 감사기도로 마무리
