4. 주제만들기: 누이의 지혜
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 레위 가족이 임신을 하여 아들을 낳고, 세달을 숨겼으나 더 이상 숨길 수 없게 되자, 아이를 갈대 상자에 넣어 나일 강으로 흘려 보냄
- 누이가 어떻게 되는지 멀리 서서 봤더니, 바로의 딸이 목욕하러 나일 강으로 나와 갈대 상자를 발견한 것을 보고 바로의 딸에게 찾아가 히브리 여인을 찾아 젖을 먹이게 할 것을 물어봄
- 누이는 어머니를 불렀고, 바로의 딸은 삯을 주어 젖을 먹이게 함.
- 아기가 자라 바로의 딸이 데려갔고, 아기의 이름을 모세라 함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 레위 가족은 아들이 태어나서 얼마나 안타까웠을까? 소중한 생명이 죽임 당하는 것을 눈으로 보지 못했을 것이다. 얼마나 잔인한 일인가? 태어나자마자 아들이라는 이유로 아이를 죽이다니... 세달이나 숨겨서 아이를 지키고 싶었던 레위 가족의 마음을 충분히 이해한다. 
- 아이가 커지며 더 이상 숨길 수 없는 상황에 놓이자 아이를 보내줄 수 밖에 없다. 갈대 상자에 역청과 나무 진을 칠해 최대한 물이 스며들지 않도록 했다. 그것은 애굽 사람 누군가 아이를 발견해 살려주길 바라는 마음이었을 것이다. 
- 누이는 간절한 마음으로 지켜봤을 것이다. 그 때 바로의 딸, 애굽의 공주가 아이를 발견하게 됐고, 보자마자 히브리 사람의 아이라는 것을 알게 되었다. 그 순간 애굽의 공주는 긍휼한 마음이 들었다. 누이는 그 틈을 타고 들어 히브리 여인을 데려오겠다고 말한다. 공주가 누이의 행동으로 아기의 엄마라고 눈치 못 챘을까? 당연히 알았을 것이다. 거기에 더불어 엄마가 아기에 젖을 먹일 수 있게 해주고, 삯까지 주어 엄마의 역할을 다함과 동시에 생계까지 책임져 주었다.
- 레위 가족이 아이를 죽이지 않고 나일강에 보내기로 결심한 것, 누이가 지켜본 것, 때마침 목욕하러 나일강에 나온 공주, 이 모든 일은 우연이 아니다. 하나님께서 그분의 뜻을 위해 지키시고 보호하신 것이다. 
- 어제 항공기 사고로 가족을 잃은 유가족들, 얼마나 가슴이 아프고, 믿기지 않을까? 한순간 가족을 잃은 그들에게 하나님의 특별한 위로가 주어지길 소망한다.
9. 적용(나): 
- 나일강에 아이를 보내 간절한 구원을 바랬던 레위 가족처럼, 절체절명의 순간에 하나님만 의지하고 그분을 의지하는 믿음이 내게 주어지길 소망한다.
- 항공기 사고로 고통 가운데 있는 유가족을 위해 기도해야겠다.
10. 영적터치(단어/구절):
- 6 열고 그 아기를 보니 아기가 우는지라 그가 그를 불쌍히 여겨 이르되 이는 히브리 사람의 아기로다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-12-31', '출애굽기', '2장 11절~20절', '모세가 바로를 떠나 미디안으로 가다', '출애굽기 2장
11   모세가 장성한 후에 한번은 자기 형제들에게 나가서 그들이 고되게 노동하는 것을 보더니 어떤 애굽 사람이 한 히브리 사람 곧 자기 형제를 치는 것을 본지라
12   좌우를 살펴 사람이 없음을 보고 그 애굽 사람을 쳐죽여 모래 속에 감추니라
13   이튿날 다시 나가니 두 히브리 사람이 서로 싸우는지라 그 잘못한 사람에게 이르되 네가 어찌하여 동포를 치느냐 하매
14   그가 이르되 누가 너를 우리를 다스리는 자와 재판관으로 삼았느냐 네가 애굽 사람을 죽인 것처럼 나도 죽이려느냐 모세가 두려워하여 이르되 일이 탄로되었도다
15   바로가 이 일을 듣고 모세를 죽이고자 하여 찾는지라 모세가 바로의 낯을 피하여 미디안 땅에 머물며 하루는 우물 곁에 앉았더라
16   미디안 제사장에게 일곱 딸이 있었더니 그들이 와서 물을 길어 구유에 채우고 그들의 아버지의 양 떼에게 먹이려 하는데
17   목자들이 와서 그들을 쫓는지라 모세가 일어나 그들을 도와 그 양 떼에게 먹이니라
18   그들이 그들의 아버지 르우엘에게 이를 때에 아버지가 이르되 너희가 오늘은 어찌하여 이같이 속히 돌아오느냐
19   그들이 이르되 한 애굽 사람이 우리를 목자들의 손에서 건져내고 우리를 위하여 물을 길어 양 떼에게 먹였나이다
20   아버지가 딸들에게 이르되 그 사람이 어디에 있느냐 너희가 어찌하여 그 사람을 버려두고 왔느냐 그를 청하여 음식을 대접하라 하였더라

