4.주제 만들기: 모세가 바로를 떠나 미디안으로 가다

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 장성한 모세가 애굽 사람이 히브리 사람을 치는 것은 봄
- 주위에 사람이 없음을 보고 그 애굽 사람을 쳐죽이고 모래 속에 감춤
- 이틑 날 히브리 사람 둘이 싸우는 것을 봄
- 어째서 동포를 치느냐 물음
- 그가 말하기를 누가 너를 우리를 다스리는 자 삼았느냐,
- 애굽 사람을 죽인 것처럼 나도 죽일 것이냐 물음
- 모세가 일이 탄로난 것을 알고 두려워 함
- 바로가 이 일을 알게 되어 모세를 죽이고자 함
- 모세가 바로의 낯을 피하여 미디안 땅으로 감
- 모세가 우물 곁에 앉아 있다가
- 물을 길으러 온 미디안 제사장의 일곱 딸들을 돕게 됨
- 이 일을 들은 미디안 제사장이 모세를 불러와 음식을 대접하라고 말함

7.하나님 찾기 (해석) 

8.인간(해석)
- 장성한 모세가 동족이 고된 노동을 하고 있는 것음 봄
- 마음이 많이 아팠을 것이고, 여러 가지 생각을 하게 되었을 것
- 그런데 애굽 사람이 동족 한 사람을 치는 것을 보게 됨
- 아마도 고된 노동에 지쳐 노동을 이어가지 못하는, 쓰러져 있는, 
- 약한 사람을 때리는 애굽 사람을 보았을 것임
- 긍휼함과 분노가 치밀어 오른 모세가 애굽 사람을 쳐 죽임
- 이 행동은 모세 입장에서는 의로운 행동이었으나,
- 애굽인들에게는 반역 행위였을 것.
- 다음 날 다시 나갔는데, 이번에는 동족끼리 싸우는 모습을 봄
- 잘못한 사람에게 왜 동포를 치느냐 말함
- 왜 서로 위해주지 못할지언정, 싸우기까지 하느냐 하는 울부짖음이었을 것
- 그 잘못한 사람이 어제 애굽인을 죽인 것처럼 오늘은 나도 죽이려느냐 말함
- 모세는 일이 탄로 난 것을 알게 됨
- 바로가 이 일을 듣고 모세를 죽이려고 찾음
- 모세는 바로를 피하여 미디안 땅에 머무름
- 우물 곁에 있을 때 미디안 제사장 일곱 딸이 물을 길으러 옴
- 목동들이 와서 일곱 딸을 쫓아냄
- 이를 본 모세가 일곱 딸을 도와 물을 기르는 것을 도와주고 양 떼에게도 먹임
- 모세는 긍휼히 여기는 마음이 있고, 
- 정의로움으로 가득 찼으며, 
- 무예가 출중한 것을 알 수 있음.
- 일곱 딸이 아버지에게 이르자 오늘은 어떻게 일찍 오느냐 물음
- 이것으로 볼 때 목동들에게 쫓겨난 일이 한두 번이 아니라 빈번하게 있던 일임을 알 수 있음
- 딸들이 모세에 대해 말하자 아버지가 청하여 음식을 대접하라 말함

9.적용(나)
- 내게는 긍휼히 여기는 마음과 정의로움이 얼마나 있는가, 어찌보면 이런 마음보다 자기 연민이 더 많다. 
- 회개하고 남을 긍휼히 여기는 마음과 정의로움이 가득하길 기도해야겠다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-01', '출애굽기', '2장 21절~25절', ' ', '(출애굽기2장)
21. 모세가 그와 동거하기를 기뻐하매 그가 그의 딸 십보라를 모세에게 주었더니
22. 그가 아들을 낳으매 모세가 그의 이름을 게르솜이라 하여 이르되 내가 타국에서 나그네가 되었음이라 하였더라
23. 여러 해 후에 애굽 왕은 죽었고 이스라엘 자손은 고된 노동으로 말미암아 탄식하며 부르짖으니 그 고된 노동으로 말미암아 부르짖는 소리가 하나님께 상달된지라
24. 하나님이 그들의 고통 소리를 들으시고 하나님이 아브라함과 이삭과 야곱에게 세운 그의 언약을 기억하사
25. 하나님이 이스라엘 자손을 돌보셨고 하나님이 그들을 기억하셨더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2025년 1월1일 출애굽기 2장21절~25절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
모세: 21절(2) 22절 
고된 노동: 23절(2) 
기억하사/기억하셨더라: 24절 25절
이스라엘 자손: 23절 25절
하나님: 23절 24절 25절
상달된지라/소리를 들으시고: 23절 24절

4.주제만들기: 
이스라엘 자손의 탄식을 들으시는 하나님

5.하나님 찾기 (관찰)
이스라엘 자손의 고통 소리를 들으시는 하나님.
언약을 기억하시는 하나님.
돌보시는 하나님.

6.인간 찾기(관찰)
미디안 제사장 르우엘이 딸 십보라를 모세에게 아내로 허락함.
결혼 후 아들을 얻은 모세.
아들의 이름은 게르솜 이고 뜻은 ''타국에서 나그네가 됨''
고된 노동으로 하나님께  울부짖는 이스라엘 자손.

7.하나님 찾기(해석)
하나님은 언약을 중요하게 여기시는 것이 분명하다. 오래전 아브라함과 이삭 그리고 야곱에게 주신 언약 즉 자손들에게 복을 주시겠다는 것을 분명히 기억하고 계셨다. 

애굽 왕의 횡포로 인하여 힘든 노역의 고통 소리를 들어주시고 언약을 기억하사 돌보아 주셨다. 

여기서 중요한 것은 하나님이 언약을 기억하고 계신다는 사실이다. 믿음의 조상 아브라함은 비록 없지만 언약을 선포하시는 하나님은 끝까지 자손들의 기도를 들어주신다. 

현대에 사는 하나님의 자녀들에게도 같게 적용되는 사실이다.

8.인간 찾기 (해석)
고통 속에서도 포기하지 않고 하나님을 찾고 부르짖는다면 반드시 하나님 은총의 응답 역사가 일어남을 보여준다.

9.적용(나):
어떠한 상황에도 더욱 언약의 말씀을 붙잡고 하나님께 부르짖는 종이 되야겠다.

10. 영적터치 (단어 또는 구절)
24절: 그의 언약을 기억하사

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-02', '출애굽기', '3장 1절~10절', '모세, 하나님 앞에 서다', '출애굽기 3장
1   모세가 그의 장인 미디안 제사장 이드로의 양 떼를 치더니 그 떼를 광야 서쪽으로 인도하여 하나님의 산 호렙에 이르매
2   여호와의 사자가 떨기나무 가운데로부터 나오는 불꽃 안에서 그에게 나타나시니라 그가 보니 떨기나무에 불이 붙었으나 그 떨기나무가 사라지지 아니하는지라
3   이에 모세가 이르되 내가 돌이켜 가서 이 큰 광경을 보리라 떨기나무가 어찌하여 타지 아니하는고 하니 그 때에
4   여호와께서 그가 보려고 돌이켜 오는 것을 보신지라 하나님이 떨기나무 가운데서 그를 불러 이르시되 모세야 모세야 하시매 그가 이르되 내가 여기 있나이다
5   하나님이 이르시되 이리로 가까이 오지 말라 네가 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라
6   또 이르시되 나는 네 조상의 하나님이니 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이니라 모세가 하나님 뵈옵기를 두려워하여 얼굴을 가리매
7   여호와께서 이르시되 내가 애굽에 있는 내 백성의 고통을 분명히 보고 그들이 그들의 감독자로 말미암아 부르짖음을 듣고 그 근심을 알고
8   내가 내려가서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 데려가려 하노라
9   이제 가라 이스라엘 자손의 부르짖음이 내게 달하고 애굽 사람이 그들을 괴롭히는 학대도 내가 보았으니
10   이제 내가 너를 바로에게 보내어 너에게 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라

3:하나님, 인간, 나
