2025년 1월 2일 출애굽기 3장 1~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
모세: 1, 3, 4(2), 6
떼: 1(2)
하나님(여호와): 1, 2, 4(2), 5, 6(5), 7
떨기나무: 2(3), 3, 4
애굽: 7, 9, 10
내 백성: 7, 10
땅: 8(3)
이스라엘 자손: 9, 10

4.주제 만들기: 모세, 하나님 앞에 서다

5.하나님 찾기 (관찰)
- 떨기나무 가운데 불꽃으로 나타나신 하나님
- 모세를 부르시는 하나님
- 모세에게 가까이 오지 말라, 신을 벗으라 말씀하시는 하나님
- 나는 하나님이라고 말씀하시는 하나님
- 애굽에서 이스라엘의 고통을 보았고, 감독자들에게 받는 핍박을 알고 있다고 말씀하시는 하나님
- 이스라엘을 애굽으로부터 건져내시고,
- 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅으로 인도하시겠다고 말씀하시는 하나님
- 모세에게 바로에게 가라 말씀하시고,
- 너를 통해 이스라엘 백성을 애굽에서 인도하여 내겠다 말씀하시는 하나님 

6.인간 찾기 (관찰)
- 모세가 호렙산 위 떨기나무에 불이 붙은 것을 봄
- 자세히 보니 불이 붙었는데 떨기나무는 타지 않는 것을 발견함
- 어째서 불이 붙었는데 떨기나무가 타지 않는지 궁금하여,
- 떨기나무에 접근하는 모세
- 음성을 듣고 떨기나무에 가까이 가는 것을 멈추고,
- 신을 벗는 모세
- 떨리나무에서 나는 음성이 하나님이란 말씀을 듣고
- 두려워 얼굴을 두 손으로 가리는 모세
- 하나님의 말씀을 듣는 모세
 
7.하나님 찾기 (해석) 
- 때가 되어 이스라엘을 구원하시고자 하시되,
- 모세를 사용하여 구원하시려고 모세 앞에 나타나심
- 모세에게 내가 하나님이며 이스라엘의 고통을 보았고 
- 애굽 감독자의 핍박을 알고 있다고 말씀하심
- 이 말씀은 모세에게 큰 위로와 힘이 되었을 것임.

8.인간(해석)
- 모세는 긴 세월 양을 치면서,
- 동족들의 고통을 생각하며 깊은 괴로움 속에서 살았을 것이며,
- 애굽의 압제로부터 동족을 구할 수 없고 돌아갈 수도 없는 
- 도망자라는 현실 속에 좌절하고 있었을 것이다.
- 그러던 어느날 불타는 떨기나무를 발견하였고,
- 그 불꽃을 보는 순간 예사롭지 않은 불꽃임을 느꼈을 것이다.
- 불에 타지 않는 떨기나무를 보며, 신비함을 느끼며 다가가는데,
- 갑자기 음성이 들려 깜짝 놀란 모세.
- 그 음성이 말하기를 멈추라, 신을 벗으라 하는데,
- 아마도 납작 엎드려 절하는 자세로 대답했을 것이다.
- 그런데 그 음성이 말하길 자신이 하나님이라 하시니, 
- 두려워 얼굴을 두 손으로 가렸다.
- 거룩하신 하나님이 앞에 나타나셨는데, 자신이 죽지 않는 것과 하나님의 말씀을 듣는 것이 
- 두려움 속에서도 너무나 신기하고 기뻤을 것이다. 
- 그 하나님이 말씀하시길 이스라엘의 고통과 감독자의 핍박을 알고 있다고 말씀하시니,
- 모세는 자신의 마음속 고통과 괴로움이 한 번에 해결되는 기쁨을 누렸을 것이다.
- 와! 하나님이 다 알고 계셨고, 건져내시겠구나!
- 이스라엘 백성을 애굽 땅에서 인도하여 아름답고 광대한 땅, 
- 젖과 꿀이 흐르는 땅으로 인도하신다니,
- 너무나 황홀하고 기쁨이 넘쳤을 것이다.

- 모세의 이름의 뜻이 ‘건져내다’ 이고,
- 하나님은 모세를 이용하여 이스라엘을 애굽의 압제로부터 건져내시려고 한다.
- 모세 입장에서 보면, 
- 모세야 너의 고통과 괴로움, 그거 내가 알고 있어. 
- 네가 할 수 없는 그 일, 내가 해결해 줄 게 말씀하시는 것이다.
  
9.적용(나)
- 하나님은 우리의 모든 상황을 알고 계신다.
- 나의 상황과 현실과 마음의 모든 생각을 알고 계신다.
- 그리고 하나님의 때에 하나님은 우리를 통해, 나를 통해 그 일을 성취하실 것이다.
- 약속의 말씀을 이루시는 하나님을 의지하고, 
- 오늘도 묵묵히 내가 가야 할 길을 걸어가야겠다.

10. 영적터치(단어/구절)  
  7   여호와께서 이르시되 내가 애굽에 있는 내 백성의 고통을 분명히 보고 그들이 그들의 감독자로 말미암아 부르짖음을 듣고 그 근심을 알고

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-03', '출애굽기', '3장 11절~22절', ' ', '(출애굽기4장)
1.  모세가 대답하여 이르되 그러나 그들이 나를 믿지 아니하며 내 말을 듣지 아니하고 이르기를 여호와께서 네게 나타나지 아니하셨다 하리이다
2. 여호와께서 그에게 이르시되 네 손에 있는 것이 무엇이냐 그가 이르되 지팡이니이다
3. 여호와께서 이르시되 그것을 땅에 던지라 하시매 곧 땅에 던지니 그것이 뱀이 된지라 모세가 뱀 앞에서 피하매
4. 여호와께서 모세에게 이르시되 네 손을 내밀어 그 꼬리를 잡으라 그가 손을 내밀어 그것을 잡으니 그의 손에서 지팡이가 된지라
5. 이는 그들에게 그들의 조상의 하나님 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님 여호와가 네게 나타난 줄을 믿게 하려 함이라 하시고
6. 여호와께서 또 그에게 이르시되 네 손을 품에 넣으라 하시매 그가 손을 품에 넣었다가 내어보니 그의 손에 나병이 생겨 눈 같이 된지라
7. 이르시되 네 손을 다시 품에 넣으라 하시매 그가 다시 손을 품에 넣었다가 내어보니 그의 손이 본래의 살로 되돌아왔더라
8. 여호와께서 이르시되 만일 그들이 너를 믿지 아니하며 그 처음 표적의 표징을 받지 아니하여도 나중 표적의 표징은 믿으리라
9. 그들이 이 두 이적을 믿지 아니하며 네 말을 듣지 아니하거든 너는 나일 강 물을 조금 떠다가 땅에 부으라 네가 떠온 나일 강 물이 땅에서 피가 되리라
10. 모세가 여호와께 아뢰되 오 주여 나는 본래 말을 잘 하지 못하는 자니이다 주께서 주의 종에게 명령하신 후에도 역시 그러하니 나는 입이 뻣뻣하고 혀가 둔한 자니이다

