5.하나님 찾기 (관찰)
모세에게 말씀하시는 여호와.
모세에게 능력을 보이시는 여호와(지팡이 가 뱀으로 변신후 다시 지팡이로 돌아옴, 손이 나병 걸린후 다시 정상으로 돌아옴)

6.인간 찾기(관찰)
두려워하는 모세.
그럼에도 순종하여 뱀의 꼬리를 잡은 모세.

7.하나님 찾기(해석)
모세 하면 상징적으로 떠오르는 것은 그가 소지한 ''지팡이'' 일 것이다. 하나님은 모세에게 그의 지팡이에 능력을 불어넣어 주셨다. 

이스라엘 백성을 출애굽의 대 사명을 받은 모세는 몹시 두려워하였다. 그러한 모세를 사용하시려고 하나님은 먼저 모세가 무엇이 필요한지 이미 알고 계셨다. 모세를 믿게 하려고 순간 지팡이가 뱀이 되게 한 후 바로 뱀이 지팡이로 다시 되는 표적을 보이셨다. 그럴 뿐만 아니라 내적으로는 모세를 순종케 함으로 인간의 기본적 지식이나 상식을 넘어서는 믿음을 주려 하셨다. 

방법으로는 하나님은 의도적으로 뱀의 꼬리를 잡도록 명령하셨다. 뱀을 잡을 때는 안전을 위하여 통상 머리 부분을 잡아야 하는 것은 모든 인간이 가진 상식일 것이다. 

특별히 오랜 40년의 목동 생활하는 동안 얼마나 많은 뱀을 다루어볼 듯한 모세에게는 쉽게 받아들이지 못했을 것이다. 하지만 모세는 고정관념을 벗어나 즉각 순종했다. 

그때 뱀이 변하여 그의 몸을 지탱시킬 지팡이로 변하였다. 하나님은 짧은 시간에 모세에게 믿음과 순종에 대하여 훈련하고 계심을 알 수 있다. 계속해서 그의 손을 나병환자 손으로 만드셨다.

 본래 손으로 변하는 표적도 행하셨다. 이러한 표적들을 통하여 깨우칠 수 있는 것은 진정한 능력은 오직 하나님께로 나옴을 알 수 있다. 결코 모세의 지팡이는 그냥 나무임을 알 수 있다. 

당장 순종하기 이해하기 어려운 환경일지 어도 하나님을 믿고 순종한다면 하나님은 반드시 누구에게나 현실의 장벽을 넘어 최고의 길을 자녀들에게 열어 주실 것이다.

8.인간 찾기 (해석)

