4.주제만들기: 
하나님의 명을  받고 애굽으로 돌아가는 모세

5.하나님 찾기 (관찰)
망설이는  모세에게 노하시는 여호와.
담대할 수 있는 여러가지 근거(형 아론이 도와줌, 모세 입에 하나님이 함께하심)를
말씀 하시는 여호와.

6.인간 찾기(관찰)
두려워하는 모세.
결국 순종하고 애굽으로 떠나는 모세.
장인 이드로와 작별 인사를 나눔.

7.하나님 찾기(해석)
하나님의 표적을 체험했음에도 여전히 모세는 떠나기를 망설인다. 
이유는 스스로 나이가 80의 노년이라는 점과 특히 말주변까지 없다는 것이었다. 하지만 하나님은 그러한 나약한 모세에 대하여 노하셨다. 

그리고 담대함을 가질 수 있는 근거를 제시하신다. 첫째는 하나님이 모세와 함께하신다는 것이다. 둘째는 육의 형제인 같은 레아 지파 형 아론을 동행토록 하시는데 그는 모세와 달리 말을 잘한다고 하셨다. 

이럴 때 모세는 용기를 내어 힘을 내어 장인 이드로와 작별 인사를 하고 떠난다. 떠날 때 자녀들과 아내와 함께 떠난다. 

그때 성경은 말한다. 모세의 지팡이가 아니라 ''하나님의 지팡이''라고 표현한다. 애굽 왕보다 크시고 강하신 하나님이 함께하신다면 노년의 나이나 언변의 기술이나 문제가 되지 않음을 깨우친다. 

2010년 나도 주님의 음성 듣고 2살 그리고 5살 딸과 아내와 함께 사명 자로 미국에서 떠났던 경험이 있다. 돌이켜보면 모든 것이 하나님의 돌보심과 함께하심으로 탈북민 선교를 감당할 수 있었고 또 계속 잘 감당하고 있다. 하나님이 함께하심이 너무 기쁘다.

8.인간 찾기 (해석)

9.적용(나):
하나님이 내 삶의 동반자요 주인이신것에 늘 감사하며 살아야겠다.

10. 영적터치 (단어 또는 구절)
20절: 모세가 하나님의 지팡이를 손에 잡았더라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-06', '출애굽기', '4장 21절~31절', '하나님의 심판과 구원의 원리', '[출4:21-31]
21 여호와께서 모세에게 이르시되 네가 애굽으로 돌아가거든 내가 네 손에 준 이적을 바로 앞에서 다 행하라 그러나 내가 그의 마음을 완악하게 한즉 그가 백성을 보내 주지 아니하리니
22 너는 바로에게 이르기를 여호와의 말씀에 이스라엘은 내 아들 내 장자라
23 내가 네게 이르기를 내 아들을 보내 주어 나를 섬기게 하라 하여도 네가 보내 주기를 거절하니 내가 네 아들 네 장자를 죽이리라 하셨다 하라 하시니라
24 모세가 길을 가다가 숙소에 있을 때에 여호와께서 그를 만나사 그를 죽이려 하신지라
25 십보라가 돌칼을 가져다가 그의 아들의 포피를 베어 그의 발에 갖다 대며 이르되 당신은 참으로 내게 피 남편이로다 하니
26 여호와께서 그를 놓아 주시니라 그 때에 십보라가 피 남편이라 함은 할례 때문이었더라
27 여호와께서 아론에게 이르시되 광야에 가서 모세를 맞으라 하시매 그가 가서 하나님의 산에서 모세를 만나 그에게 입맞추니
28 모세가 여호와께서 자기에게 분부하여 보내신 모든 말씀과 여호와께서 자기에게 명령하신 모든 이적을 아론에게 알리니라
29 모세와 아론이 가서 이스라엘 자손의 모든 장로를 모으고
30 아론이 여호와께서 모세에게 이르신 모든 말씀을 전하고 그 백성 앞에서 이적을 행하니
31 백성이 믿으며 여호와께서 이스라엘 자손을 찾으시고 그들의 고난을 살피셨다 함을 듣고 머리 숙여 경배하였더라
3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
