- 아론(27,28,29,30절)
- 십보라(25,26절)
- 피남편(25,26절)
4. 주제만들기: 하나님의 심판과 구원의 원리
5. 하나님 찾기 (관찰)
- 바로의 마음을 완악하게 하여, 바로의 장자를 죽이려하심
- 모세에게 나타나 죽이려 하심
- 아론에게 광야로 가서 모세를 맞으라 하심
6. 인간 찾기 (관찰)
- 모세는 하나님으로부터 죽임 당할 위기에 처했으나 십보라가 자신의 아들의 포피를 베어 모세의 발에 갖다 대어 위기에서 벗어남
- 아론을 만나 하나님께서 명하신 일을 알리고 이스라엘 자손의 모든 장로를 모아 하나님의 말씀을 전하고 이적을 행하자 장로들이 머리숙여 경배함
7. 하나님 찾기 (해석) 
- 하나님은 악을 심판하시는 분이시다. 이스라엘 백성을 구원하시고자 애굽 왕을 심판하신 것도 있지만 바로는 하나님을 인정하지 않았다. 바로는 모세로부터 하나님의 기적을 경험했지만 돌이키지 않았다. 마치 현 시대를 살고 있는 우리처럼 하나님을 인정하지 않은 것이다.
- 하나님은 우리를 구원하시는 분이시다. 모세를 죽이려 하신 하나님이 선뜻 이해되지 않지만 하나님의 구원 사역에서 모세의 순종은 매우 중요한 부분이다. 자녀가 태어났을 때 포피를 베어내지 않는 불순종은 하나님과의 언약을 어긴 것이다. 십보라가 속히 자녀의 포피를 베어 모세에게 갖다 댄 것으로 보아 십보라도 이 사실을 정확히 알고 있었을 것이다. 
- 하나님께선 완벽한 순종을 원하신다. 악이 만연하고, 죄가 죄인지, 죄가 될 수 있는지 헷갈려하며 살아가는 이 시대에 우리가 죄를 멀리하고, 분별해야하는 명확한 이유이다. 하나님은 거룩한 분이기에 우리도 그분을 따라 거룩한 삶을 추구해야 한다.
8. 인간(해석):
- 이스라엘 백성들의 장로들은 모세와 아론을 통해 하나님의 말씀을 전달받고 소망이 생겼을 것이다. 하나님은 어려운 상황, 위기에 처한 우리를 지켜보지 않으신다.
9. 적용(나): 
- 적당히, 스스로 합리화하여 신앙생활을 하지 않도록 하나님의 특별한 은혜를 구해야겠다.
- 힘든 상황이어도 하나님을 의지하며 간구하는 기도를 계속해야겠다.
10. 영적터치(단어/구절)
피 남편
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-07', '출애굽기', '5장 1절~10절', '바로 앞에 선 모세', '출애굽기 5장
1   그 후에 모세와 아론이 바로에게 가서 이르되 이스라엘의 하나님 여호와께서 이렇게 말씀하시기를 내 백성을 보내라 그러면 그들이 광야에서 내 앞에 절기를 지킬 것이니라 하셨나이다
2   바로가 이르되 여호와가 누구이기에 내가 그의 목소리를 듣고 이스라엘을 보내겠느냐 나는 여호와를 알지 못하니 이스라엘을 보내지 아니하리라
3   그들이 이르되 히브리인의 하나님이 우리에게 나타나셨은즉 우리가 광야로 사흘길쯤 가서 우리 하나님 여호와께 제사를 드리려 하오니 가도록 허락하소서 여호와께서 전염병이나 칼로 우리를 치실까 두려워하나이다
4   애굽 왕이 그들에게 이르되 모세와 아론아 너희가 어찌하여 백성의 노역을 쉬게 하려느냐 가서 너희의 노역이나 하라
5   바로가 또 이르되 이제 이 땅의 백성이 많아졌거늘 너희가 그들로 노역을 쉬게 하는도다 하고
6   바로가 그 날에 백성의 감독들과 기록원들에게 명령하여 이르되
7   너희는 백성에게 다시는 벽돌에 쓸 짚을 전과 같이 주지 말고 그들이 가서 스스로 짚을 줍게 하라
8   또 그들이 전에 만든 벽돌 수효대로 그들에게 만들게 하고 감하지 말라 그들이 게으르므로 소리 질러 이르기를 우리가 가서 우리 하나님께 제사를 드리자 하나니
9   그 사람들의 노동을 무겁게 함으로 수고롭게 하여 그들로 거짓말을 듣지 않게 하라
10   백성의 감독들과 기록원들이 나가서 백성에게 말하여 이르되 바로가 이렇게 말하기를 내가 너희에게 짚을 주지 아니하리니

