4.주제 만들기: 바로 앞에 선 모세

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 모세와 아론이 바로 앞에 섬
- 하나님의 말씀을 전하는 모세와 아론
- 나는 하나님을 알지도 못하며, 그 말을 듣지 않겠다고 말하는 바로
- 모세와 아론이 하나님이 나타나셨고, 
- 광야로 사흘 길쯤 가서 제사를 드리려고 한다고 말함
- 어째서 백성의 노역을 쉬게 하려느냐 물으며, 
- 더욱 고된 노동을 하도록 명령하는 바로
- 감독과 기록원들이 나가서 바로의 명령대로 함

7.하나님 찾기 (해석) 

8.인간(해석)
- 모세와 아론은 용기를 내어 바로 앞에 섬
- 바로의 위세에 압도 되었지만, 용기를 내어 하나님의 말씀을 전함
- 그러나 바로가 하나님이 누군지 모르기에, 그 말을 따르지 않겠다고 말함
- 모세와 아론은 하나님이 나타나셔서 말씀하셨기에
- 우리는 사흘 길을 나가 제사를 드려야 한다라고 말하며,
- 그렇지 않으면, 우리가 벌을 받을 것이라고 말함
- 모세와 아론은 하나님을 직접 만났기에 하나님의 위대함을 알고, 경외심에 한 말이었지만,
- 바로는 알아 들을 수가 없음
- 바로의 이러한 반응은 하나님께서 모세에게 이미 말씀하신 것이었음
- 그러나 바로는 노역을 쉬게하려 한다며, 더욱 고된 노동을 시킬 것을 명령함
- 아마도 맹렬히 화를 내며 즉각적으로 명령했을 것이고,
- 감독과 기록원들이 즉각 명령을 수행했을 것이다.
- 이를 지켜본 모세와 아론은 그렇지 않아도 강제노동이 힘들어 백성들이 고통을 받고 있는데,
- 백성들이 더욱 심한 노동을 하게 되었으니,
- 일어난 일에 대해 당황스러움을 금치 못했을 것이며, 큰 걱정을 하게 되었을 것이다.
- 그러나 바로가 말을 듣지 않고 고집을 부릴 것을 하나님은 미리 말씀하셨다.

9.적용(나)
- 하나님의 말씀에 순종하여 일을 행할 때,
- 그 일의 과정이 순탄하지만은 않을 수 있다.
- 어려움이 있고 영육 간에 어려움을 당할 수 있다는 것을 기억하고,
- 오직 주님을 바라보고, 힘을 내어 맡겨진 사명을 감당해야 한다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-08', '출애굽기', '5장 11절~23절', ' ', '(출애굽기 5장)
11. 너희는 짚을 찾을 곳으로 가서 주우라 그러나 너희 일은 조금도 감하지 아니하리라 하셨느니라
12. 백성이 애굽 온 땅에 흩어져 곡초 그루터기를 거두어다가 짚을 대신하니
13. 감독들이 그들을 독촉하여 이르되 너희는 짚이 있을 때와 같이 그 날의 일을 그 날에 마치라 하며
14. 바로의 감독들이 자기들이 세운 바 이스라엘 자손의 기록원들을 때리며 이르되 너희가 어찌하여 어제와 오늘에 만드는 벽돌의 수효를 전과 같이 채우지 아니하였느냐 하니라
15. 이스라엘 자손의 기록원들이 가서 바로에게 호소하여 이르되 왕은 어찌하여 당신의 종들에게 이같이 하시나이까
16. 당신의 종들에게 짚을 주지 아니하고 그들이 우리에게 벽돌을 만들라 하나이다 당신의 종들이 매를 맞사오니 이는 당신의 백성의 죄니이다
17. 바로가 이르되 너희가 게으르다 게으르다 그러므로 너희가 이르기를 우리가 가서 여호와께 제사를 드리자 하는도다
18. 이제 가서 일하라 짚은 너희에게 주지 않을지라도 벽돌은 너희가 수량대로 바칠지니라
19. 기록하는 일을 맡은 이스라엘 자손들이 너희가 매일 만드는 벽돌을 조금도 감하지 못하리라 함을 듣고 화가 몸에 미친 줄 알고
20. 그들이 바로를 떠나 나올 때에 모세와 아론이 길에 서 있는 것을 보고
21. 그들에게 이르되 너희가 우리를 바로의 눈과 그의 신하의 눈에 미운 것이 되게 하고 그들의 손에 칼을 주어 우리를 죽이게 하는도다 여호와는 너희를 살피시고 판단하시기를 원하노라
22.  모세가 여호와께 돌아와서 아뢰되 주여 어찌하여 이 백성이 학대를 당하게 하셨나이까 어찌하여 나를 보내셨나이까
23. 내가 바로에게 들어가서 주의 이름으로 말한 후로부터 그가 이 백성을 더 학대하며 주께서도 주의 백성을 구원하지 아니하시나이다

