5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
이스라엘 백성을 더욱 학대하는 애굽왕 과 그의 감독들.
모세와 아론에게 분을 토하는 이스라엘 백성.
억울함을 여호와께 호소하는 모세.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
모세와 아론은 하나님의 명령대로 애굽 왕에게 이스라엘 백성을 놓아 달라고 말했다. 

이에 애굽왕의 반응은 매우 차가웠다. 도리어 이스라엘 백성들에게 더 심한 노역을 가했다. 심지어는 벽돌을 만들 때 기본적인 짚도 허락하지 않았다. 

이스라엘 백성들은 더 힘든 노역의 원인을 제공한 모세와 아론을 문책하였다.
이때 모세는 하나님께 억울함을 호소한다. 인간적인 측면에서 보면 모세는 매우 억울할 것이다. 본인이 원하지 않는 일을 명령받아 순종했는데 당장 펼쳐진 현실은 참담했다. 

특별히 모세는 내면에 잊고 살았던 트라우마가 떠올랐을 것 같다.
모세는 40년 전 같은 동족인 이스라엘 백성을 도우려다 그들의 같은 고발로 하루아침의 왕족에서 쫓겨나 도망자 인생이 되었다. 

그러한 아픈 부분을 하나님은 의도적으로 재현하는듯하시다. 하나님은 모세가 이스라엘 백성들을 출애굽의 대업을 완수하기 위해서는 내적 치유 부분이 중요하다고 여기신 것 같다. 

즉 모세 스스로 아픈 과거에서 빠져나와 용서와 사람의 사람으로 거룩한 하나님의 사람으로 승화된 모습으로 대업에 임하기를 바라시는 듯하다.

9.적용(나):
혹시 억울한 일을 겪더라도 모든 문제의 해결자 이신 하나님께 구하고 더욱 의지하는 삶을 살아야겠다. 

