4.주제 만들기: 하나님이 모세에게 말씀하심

5.하나님 찾기 (관찰)
- 모세에게 나타나 강한 손으로 바로에게 일을 행하시겠다 말씀하심
- 모세에게 나는 여호와니라 말씀하심
- 이스라엘 자손을 애굽에서 빼내어,
- 너희를 내 백성으로 삼고 나는 너희의 하나님이 되리라 말씀하심
- 가나안 땅으로 인도하고 그 땅을 이스라엘에게 주어 기업으로 삼게 하리라 말씀하시며
- 이를 백성들에게 전하라고 하심

6.인간 찾기 (관찰)
- 모세가 하나님께서 말씀하신 것을 백성에게 전함
- 백성이 고단하고 기가 죽어서 모세의 말을 듣지 않음

7.하나님 찾기 (해석) 
- 이제 전에 말씀하신 대로 바로를 강한 손으로 치시겠다 말씀하심
- 나는 여호와 너희의 주라고 말씀하시며,
- 아브라함과 이삭과 야곱에게 전능한 하나님으로 나타났었고,
- 그들에게 나의 이름이 여호와인 것을 알리지 않았다고 말씀하심
- 아브라함과 이삭과 야곱은 나의 전능함을 알지만, 
- 그들의 자손인 너희는 나를 경험하지 못해 나의 전능함을 알지 못한다고 말씀하신 것이고,
- 강한 손으로 역사함으로써 내가 여호와, 너희의 주됨을 보이시겠다고 말씀하시는 것
- 이스라엘의 신음소리를 듣고 내가 맺은 언약을 기억하고 있으며,
- 이제 애굽 사람으로 건지시겠다 말씀하심
- 여러 큰 심판들로써 이스라엘을 속량하여,
- 너희를 내 백성으로 삼고 나는 너희의 하나님이 되리라 말씀하셨는데,
- 하나의 심판이 아니라 여러 심판, 즉 여러 이적을 보이실 것을 먼저 말씀하신 것
- 이것은 여러 심판을 통하고 나서야만 
- 내가 전능한 하나님인 것을 
- 너희가 경험하여 알게 될 것이다 라고 말씀하시는 것
- 요셉이 죽고 몇 대가 지나면서 
- 하나님을 경험한 사람은 없어지고
- 애굽의 우상을 보며 살아온 백성들에게
- 너희가 듣던 아브라함과 이삭과 야곱의 하나님은 전설 속의 신이 아니라
- 바로 여호와, 너희의 주라는 것을 보여주고 각인시키고자 하심  

8.인간(해석)
- 모세는 백성들의 노동이 가중되고 그 원망을 듣게 되어 크게 실망했으나,
- 하나님의 나타나심과 말씀을 통해 다시 용기를 얻고 백성에게 하나님의 말씀을 전했다.
- 그러나 백성들은 가중된 노동에 고단하고 기가 죽어 모세의 말을 듣지 않았다.
- 몸이 너무나 고단하고 핍박에 기가 죽은 백성들에게 무슨 말이 들리겠으며,
- 모세의 말이 얼마나 듣기 괴로웠을까 싶다.
- 그들은 아직 하나님을 경험하지 못했기에 더욱 그랬을 것이다.
- 모세는 다시 한 번 좌절하며 실망하였을 것이다.

9.적용(나)
- 하나님은 모든 상황을 아시며,
- 일을 행할 계획을 갖고 계시며,
- 그 일을 성취하신다. 아니 그의 시간 속에서 성취하셨다.
- 그러나 사람은 그것을 알지 못하고, 
- 하나님의 계획을 신뢰하지 못하고,
- 진행되는 상황 속에서 고민하고 갈등하고 괴로워한다.
- 먼저는 하나님을 제대로 알지 못하는 인간의 한계 때문이고,
- 다음은 하나님을 경험하지 못했기 때문이다.
- 사람이 하나님을 이해할 수는 없지만,
- 모세처럼 하나님을 경험한 사람은
- 비록 두렵고 앞이 안 보이지만, 
- 그의 영광을 경험했기에 용기를 내어 말씀에 순종할 수 있다.

- 비록 상황이 어렵고 힘들더라도, 때로는 괴롭더라도, 
- 늘 옆에서 함께 하시는 전능하신 하나님을 기억하고 의지하고, 
- 그의 도우심을 기다리며 뚜벅뚜벅 내 길을 가야겠다.

10. 영적터치(단어/구절)  
  7   너희를 내 백성으로 삼고 나는 너희의 하나님이 되리니 나는 애굽 사람의 무거운 짐 밑에서 너희를 빼낸 너희의 하나님 여호와인 줄 너희가 알지라
