7. 하나님 찾기 (해석) 
- 하나님은 언약을 이루기 위해 그 분의 방식대로 일하신다. 우리의 생각대로라면 단번에 이스라엘 자손을 바로로부터 구원하면 될 일이지만, 하나님께선 이스라엘 백성에게 가장 유익한 방법을 택하신다. 
- 만약 하나님이 단번에 이스라엘 백성을 구원하셨다면 이스라엘 백성은 하나님을 여러 신들 중 한명으로 생각할 수 있다. 또한 그들이 현재 가진 문화가 이스라엘 백성을 또 무너지게 하는 악순환이 반복될 수 있다.
- 우리가 기억해야할 것은 하나님께선 가장 좋은 것을 우리에게 주시는 분이다. 
8. 인간(해석):
- 모세는 하나님의 명령을 따라 이스라엘 자손과 바로에게 담대히 선포했다. 그러나 그에게 돌아온 것은 바로의 무시와 이스라엘 자손의 원망이다. 이런 상황에서 하나님은 다시 모세에게 같은 명령을 내리신다. 모세는 얼마나 황당했을까? 더군다나 자신은 히브리 언어를 완벽히 구사하지 못하므로 이스라엘 자손들은 모세를 더욱 무시한다고 느꼈을 것이다. 
- 하나님은 인간에게 자신의 능력을 넘어서는 완벽한 순종을 원하신다. 자신의 능력 안에서 요구되는 순종은 누구나 할 수 있다. 하나님은 자신의 능력을 벗어나는 순종을 원하시는데 하나님을 전적으로 의지하게 만드는 하나님만의 방법인 것 같다. 
- 하나님은 분명히 말씀하신다. 너가 하는게 아니야. 내가 하는 거야. 너는 그냥 따라와. 
- 레위 지파의 자손인 모세는 선지자로서 역할을 아론은 제사장의 역할을 담당하므로 이스라엘을 이끌게 된다. 
9. 적용(나): 
- 하나님의 일에 집중하고, 순종하면, 하나님께서 알아서 우리를 가장 좋은 길로 이끄신다. 그것은 내가 생각하는 좋은 곳이 아닐 수 있다. 그러나 내 마음엔 기쁨과 평안이 가득할 것이다. 하나님께 집중하고, 그 분의 말씀에 순종하자.
10. 영적터치(단어/구절)
- 13 여호와께서 모세와 아론에게 말씀하사 그들로 이스라엘 자손과 애굽 왕 바로에게 명령을 전하고 이스라엘 자손을 애굽 땅에서 인도하여 내게 하시니라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-11', '출애굽기', '6장 21절~30절', '', '(출애굽기 6장)
21. 이스할의 아들들은 고라와 네벡과 시그리요
22. 웃시엘의 아들들은 미사엘과 엘사반과 시드리요
23. 아론은 암미나답의 딸 나손의 누이 엘리세바를 아내로 맞이하였고 그는 나답과 아비후와 엘르아살과 이다말을 낳았으며
24. 고라의 아들들은 앗실과 엘가나와 아비아삽이니 이들은 고라 사람의 족장이요
25. 아론의 아들 엘르아살은 부디엘의 딸 중에서 아내를 맞이하였고 그는 비느하스를 낳았으니 이들은 레위 사람의 조상을 따라 가족의 어른들이라
26. 이스라엘 자손을 그들의 군대대로 애굽 땅에서 인도하라 하신 여호와의 명령을 받은 자는 이 아론과 모세요
27. 애굽 왕 바로에게 이스라엘 자손을 애굽에서 내보내라 말한 사람도 이 모세와 아론이었더라
28.  여호와께서 애굽 땅에서 모세에게 말씀하시던 날에
29. 여호와께서 모세에게 말씀하여 이르시되 나는 여호와라 내가 네게 이르는 바를 너는 애굽 왕 바로에게 다 말하라
30. 모세가 여호와 앞에서 아뢰되 나는 입이 둔한 자이오니 바로가 어찌 나의 말을 들으리이까

