2025년 1월11일 출애굽기 6장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
자손/아들들: 21절 22절 24절 25절(2) 
아론과 모세/모세와 아론: 26절 27절
애굽왕 바로: 27절 29절 30절
모세: 28절 29절 30절
여호와: 28절 29절(2) 30절

4.주제만들기: 
리더로 선택받은 모세와 아론

5.하나님 찾기 (관찰)
명령하시는 여호와.
모세에게 애굽왕에게 출애굽을 선포하라 말씀하시는 여호와.

6.인간 찾기(관찰)
레위의 자손들(계보)
하나님 명령을 받는 모세와 아론.
여호와께 스스로 입이 둔한 자임을 나타내는 모세.

7.하나님 찾기(해석)
하나님은 모세뿐만 아니라 형 아론에게도 출애굽을 따로 미리 준비시켰음을 알 수 있다. 26절과 27절에 이름이 기록된 것을 보면 알 수 있다. 26절은 이름의 순서가 아론과 모세로 되어있고 27절에는 모세와 아론으로 순서가 바뀌어 기록되었다. 

모세가 많은 영향력을 끼치는 리더였지만 아론 또한 연합하는 자로써 중요한 인물임이 틀림이 없다. 어쩌면 성경은 출애굽을 시작하기 전에 어떠한 인물이 지나치게 영웅화되는 것을 방지하는 것이 아닌지 생각해보게 된다. 

즉 이스라엘 백성에게 출애굽을 하라고 받은 자나 애굽왕에게 그것을 전달하는 자보다 모든 것을 계획하시고 이행하시는 여호와가 진정한 영웅이요 왕이라는 사실을 상기시키는 듯하다.

야곱의 자녀들에 유언할 때 레위 자손에 대하여 축복의 내용보다는 저주에 가까운 내용이었다. 

그런데도 하나님은 레위 자손들 중 모세와 아론을 선택하시어 리더로 세우셨다. 왜 레위 자손들을 사용하셨을까?


하나님은 저주에 대하여 더디시고 축복의 말씀에 관해서는 빠르게 시행하신다. 이성적으로 하나님을 다 이해할 수 없지만 분명한 것은 하나님은 부족한 자녀라도 사용하실 수 있을 수 있으신 하나님이시다.

8.인간 찾기 (해석)

9.적용(나):
부족한 나를 탈북민 선교에 사용하시는 하나님을 찬양합니다!!
더욱 겸손히 열심을 품고 사명 감당해야겠다.

10. 영적터치 (단어 또는 구절)
29절: 나는 여호와라 

