7.하나님 찾기(해석)
하나님은 의기소침한 모세에게 바로 앞에 신 같은 존재로 여길 정도로 만들어 주겠다고 용기를 주고 계신다.

 모세의 형 아론에게는 바로 앞에서 대언자로 사용하시겠다고 역할 분담을 정확히 구분시켜 주신다.

