모세처럼 순종함에도 답답함을 잠시 겪더라도 잠시 참고 견디면 반드시 승리의 기쁨의 시간이 온다는 진리를 깨우치게 된다. 

전능하신 하나님은 모든 승리의 계획을 세우고 계시고 그대로 진행하시는 신실하신 하나님 이시기 때문이다. 이로써 애굽 백성조차도 여호와의 존재를 알게 된다.

