6. 인간 찾기 (관찰)
- 애굽 요술사도 지팡이를 던져 뱀을 만들었으나 아론의 지팡이로 만들어진 뱀이 다른 뱀들을 삼킴
- 바로의 마음이 완악하여 백성 보내기를 거절함
- 모세와 아론은 바로에게가 물에 나오게 하고 지팡이를 내밀어 나일강을 피로 변하게 함
7. 하나님 찾기 (해석) 
- 하나님께선 나일강을 피로 물들이셨다. 단번에 바로와 애굽을 정리할 수 있는 분이시지만 그 분의 계획 아래 순리대로 표적과 기적을 행하시며 바로와 애굽이 믿는 거짓 신이 아닌 참된 하나님임을 보여주신다.
- 인간은 상황 파악을 하지 못하는 어리석은 존재지만 하나님께선 그런 인간(우리)를 사랑하신다. 아무런 이유도 조건도 대가도 없이 우리를 사랑하신다. 
8. 인간(해석):
- 바로는 아론의 지팡이의 뱀이 다른 요술사의 뱀을 삼키는 것을 보았지만 대수롭지 않게 여긴다. 우리가 하나님의 뜻을 거스를 때 이런 모습이지 않을까? 하나님의 존재와 능력을 인정하지 않고 나의 생각, 나의 뜻대로 행동하는 교만을 저지른다.
- 바로는 자신이 신이라 생각했을 것이다. 하나님은 계속해서 이로 말미암아 네가 여호와인줄 알리라라고 말씀하시며 인정과 순종을 바라고 계신다. 단순하고 쉬운 일인데 마음이 완악해 있을 땐 그것을 파악하지 못한다. 교만함에 빠지면 안 되는 이유이다.
9. 적용(나): 
- 하나님의 말씀에 절대적으로 순종하자
- 내 생각보다 하나님의 뜻을 구하자
10. 영적터치(단어/구절)
- 마음이 완악하여
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

