4.주제 만들기: 계속되는 이적과 바로의 완악함

5.하나님 찾기 (관찰)
- 모세의 말대로 애굽 온 땅에 있던 개구리를,
- 집과 마당과 밭에서부터 나와 죽게 하심
- 땅의 티끌을 쳐 온 땅에 이가 되게 하라 명하심 
- 아침에 일찍이 일어나 바로 앞에 서서 백성을 보내라 명하게 하심

6.인간 찾기 (관찰)
- 모세와 아론이 개구리가 나일강에만 있게 하길 여호와께 간구함
- 사람들이 죽은 개구리를 모아 무더기로 쌓았으며
- 땅에서 악취가 감 
- 아론이 지팡이를 잡고 땅의 티끌을 침
- 요술사가 이를 생기게 하려 했으나 실패하고
- 이것은 하나님만 하실 수 있는 것이라고 말함
- 그러나 바로는 모세와 아론의 말을 듣지 않음
- 모세가 아침 일찍 바로 앞에 서라는 하나님의 말씀을 들음

7.하나님 찾기 (해석) 
- 모세의 간구를 들으시고 애굽 온 땅에 가득하던 개구리를 나일강에만 남게 하심
- 이것은 개구리가 명령대로 움직인 것으로 사람의 생각으로 이해할 수 없는 일이었음
- 백성들에게 조금씩 조금씩 자신의 위대하심을 나타내시는 것
- 땅의 티끌을 이로 변하게 하셨는데,
- 이것은 요술사들의 능력 또는 속임수로는 흉내 낼 수 없는 것으로,
- 하나님께서 자신의 권능을 본격적으로 나타내기 시작하심
- 바로를 완고하게 하심으로,
- 모세와 아론 그리고 이스라엘과 애굽 모든 백성에게
- 여호와 하나님을 분명하게 경험하게 하시고,
- 알게 하시는 것

8.인간(해석)
- 모세와 아론의 말대로 움직이고 죽는 개구리를 보고,
- 바로와 모든 백성은 놀라움을 금치 못했을 것임
- 그러나 바로는 문제가 해결되자,
- 모세와 아론의 말을 듣지 않았는데,
- 이것은 하나님께서 말씀하신 것과 같았다
- 땅의 티끌이 이가 되는 것을 보고 요술사들은 더는 흉내(요술 또는 속임수) 낼 수 없음을 깨닫고
- 이것은 하나님의 권능이라고 바로에게 말함
- 바로는 이것이 하나님의 권능을 보고 많이 놀랐으나,
- 마음이 완악하여 모세와 아론의 말을 듣지 않음
- 바로의 생각에는 더 강한 신도 있다고 생각하는 것이고,
- 이 정도 피해로 이스라엘(노동력)을 내보낼 수는 없다는 생각이 있었을 것.
- 모세와 아론의 입장에서는 하나님의 권능을 보고 감탄하고,
- 바로의 완악함, 소름 돋는 인간의 고집을 보고 놀라움을 금치 못했을 것이다
- 모세가 다시 하나님 앞에 서고, 그 말씀을 듣는다.
- 모세는 아마도 기대 반, 걱정 반의 심정으로 말씀을 듣고 있을 것이다. 

9.적용(나)
- 하나님이 완악하게 하신 자는 
- 하나님의 권능을 보고도 고집을 꺽지 않는다.
- 그러나 하나님은 이 완악한 자를 통하여 자신의 계획을 성취하신다.
- 내 주변에 이런 사람이 있을 수 있고,
- 주님이 주신 사명인데 일이 막힐 때가 있다.
- 이런 어려움이 닥쳤을 때 포기하지 않고,
- 주님과 동행하며 주님을 느끼며 맡겨주신 일을 끝까지 해내야 한다.
- 오늘도 내가 할 일을 묵묵히 해나가야겠다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-17', '출애굽기', '8장 21절~32절', '완악한 바로', '[출8:21-32]
21 네가 만일 내 백성을 보내지 아니하면 내가 너와 네 신하와 네 백성과 네 집들에 파리 떼를 보내리니 애굽 사람의 집집에 파리 떼가 가득할 것이며 그들이 사는 땅에도 그러하리라
22 그 날에 나는 내 백성이 거주하는 고센 땅을 구별하여 그 곳에는 파리가 없게 하리니 이로 말미암아 이 땅에서 내가 여호와인 줄을 네가 알게 될 것이라
23 내가 내 백성과 네 백성 사이를 구별하리니 내일 이 표징이 있으리라 하셨다 하라 하시고
24 여호와께서 그와 같이 하시니 무수한 파리가 바로의 궁과 그의 신하의 집과 애굽 온 땅에 이르니 파리로 말미암아 그 땅이 황폐하였더라
25 바로가 모세와 아론을 불러 이르되 너희는 가서 이 땅에서 너희 하나님께 제사를 드리라
26 모세가 이르되 그리함은 부당하니이다 우리가 우리 하나님 여호와께 제사를 드리는 것은 애굽 사람이 싫어하는 바인즉 우리가 만일 애굽 사람의 목전에서 제사를 드리면 그들이 그것을 미워하여 우리를 돌로 치지 아니하리이까
27 우리가 사흘길쯤 광야로 들어가서 우리 하나님 여호와께 제사를 드리되 우리에게 명령하시는 대로 하려 하나이다
28 바로가 이르되 내가 너희를 보내리니 너희가 너희의 하나님 여호와께 광야에서 제사를 드릴 것이나 너무 멀리 가지는 말라 그런즉 너희는 나를 위하여 간구하라
29 모세가 이르되 내가 왕을 떠나가서 여호와께 간구하리니 내일이면 파리 떼가 바로와 바로의 신하와 바로의 백성을 떠나려니와 바로는 이 백성을 보내어 여호와께 제사를 드리는 일에 다시 거짓을 행하지 마소서 하고
30 모세가 바로를 떠나 나와서 여호와께 간구하니
31 여호와께서 모세의 말대로 하시니 그 파리 떼가 바로와 그의 신하와 그의 백성에게서 떠나니 하나도 남지 아니하였더라
32 그러나 바로가 이 때에도 그의 마음을 완강하게 하여 그 백성을 보내지 아니하였더라

