4. 주제만들기: 완악한 바로
5. 하나님 찾기 (관찰)
- 애굽 사람의 집집에 파리떼를 보내심
- 이스라엘 백성이 거주하는 고센 땅에는 파리떼를 보내시지 않음
6. 인간 찾기 (관찰)
- 이스라엘 백성이 하나님께 제사를 드릴 수 있도록 요청하는 모세와 아론
- 파리 떼를 피하고자 애굽 땅에서 제사를 드리라고 말하는 바로, 그럴 수 없다는 모세의 말에 광야로 가되 멀리가지 말라고 말하였으나 파리 떼가 사라지자 마음을 완악하게 먹고 백성을 보내지 않는 바로
7. 하나님 찾기 (해석) 
- 하나님께선 구별하여 파리 떼를 보내셨다. 아마 이스라엘 백성들은 더 많은 노역과 부당한 일이 벌어질지 몰라 두려움에 있었을 것이다. 하나님은 이스라엘 백성들에게 자신의 존재를 드러냄과 동시에 희망과 용기를 주고자 하셨을 것이다. 
- 요셉 이후 하나님을 잊은 채 살아가던 이스라엘 백성에게 나타나셔서 표징을 보이신 하나님의 모습에 예수님의 모습을 떠올린다. 하나님은 구약에서도 우리를 위해 동일하게 나타나셨고, 많은 표적을 보이셨으나, 우리는 하나님을 의지하지 않았다. 하나님의 사랑도 동일하고 인간의 어리석음도 동일하다.  
8. 인간(해석):
- 바로는 세 번의 완악함을 보여주었다. 애굽 땅에서 제사를 드리는 것, 광야에서 멀리 나가지 말라는 것, 마음을 바꿔 이스라엘 백성을 보내지 않은 것이다. 완악함이 내면에 생기면 진리를 제대로 보지 못하고, 보더라도 인정하지 못하는 상태가 된다. 이만큼 안타까운 일이 있을까... 
9. 적용(나):
- 현 시대는 교회와 예수님의 존재에 대해 완악한 시선으로 바라보는 영혼들이 많다. 그들이 바로와 같이 죽음에 이르지 않도록 노방전도에 힘써야겠다. 
- 지금도 함께 하시는 하나님께 나는 과거 어리석은 인간처럼 행동하지 않도록 영적인 거룩함을 유지해야겠다.  
10. 영적터치(단어/구절)
- 구별하여
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-18', '출애굽기', '9장 1절~10절', '', '(출애굽기 9장)
1.  여호와께서 모세에게 이르시되 바로에게 들어가서 그에게 이르라 히브리 사람의 하나님 여호와께서 말씀하시기를 내 백성을 보내라 그들이 나를 섬길 것이니라
2. 네가 만일 보내기를 거절하고 억지로 잡아두면
3. 여호와의 손이 들에 있는 네 가축 곧 말과 나귀와 낙타와 소와 양에게 더하리니 심한 돌림병이 있을 것이며
4. 여호와가 이스라엘의 가축과 애굽의 가축을 구별하리니 이스라엘 자손에게 속한 것은 하나도 죽지 아니하리라 하셨다 하라 하시고
5. 여호와께서 기한을 정하여 이르시되 여호와가 내일 이 땅에서 이 일을 행하리라 하시더니
6. 이튿날에 여호와께서 이 일을 행하시니 애굽의 모든 가축은 죽었으나 이스라엘 자손의 가축은 하나도 죽지 아니한지라
7. 바로가 사람을 보내어 본즉 이스라엘의 가축은 하나도 죽지 아니하였더라 그러나 바로의 마음이 완강하여 백성을 보내지 아니하니라
8.  여호와께서 모세와 아론에게 이르시되 너희는 화덕의 재 두 움큼을 가지고 모세가 바로의 목전에서 하늘을 향하여 날리라
9. 그 재가 애굽 온 땅의 티끌이 되어 애굽 온 땅의 사람과 짐승에게 붙어서 악성 종기가 생기리라
10. 그들이 화덕의 재를 가지고 바로 앞에 서서 모세가 하늘을 향하여 날리니 사람과 짐승에게 붙어 악성 종기가 생기고

