1:감동받는 단어나 구절 찾기(영적터치)

2025년 1월18일 출애굽기 9장01절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
가축: 3절 4절 6절(2) 7절 
이스라엘 자손의 가축은 하나도 죽지 아니함: 4절 6절 7절
심한 돌림병/죽었으나: 3절 6절
백성을 보내지 아니함: 2절 7절
화덕: 8절 10절
재: 8절 10절
여호와: 1절 3절 4절 5절 6절 8절
모세: 1절 8절
바로: 1절 2절 7절 
악성 종기:9절 10절

4.주제만들기: 
가축의 죽음(재앙)

5.하나님 찾기 (관찰)
모세로  바로에게 가라고 명령하시는 여호와.
바로의 완강함으로 애굽의 가축들에게 재앙을 내리시는 여호와.
이스라엘 자손의 가축은 재앙을 피하도록 구분하신 여호와.
악성 종기의 재앙을 내리시는 여호와.

6.인간 찾기(관찰)
여호와의 명령대로 행하는 모세와 아론.
재앙이 있었지만 또다시 완강하여 이스라엘 백성을 보내지 않는 바로.

7.하나님 찾기(해석)
공의와 공정 그리고 자비를 행하시는 하나님을 보게 된다. 

먼저 공의의 여호와는 여러 번 반복되는 재앙에도 완강하여 대항하는 바로에게 계속해서 새로운 재앙을 행하셨다. 

다섯째 재앙으로는 애굽의 모든 가축이 죽는 돌림병과 악성종양을 사용하셨다.

공정 하나님의 모습은 ''구분''이라는 말에 함축된 듯하다. 고통받고 여호와를 찾는 이스라엘 가축에게는 재앙이 피해 가고 핍박하고 완강한 바로의 백성의 소유물인 가축들만 재앙을 받아 죽었다. 

정확하게 가축의 소유권을 구별하여 재앙을 칼처럼 가르는 것은 인간의 영역이 아닐 것은 분명하다. 전능하신 하나님은 부족하더라도 하나님을 찾는 백성들은 결국 보호해주시고 생명을 지켜주심을 알게 한다. 이것이 하나님 나라의 공정일 것이다.

자비의 하나님은 5절의 ''기한''이라는 단어로 예측할 수 있다. 심판의 목적은 결국 한정된 기한에 깨우치고 회개하며 주님의 뜻대로 행하라 하시는 큰 자비로부터 나온 하나님의 마음일 것이다.

공통점으로 하나님은 애굽왕 조차도 여호와께 돌아오고 그분이 진정한 왕이심을 간절히 깨우쳐 주시는 것 같다.

8.인간 찾기 (해석)
여러 번 반복되는 재앙에도 굽히지 않고 대항하는 바로 왕을 본다. 아주 안타까운 마음이 든다. 

자신의 완강한 고집 때문에 자신 백성들과 재산 같은 가축들이 죽었음에도 계속 하나님께 저항한다. 얼마나 마음이 완강하면 그럴 수 있을까? 

그러면서 나의 마음 상태를 생각해본다. 나 역시 마음이 단단하여 마치 콘크리트처럼 단단해지면 내 가정 그리고 사랑하는 NKFC 공동체를 힘들게 할 수 있겠다고 하는 경각심이 든다.

그러므로 늘 마음을 성찰하고 주님의 은혜 안에 살면서 마음이 늘 옥토 밭이 되도록 노력해야겠다.

9.적용(나):
늘 주님안에서 마음이 옥토밭이 되도록 3331큐티 와 기도생활에 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
5절: 여호와께서 기한을 정하여

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-19', '출애굽기', '9장 11절~20절', '', '(출애굽기 9장)
11. 요술사들도 악성 종기로 말미암아 모세 앞에 서지 못하니 악성 종기가 요술사들로부터 애굽 모든 사람에게 생겼음이라
12. 그러나 여호와께서 바로의 마음을 완악하게 하셨으므로 그들의 말을 듣지 아니하였으니 여호와께서 모세에게 말씀하심과 같더라
13.  여호와께서 모세에게 이르시되 아침에 일찍이 일어나 바로 앞에 서서 그에게 이르기를 히브리 사람의 하나님 여호와의 말씀에 내 백성을 보내라 그들이 나를 섬길 것이니라
14. 내가 이번에는 모든 재앙을 너와 네 신하와 네 백성에게 내려 온 천하에 나와 같은 자가 없음을 네가 알게 하리라
15. 내가 손을 펴서 돌림병으로 너와 네 백성을 쳤더라면 네가 세상에서 끊어졌을 것이나
16. 내가 너를 세웠음은 나의 능력을 네게 보이고 내 이름이 온 천하에 전파되게 하려 하였음이니라
17. 네가 여전히 내 백성 앞에 교만하여 그들을 보내지 아니하느냐
18. 내일 이맘때면 내가 무거운 우박을 내리리니 애굽 나라가 세워진 그 날로부터 지금까지 그와 같은 일이 없었더라
19. 이제 사람을 보내어 네 가축과 네 들에 있는 것을 다 모으라 사람이나 짐승이나 무릇 들에 있어서 집에 돌아오지 않는 것들에게는 우박이 그 위에 내리리니 그것들이 죽으리라 하셨다 하라 하시니라
20. 바로의 신하 중에 여호와의 말씀을 두려워하는 자들은 그 종들과 가축을 집으로 피하여 들였으나

