4.주제만들기: 
우박의 재앙

5.하나님 찾기 (관찰)
모세로 바로에게 가서 대언 하라 명령하시는 하나님.
악한 바로를 왕으로 세운 목적은 기회를 주어 여호와 이름을 온 천하에 전파하라는 목적이심.
우박의 재앙을 예고하시는 여호와.

6.인간 찾기(관찰)
여호와의 명령을 받는 모세.

7.하나님 찾기(해석)
하나님은 돌림병을 바로 와 그의 모든 백성에게 주어 멸망시킬 수 있으나 계속 스스로 깨우칠때까지 기다려주시는 부분이 있음을 보여준다. 

또 하나 다른 큰 목적은 명확하다. 하나님 이름이 온 천하에 드러나는 것이다. 바벨탑을 세워 저주받았던 인간들의 목적과 상반되는 것이다. 애굽 왕 바로를 왕의 자리에 세우시는 하나님의 목적처럼 현대를 살아가는 모든 사람이 높은 위치에 세워지는 목적도 확실시된 것을 깨우친다. 

인간들은 기본적으로 왕 되신 하나님을 만나고 그분을 온 천하에 드러나도록 힘쓸 때 가장 가치 있는 목적에 부합한 삶이라는 생각을 해본다. 

하나님이 허락하신 세상에서의 위치나 역할을 소중히 여기며 주님의 영광과 이름을 드러내는 삶이야말로 하나님이 원하시는 삶인 것 같다.

8.인간 찾기 (해석)

9.적용(나):
늘 여호와의 이름을 천하에 알리고 높이는 삶을 살아내야겠다. 그러므로 더욱 복음전도(마포대교 한강대교)에 힘쓰며 기회가 오면 세계 곳곳에 가서 대교 전도를 해야겠다.

