4. 주제만들기
5. 하나님 찾기 (관찰)
- 모세에게 명령하시고 하늘을 향해 손을 들어 애굽 온 땅에 우박을 내리게 하심
- 우렛소리와 우박을 보내시고 불을 땅에 달리게 하심
6. 인간 찾기 (관찰)
- 하나님의 명령에 따라 모세는 하늘 향해 손을 듬
- 이스라엘 백성의 땅 고센에는 우박이 내리지 않음
- 여호와를 마음에 두지 않은 사람은 종들과 가축들을 그대로 둠
- 우렛소리와 우박이 불에 섞여 내리고 사람과 짐승을 치고, 밭의 모든 채소와 나무를 꺾음
- 바로는 모세에게 사람을 보내 이번엔 자신이 범죄하였다고 말하며, 여호와는 의로우시고, 자신과 백성은 악하다고 고백함
- 모세는 성 밖을 나가 손을 펴고 우박이 그치면 세상이 여호와께 속한 줄 알 것이라고 바로에게 말함. 그러나 왕과 신하들은 아직도 하나님을 두려워하지 않는 것을 자신이 알고 있다 말함.
7. 하나님 찾기 (해석) 
- 하나님께선 친절히 바로에게 기회를 주셨다. 그리고 우박을 내릴 것이고, 죽임을 당할 것이라고도 말해주셨다. 하나님께서 애굽을 통해 세상이 하나님께 속한 것을 알리시고자 하시지만 완악한 인간에게 벌만 주시려한 것은 아니시다. 바로에게 다음 재난을 알려주심으로써 애굽 사람들이 피할 기회를 마련해주셨다. 
- 하나님께선 우리에게 사인을 주신다. 사인을 깨닫는다면 올바른 선택을 할 수 있고, 깨닫지 못한다면 어리석은 판단을 할 수 있다.  
- 지옥은 마치 이런 곳일까? 우렛소리와 우박과 불이 함께 내려져 있는 곳, 우박을 피하기 위해 움직이는 곳엔 불이 있을 것이다. 
8. 인간(해석):
- 바로는 현재 상황을 모면하기 위해 거짓된 고백을 한다. 우리는 어려움에 마주했을 때 하나님께 서원하듯이 기도하곤 한다. 마치 내가 하나님을 위해 이렇게 해주겠습니다라는 건방지고 교만한 기도내용을 포함한다. 
- 모세는 바로의 거짓 고백을 알아차린다. 영적으로 보는 안목이 생겼다. 그동안 바로의 완악함으로 하나님 앞에 엎드려 못하겠다고 고백하던 모세의 모습이 아닌, 담대한 모습이다. 하나님께서 함께 하신다는 확신이 들면 우리는 담대해질 수 있다. 
9. 적용(나): 
- 하나님께 건방지고 교만한 기도를 하지 않는지 점검하고 영적인 안목이 생겨 담대해지도록 기도해야겠다.
- 하나님께서 주시는 사인을 잘 깨닫고 하나님의 뜻을 따라가는 삶을 살아야겠다.
10. 영적터치(단어/구절)
- 이번은 내가 범죄하였노라 여호와는 의로우시고 나와 나의 백성은 악하도다
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

