4.주제만들기: 
메뚜기의 재앙 예고

5.하나님 찾기 (관찰)
모세로 바로에게 가서 대언 하라 명령하시는 여호와.
메뚜기 재앙을 예고 하시는 여호와.

6.인간 찾기(관찰)
여호와의 명령을 받들어 바로와 그의 신하에게 여호와 말씀을 전달하는 모세와 아론.
말을 받은 신하들은 두려워함.
반면 바로는 여전히 완강함.

7.하나님 찾기(해석)
요셉이 떠난 지 수백 년이 지난 다음 애굽 사람들은 과거 훌륭했던 국무총리 요셉을 잊을 뿐만 아니라 요셉과 함께하셨던 하나님을 알지 못했다. 

그 결과로 이스라엘 백성을 괴롭히고 나아가서는  재앙까지 받는 결과를 초래했다. 

반면 하나님은 재앙을 통해서라도 살아계신 여호와를 자손 대대로 전하고자 의지를 다지고 계심을 알 수 있다. 

하나님은 모든 인류 세대에게 관계성을 맺고 복을 주시기를 원하신다.

또한 하나님은 만약 바로가 또다시 거역한다면 메뚜기를 보내 남은 곡식도 다 망가뜨린다고 말씀하셨다. 

우박 재앙 때 하나님은 애굽 사람들이 최소 생존할 수 있는 식물을 남겨놓으셨다. 

고통 가운데에서도 회개할 기회를 주신 하나님의 의도를 알지 못하고 도리어 숨통이 트인 바로는 거역하는 쪽으로 방향을 맞추었다. 

우둔한 선택이다. 하나님이 주신 경고인가 아니면 선물인지를 분간을 못 한 죄인의 모습이다. 

나도  늘 삶 가운데 분별을 하여 끊어야 할 것과 이어갈 것을 알도록 힘써야겠다.

8.인간 찾기 (해석)

9.적용(나):
하나님 그분의 뜻대로 돌아가라는 음성에 늘 귀를 기울이고 순종하는 삶을 살아내야겠다.

