땅: 15(2)

4.주제 만들기: 메뚜기 재앙과 바로의 부분적 사죄

5.하나님 찾기 (관찰)
- 모세에게 손을 내밀어 애굽 땅에 메뚜기가 올라오게 하여,
- 남은 모든 채소를 먹게 하라 명하심
- 모세가 지팡이를 들매 동풍을 일으키심
- 바로의 사죄에 따른 모세의 간구함에 따라 메뚜기를 홍해로 몰아넣으시는 하나님
- 바로를 완악하게 하시는 하나님

6.인간 찾기 (관찰)
- 바로가 말씀을 어기고 장정만 가서 여호와를 섬기라 말하고
- 모세와 아론을 쫓아냄
- 모세가 하나님의 말씀대로
- 손을 내밀어 지팡이를 듦
- 동풍에 밀려오는 메뚜기와 땅에 가득한 메뚜기를 보는 모세와 이스라엘, 그리고 바로와 애굽 백성
- 모세와 아론을 급히 불러 내가 잘 못했다 사죄하는 바로
- 이 죽음만은 내게서 떠나게 하라 요청하는 바로
- 여호와께 구하는 모세
- 메뚜기가 홍해로 몰려가고 애굽 땅에 하나도 남지 않게 되자,
- 다시 완악해진 바로

7.하나님 찾기 (해석) 
- 메뚜기떼를 즉시 나타나게 하지 않으시고, 
- 동풍이라는 자연현상을 사용하시고, 
- 하루라는 시간을 이용하여 메뚜기가 나타나게 하시는 하나님
- 메뚜기떼가 몰려오게 하시고 애굽 땅에 남겨두었던 모든 채소를 제거하시는 하나님
- 애굽 땅을 전쟁으로 폐허가 된 곳보다도 더 폐허가 되게 하셔서 살 소망이 없게 하심 
- 바로의 사죄와 모세의 간구함으로 메뚜기떼를 애굽 땅에서 몰아내시지만,
- 뜻이 있으셔서 바로가 말을 듣지 않게 하심

8.인간(해석)
- 모세의 말에 화가 난 바로가 장정들만 광야로 가서 하나님을 예배하고 오라고 말함
- 모든 이스라엘 백성이 소유를 들고 나가면 돌아오지 않을 것을 예상하고 있는 것
- 하나님의 말씀대로 손을 내밀어 지팡이를 든 모세
- 급히 불어오는 동풍을 맞으며 메뚜기가 몰려올 것을 기다리는 모세
- 그동안 손을 들면 즉시 이적이 나타났는데,
- 즉시 나타나지 않는 메뚜기를 기다리며 여러 가지를 생각했을 모세
- 메뚜기떼가 나타나고 모든 것을 먹어치우자,
- 두려워서 급히 모세와 아론을 불러
- 하나님과 너희에게 죄를 지었으니 이번만 죄를 용서해 달라고, 
- 이 죽음만은 내게서 떠나게 해달라고 말하는 바로
- 죽게 된 것을 알게 되고 사죄하며 모세에게 부탁하는 바로를 보면,
- 하나님의 능력을 깨닫게 된 것을 알 수 있음
- 그러나 메뚜기가 사라지고 이제 살았다 하는 생각이 들자 다시 고집을 부리는 바로
- 바로는 메뚜기가 없으니 아직 살만하다 생각했을 것이며
- 하나님이 두렵지만 이스라엘 백성(내 재산)을 포기할 수 없다 라고 생각했을 것  
- 바로의 완악함은 하나님이 계획안에서 주신 것    

9.적용(나)
- 하나님은 즉시 이적이 나타나게도 하시고,
- 자연현상을 이용하고 시간 차를 두고 나타나게도 하신다.
- 이것을 기억하고 기다릴 줄 알아야 한다.
- 어떤 완악한 사람들은 하나님이 계획하신 만큼 완악한 것이고,
- 그들이 완악함은 하나님이 사용하시는 것이다.
- 그런 사람을 만났을 때 하나님의 뜻이 무엇인지 구하며 내가 할 수 있는 일을 해야 한다.
- 내가 할 수 있는 일은 하나님의 지팡이를 드는 것과 하나님의 역사를 기다리고 누리는 것이다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-24', '출애굽기', '10장 21절~29절', '하나님의 사람 모세', '[출10:21-29]
