4. 주제만들기: 하나님의 사람 모세
5. 하나님 찾기 (관찰)
- 모세에게 명령하여 손을 들게 한 후 애굽 땅 위에 흑암이 있게 하심
- 온 이스라엘 자손들이 거주하는 곳엔 빛이 있게 하심
- 바로의 마음을 완악하게 하심
6. 인간 찾기 (관찰)
- 흑암으로 애굽 사람은 서로 볼 수 없고, 처소에서 일어나는 사람이 없음
- 바로는 모세를 불러 여호와를 섬기되 가축은 남겨두고 가라 말함
- 모세는 바로에게 우리 하나님 여호와께 드릴 제사와 번제물을 주어야 하고 어떤 것으로 여호와를 섬길지 모른다고 말함
- 바로는 마음이 완악해져 모세에게 자기를 떠나라 말하며 다시 얼굴을 보면 죽이리라 말함
- 모세도 바로에게 다시는 당신의 얼굴을 보지 않으리라 말함
7. 하나님 찾기 (해석)
- 하나님께선 자신의 한 없는 능력을 보여주신다. 애굽 땅을 흑암 가운데 머무르게 하고, 온 이스라엘 자손이 머무는 곳엔 빛을 비춰주셨다. 우리가 소망을 볼 수 있는 것은 흑암과 같은 삶 가운데 우리에게만 비춰주는 빛이 있다는 것이다. 우리는 깨닫지 못하지만 하나님께선 예수님을 통해 우리에게만 비추는 빛을 주셨다. 어둠과 같은 세상에 예수님께서 오셔서 구원의 빛을 우리에게 비추어 주셨다. 
8. 인간(해석):
- 모세는 더 담대해졌다. 애굽의 왕 바로, 신이라고도 불리는 사람과 대면할 때 바로로부터 나오는 위엄에 전혀 밀리지 않는 모세를 본다. 하나님의 능력, 하나님의 임재를 경험한 모세는 죽음 따위는 무섭지 않은 존재가 되었다. 우리도 하나님의 능력, 임재를 경험했는데 세상 앞에 두려워할 필요 없다. 하나님을 의지하자.
- 바로는 흑암 가운데 이스라엘 자손에게만 비치는 빛을 알았을 것이다. 그럼에도 완악함에 사로잡혀 이스라엘 백성을 놓아주지 못한다. 알면서도 그것을 따르지 못하는 것, 그것보다 치명적인 영적 무지의 상태는 없을 것이다. 우리도 영적 무지의 상태에 빠지지 않도록 주의해야 한다.
9. 적용(나): 
- 구원의 빛을 감사하며 그분의 능력을 신뢰하고 그분만 의지하자.
- 영적 무지의 상태에 빠지지 않도록 말씀, 기도, 예배의 자리를 잘 지키자.
10. 영적터치(단어/구절)
- 온 이스라엘 자손들이 거주하는 곳에는 빛이 있었더라
11. 믿음과 회개 및 감사기도로 마무리
